window.__D("text/maamarei-admur-hazaken/c004",{"p":[[2100490386,"א\"ע בכדי שיוכל להיות מציאת נפרדים כו' וזה ההעלם נק' בשם לבוש מלכו\"ת וכמ\"ש ה' מלך גיאות לבש שנתלבש בהעלם מפני שצריך<sup data-n=\"2052\">68</sup> להיות מלך על עם כו' וכמ\"ש במ\"א וד\"ל.\n<b>והנה</b> מדת מלכותו ית' מתפשטת תמיד להחיות רוח שפלים מאין ליש בכל העולמות וא\"א כ\"א ע\"י לבוש מלכות כנ\"ל, א\"כ צריך שימשיכו לו בחי' לבוש זה המעלים ומסתיר כו' בכדי שיקרא מלך על עם כנ\"ל, הנה ההמשכה של אותו הלבוש מלכות הוא ע\"י מעשה המצות דוקא ולכך נקרא'<sup data-n=\"2053\">69</sup> המצוה בשם מצות המלך כידוע בזוהר ור\"מ וזהו ענין הברכה שעל מעשה המצוה באמרו אשר קדשנו במצותיו וציונו כו' פי' וציונו לעשות בחי' לבוש למלכות כו'. אך כיצד נעשה בחי' לבוש ע\"י קיום המצוה הענין הוא ע\"י בחי' קבלת מלכות שמים שיש בכל מצוה במה שמקבל ע\"ע עול מלכות שמים כענין וכולם מקבלים עליהם עול מלכות כו' והוא מה שמבטל א\"ע לעשות רצון ה' במצוה זו שהוא עושה כמאמר בטל<sup data-n=\"2054\">70</sup> רצונך מפני רצונו כו' וזהו הנק' קבלת עול מלכות שמים וכמ\"ש שום<sup data-n=\"2055\">71</sup> תשים עליך מלך כו' ובהיות שבזה העול מעורר למעלה שיתפשט מלכות שמים בבחי' אימה ויראה על כל הנבראים כמאמר וכולם<sup data-n=\"2056\">72</sup> מקבלים כו' לכך נק' המצוה בשם מצות המלך לפי שמעוררת למעלה בחי' מלך להיות ה' מלך גיאות לבש כו' והיינו בחי' הלבוש כי העול הוא צמצום ובטול הרצון ומעורר למעלה צמצום והסתר עצמותו ג\"כ וזהו שע\"י המצוה נעשה בחי' לבוש מלכות למעלה וזהו שאו' בברכת המצות אלקינו מלך העולם מפני שיקרא בשם מלך ע\"י קיום המצוה דוקא מטעם זה וד\"ל.\n<b>והנה</b> בזמן הגלות כתיב אלביש<sup data-n=\"2057\">73</sup> שמים קדרות ושק אשים כסותם, פי' שהלבושי' הם בתכלית הקדרות והחושך היפך הלבושים שממעשה המצות והענין הוא לפי דכמו שע\"י קבלת מלכות שמים שבכל מצוה נעשה לבוש להעלים האור בתוך הקדושה האלקי' כמ\"ש שום תשים עליך מלך כו' כנ\"ל, כך בהיפוך כשאין לו קבלת מלכות שמים באימה בשעה שעושה המצוה אזי יוצא האור והשפע לחיצונים כי שרש יניקתם נמשך מפריקת עול מלכות שמים שע\"י פריקת עול מלכות שמים מסתעפים כל המדות הרעות כנראה לעין ונעשה מזה כל הבנין דקליפה במדות ושכל כו' כי<sup data-n=\"2058\">74</sup> את זלע\"ז עשה האלקים כו' והגם שעושה המצוה בפ\"מ אם הוא בבחי' פריקת עול באותה שעה יש מקום לחיצונים לקבל יניקה מאותה ההשפעה ביחוד עליון שנעשה למעלה ע\"י המצות כי ידוע דרמ\"ח<sup data-n=\"2059\">75</sup> מ\"ע נק' רמ\"ח איברים דמלכא",[["2052","68","<b>מפני שצריך להיות מלך על עם</b>: ראה שער היחוד והאמונה פ\"ז."],["2053","69","<b>נקרא' המצות בשם מצות המלך</b>: אסתר ג, ג. ובזח\"ג קעה, ב."],["2054","70","<b>בטל רצונך</b>: אבות פ\"ב, מ\"ד."],["2055","71","<b>שום תשים עליך מלך</b>: פ' שופטים יז, טו."],["2056","72","<b>וכולם מקבלים</b>: ברכת יוצר."],["2057","73","<b>אלביש שמים קדרות</b>: ישעי' נ, ג."],["2058","74","<b>כי את זלע\"ז עשה האלקים</b>: קהלת ז, יד."],["2059","75","<b>דרמ\"ח מ\"ע נק' רמ\"ח איברים דמלכא</b>: ראה תיקוני זהר ת\"ל. וראה תניא פ\"ד ובליקוט פירושים ומ\"מ שם."]]],[2100490387,"והעשי' של המצוה הוא בחי' הלבוש לאבר כו' וכאשר יש קבלת מ\"ש בעשי' זו הרי הלבוש הזה נאה ומהודר להיות שאין החיצונים מגיעים שם כלל מטעם הנ\"ל אבל בפריקת עול מ\"ש מקבלים גם הם ומשחירים הם את הלבושים דמעשה המצות וזהו שאמר אלביש שמים קדרות כו' וכן כתיב אל<sup data-n=\"2060\">76</sup> תראוני שאני שחרחורת כנ\"ל, ופי' שמים<sup data-n=\"2061\">77</sup> היינו בחי' המצות כמו שהן מפורשים בתורה שנק' רמ\"ח איברים כו' והן כלולי' מאש<sup data-n=\"2062\">78</sup> ומים רצוא ושוב דהיינו חו\"ג כך כשר וכך פסול כך טמא וכך טהור כו' וכמ\"ש מימינו<sup data-n=\"2063\">79</sup> אש דת למו שהתורה<sup data-n=\"2064\">80</sup> ניתנה בשתי מדות הללו חו\"ג ולכך נק' התורה שמי\"ם כלומר א\"ש ומי\"ם יחד כו' ובפריקת עול שמי\"ם הללו מלובשים בלבוש החשוך והוא הנק' קדרו\"ת מפני יניקו' החיצונים כו' וד\"ל, וזהו שארז\"ל שהאומר אין לי [אלא] תורה אפי' תורה אין לו מפני יניקות החיצונים שמקבלים בתורה שבלא יראה כנ\"ל וד\"ל. וזהו בזמן הגלות דוקא שמתגברים יניקות החיצוני' בשמי\"ם העליונים מטעם פריקת עול כו' אבל בזמן בהמ\"ק אמר קומי לך רעיית\"י יפת\"י, פי' יפת\"י שמייפים בחי' האדם דלעילא ע\"י מעשה המצות כשהן בקבלת עול מ\"ש מטעם הנ\"ל וכמ\"ש עוז<sup data-n=\"2065\">81</sup> והד\"ר לבוש\"ה כו' דהיינו בחי' לבוש מלכות הנ\"ל וכמ\"כ כתיב הו\"ד<sup data-n=\"2066\">82</sup> והד\"ר לבש\"ת כו' מטעם שהעול מלכות מייפה למדת מלכות כי אין מלך בלא עם כנ\"ל וד\"ל. וזהו שסמך ב' דברים הללו זה אצל זה דהיינו רעיית\"י ואח\"כ יפת\"י שהן ב' המדרגו' דתורה ומצות מפני שזה מזון וזה לבוש והלבוש מייפה כנ\"ל וד\"ל.\n<b>וזהו</b> יונתי בחגוי הסלע בסתר המדריגה כו' שזה נאמר בזמן הגלות דוקא, דהנה מ\"ש כי הנה הסתי\"ו עבר כו' על זמן יצ\"מ נאמר דכתיב לכתך<sup data-n=\"2067\">83</sup> אחר\"י במדבר כו' וכמ\"ש אחרי<sup data-n=\"2068\">84</sup> ה' תלכו פי' בבחי' אחוריי' וחיצוניו' בלבד עד שהנצנים נראו כו' והתאנה חנטה כו' אזי אמר קומי לך רעיית\"י יפתי דהיינו זמן מ\"ת וקיום המצות שהן מזון ולבוש כנ\"ל, ואח\"כ אמר יונת\"י בחגוי הסלע כו' שהוא בזמן הגלות והענין הוא כך משום שבתחלה אמר קומי לך כו' דהיינו ענין ההעלאה למעלה ע\"י התפלה שנק' סולם עד שישראל עלה במחשב\"ה הקדומה כנ\"ל אבל בזמן הגלות א\"א לכנ\"י לעלות כ\"כ מצד עצמה לפי שאין כח לעלות כלל והמשיל הדבר כמו עד\"מ היונה המסתתרת א\"ע בבקעי הסלע מפני השמש או השלג וכיוצא שבהיות היונה טמונה בעומק הבקעי' בודאי מתצמצמת בעצמה לבלתי תתפשט אגפיה לפרוח והנמשל מובן למעלה בכללות נש\"י שנמשלה ליונה כידוע שבזמן הגלות אין ביכולתה לעלות בבחי' אוי\"ר שנק' גדפין כידוע לפי שמסתתרת בחגוי הסלע בסתר",[["2060","76","<b>אל תראוני שאני שחרחורת</b>: שה\"ש א, ו."],["2061","77","<b>שמים היינו בחי' המצות</b>: ראה תו\"א מקץ (לה, א). שם סע\"ג. שערי אורה שער החנוכה נ, ב ואילך."],["2062","78","<b>מאש ומים רצוא ושוב</b>: ראה ג\"כ תו\"א עג, ד. לקו\"ת חקת נו, ב. שה\"ש יח, ג."],["2063","79","<b>מימינו אש דת למו</b>: ברכה לג, ב."],["2064","80","<b>שהתורה. . חו\"ג</b>: ראה שער היחוד והאמונה פ\"ה."],["2065","81","<b>עוז והדר לבושה</b>: משלי לא, כה."],["2066","82","<b>הוד והדר לבשת</b>: תהלים קד, א."],["2067","83","<b>לכתך אחרי במדבר</b>: ירמי' ב, ב."],["2068","84","<b>אחרי ה' תלכו</b>: פ' ראה יג, ה."]]],[2100490388,"המדרגה כלומר אע\"פ שבאוי\"ר הנק' גדפין הי' ביכולת כל ניצוץ האלקי לעלות ולהדבק בעצמו' אור א\"ס אך מפני שהגלות מקום צר הוא עד\"מ נקיקי הסלעים לא תוכל להתפשט בגדפין דאוי\"ר כלל והיינו מפני שיעבוד מלכיות ועול הפרנסה אשר בא בקושי גדול גם שיש לה גדפין אבל בסיבת המצוק לא תוכל לפשוט ולפרוח בהן עד\"מ והרי ידוע דבלא דו\"ר לא פרחא לעילא כמ\"ש בזוהר וד\"ל.\n<b>וזהו</b> יונתי בחגוי הסלע כו' הראיני<sup data-n=\"2069\">85</sup> את מראייך כו' פי' אחר שיונת\"י בחגוי הסלע בזמן הגלות וא\"א לה לעלות מעצמה להיות קומי לכ\"י כף יו\"ד כנ\"ל זאת היא העצה היעוצה להיות לה תקומה לכנ\"י באופן אחר והוא במה שאמר הראיני את מראייך כו' פי' מראיי\"ך דהנה כנ\"י דלעילא נק' בשם מראה כמ\"ש מראה<sup data-n=\"2070\">86</sup> דמות כבוד ה' ואראה מראות אלקים כו' וכמ\"ש<sup data-n=\"2071\">87</sup> בזוהר דאית מראה כו' ובחי' כללו' נש\"י מפני שהוא בחי' מל' דאצי' למעלה נק' מראה דמות כבוד הוי' פי' כמו עד\"מ המראה הגשמית דהנה אנו רואים בסיבת המראה בזכוכית לבינה וכיוצא שכאשר היא דבוקה מאחריה בדבר מה המחשיך כמו כסף לבן שמדביקין באחורי המראה אזי כשמסתכלין במראה אותה הצורה המסתכלת נראית בה מפני שחוזרת להראות אותה הצורה המסתכלת וידוע שסיבת חזרת האור הזה להראות בא דוקא מפני שדבקו מאחוריה דבר מה המונע ומעכב על בהירות הזכוכית לבלתי תתפשט עוד ע\"כ כשמסתכלין בה חוזר האור לאחוריו לפי שהדבק אשר מאחריה אינו מניח התפשטות האור יותר א\"כ בהכרח שיחזור האור לנגד דבר המסתכל בה ע\"כ בא סיבת חזרת האור להראות הצורה המסתכלת. והנה יש בזה תנאי עוד והוא בהמסך הדבוק מאחוריה שלא יהי' מדבר גס ועב אלא יהי' דק וקלוש דוקא כמו כסף לבן וכיוצא ואם הדבק בדבר גס ועב מאד לא יהי' סיבת חזרת האור כלל כידוע. והנמשל מכל זה יובן למשכיל למעלה דהנה מבואר למעלה דשרש ענין ירידת הנשמה בגוף היתה לצורך עלי' דוקא כו'.\n<b>וביאור</b> הדברים הנה עד\"מ המראה הנ\"ל דמפני סיבת הדבק הדבוק מאחריה חוזר האור כו' כך ע\"י שירדה הנשמה בגוף וחומריות הגוף מחשיך עליה מאד לפי שחומריות הגוף נלקח מד' יסודות גשמיים דנוג\"ה דעשי' כידוע ושרש<sup data-n=\"2072\">88</sup> הנשמה היא חלק אלוה ממעל ע\"כ מפני זה בא בנפש האלקי' בחי' אור חוזר למעלה דהיינו שעי\"ז תכסוף ותשתוקק לצאת מנרתק החומרי שלא יסתיר וכמ\"ש ויצעקו<sup data-n=\"2073\">89</sup> אל ה' בצר להם כו' ועולה היא במעלת הדביקות וההתקשרות למעלה ברום המעלות דהיינו להדבק ולהכלל בעצמות אא\"ס דוקא כי כל בחי' אור חוזר חוזר לקדמותו למקום שנלקח משם והיינו כמו שעלה ישראל במחשב\"ה בעצמו' אור הא\"ס כנ\"ל וסיבת עלי' גדולה הזאת הנה היא באה רק מפני המונע ומעכב עלי' להתפשט ולירד",[["2069","85","<b>הראיני את מראייך</b>: שה\"ש ב, יד."],["2070","86","<b>מראה דמות כבוד ה'</b>: יחזקאל א, כח."],["2071","87","<b>וכמ\"ש בזהר דאית מראה</b>: ראה זהר בהקדמה יא, ב."],["2072","88","<b>ושרש הנשמה היא חלק אלוה ממעל</b>: ראה תניא רפ\"ב."],["2073","89","<b>ויצעקו אל ה'</b>: ראה תהלים קז, ו."]]],[2100490389,"עוד כמשל הדבק שאחורי המראה והוא מחשך חומריו' עוה\"ז וא\"כ ירידה זו דוקא היא שעשתה העלי' הזאת משא\"כ אם לא ירדה הנשמה בגוף לא היתה ביכולתה לעלות כ\"כ מטעם שאין בחי' א\"ח אלא כשיש דבר המעכב כו' כמשל המראה ואם אין מעכב היא יורדת ואין לה עלי' כלל כו' והיינו שארז\"ל יפה<sup data-n=\"2074\">90</sup> שעה א' בתשובה ומע\"ט מכל חיי העוה\"ב פי' דהגם שחיי העוה\"ב הוא שנהנין מזיו כו' זהו בסדר הבריאה במדה שנמדד לכל חד לפום שיעורא דילי' אבל כדי שתעלה הנפש להדבק בעצמו' אור א\"ס שלמעלה מכל ההשתלשלו' והוא שתקרא טהור\"ה לפני בחי' בריא' שאתה בראת' כנ\"ל אין זה אלא מצד התלבשו' הנפש בגוף דוקא שבאת עי\"ז לידי תשוב\"ה דהיינו תשוב ה\"א בבחי' א\"ח מטעם הנ\"ל לפי שהגוף מחשיך ואז תגיע למעלה יתירה שאינה בסדר השתלשלו' כלל אפי' בחיי העוה\"ב כו' וזהו יפה שעה א' בתשוב\"ה ומע\"ט פי' המעשים הן טובים דהיינו מאירים וכמ\"ש וירא<sup data-n=\"2075\">91</sup> אלקים האור כי טוב כו' ואם לא סיבת התשוב\"ה הזאת אין המעשה של המצוה מאירה כ\"כ מטעם שהתשוב\"ה היא בחי' א\"ח כמ\"ש ויצעקו אל ה' צעק לבם כו' והיינו שאמרו ז\"ל דבע\"ת<sup data-n=\"2076\">92</sup> גדולי' גם מצדיקים גמורים ואמרו בזוהר הטעם משום דמשכין<sup data-n=\"2077\">93</sup> לי' לקודב\"ה בחילא יתיר פי' חילא יתיר היינו מפני בחי' א\"ח שעולה בכח גדול מאד וכענין ופרעה<sup data-n=\"2078\">94</sup> הקריב הקריב לבם כו' כמ\"ש במ\"א. אך זהו בתנאי שהמסך המבדיל הוא מדבר דק וקלוש כמשל הדבק שאחורי המראה ולא מסך עב וגס. והענין הוא דכתיב עוונותיכם<sup data-n=\"2079\">95</sup> מבדילים כו' הן מסך מבדיל עב וגס מאד ולא יוכל להיות בנפש אלקי' בחי' א\"ח בתשובה אלא רק מבחי' מסך קלוש דוקא והוא כמו דברים המותרים בתאוות היתר שהוא מבחי' קליפת נוג\"ה מעורב טו\"ר ואינו איסור גמור אבל הוא מחשיך קצת וה\"ז כמשל כסף לבן הקלוש שדבוק באחורי המראה כנ\"ל וד\"ל.\n<b>וזהו</b> המשך הפסוקי' כי הנה הסתי\"ו עבר כו' זהו בזמן יצ\"מ כנ\"ל ואח\"כ קומי לך רעיית\"י יפת\"י והכתיב לכ\"י היינו בחי' התורה והמצות ואח\"כ בזמן הגלות שא\"א לקום העצה היא הראיני את מראייך פי' בבחי' תשוב\"ה כדי שיבא האור בבחי' א\"ח למעלה כנ\"ל וזהו הראיני את מראיי\"ך ומה שאמר מראייך ב' מראות הענין הוא לפי שיש ב'<sup data-n=\"2080\">96</sup> מיני תשובה הא' תשובה עילאה והוא כענין התפלה ברעותא דלבא ע\"י ההתבוננות כנ\"ל שנק' סולם כו' והב' תשובה תתאה ע\"י שיצעקו בצר להם כנ\"ל וזהו תשוב<sup data-n=\"2081\">97</sup> ה\"א עילאה ותשוב ה\"א תתאה והכל בבחי' א\"ח כדי שיבא הצורה המסתכלת בה לנגד כנ\"ל וד\"ל. ואח\"כ אומר השמיעני את קולך כי קולך ערב ומראיך נאוה פי' אחר שאמר העצה בתשובה שתהא בבחי' א\"ח כמו במראה כנ\"ל",[["2074","90","<b>יפה שעה א' בתשובה ומע\"ט</b>: אבות פ\"ד מי\"ז."],["2075","91","<b>וירא אלקים האור כי טוב</b>: בראשית א, ד."],["2076","92","<b>דבע\"ת גדולים גם מצדיקים</b>: ראה ברכות לד, ב. הערת כ\"ק אדמו\"ר בסה\"מ ה'תש\"ט ע' 183-4."],["2077","93","<b>דמשכין לקוב\"ה בחילא יתיר</b>: זח\"א קכט, ב. אגרת התשובה פ\"ח."],["2078","94","<b>ופרעה הקריב הקריב לבם</b>: בשלח יד, י. ראה שמו\"ר פכ\"א, ה. זהר לך פא, ב. בשלח מז, א."],["2079","95","<b>עונותיכם מבדילים</b>: ישעי' נט, ב."],["2080","96","<b>ב' מיני תשובה</b>: ראה אגרת התשובה פ\"ו. פ\"ח. פ\"ט."],["2081","97","<b>תשוב ה\"א</b>: ראה זהר נשא קכב, א."]]],[2100490390,"אמר עוד שעי\"ז יהי' קולך ערב ומראך נאוה כלומר שבא לפרש וליתן טעם למה שקדם בעצה זו דתשובה באמרו הראיני את מראייך כו' שעיקר הכוונה הוא שיהא דוקא יתרון האור בתוספת גילוי מכמו שהי' בראשונה דאם לא יהי' יתרון אור הרבה מכמו שהי' מהו התועלת בירידת הנשמה בגוף כדי שתבא לבחי' תשובה כו' וענין היתרון הזה הוא במה שאמר כי קול\"ך ער\"ב ומראך נאוה, פי' קול\"ך ער\"ב כוונתו בתו' שנקראת מזון לנפש האלקי' כנ\"ל בפי' רעיי\"תי כו'.\n&lt;קט&gt;"],[2100490391,"<h3>להבין שרשי הדברים הנ\"ל</h3>\n<b>בעזר\"ה.</b>\n<b>להבין</b><sup data-n=\"2082\">1</sup> שרשי הדברים הנ\"ל. הנה שרש ענין ישראל<sup data-n=\"2083\">2</sup> עלה במחשבה וענין ותורה<sup data-n=\"2084\">3</sup> שם בישראל בשביל<sup data-n=\"2085\">4</sup> ישראל שנק' ראשי\"ת כו'. יובן בהקדים הפסוק כי<sup data-n=\"2086\">5</sup> לא מחשבותי מחשבותיכם פי' אין לדמות בדמיון וערך מחשבה של אדם לבחי' מחשבה עליונה ואע\"פ שבצלם<sup data-n=\"2087\">6</sup> אלקי' עשה את האדם כידוע אבל בבחי' המחשבה למעלה באלקו' הוא בהיפוך מבאדם למטה כו', דהנה המחשבה<sup data-n=\"2088\">7</sup> נק' נהר וכידוע בפי' ונהר<sup data-n=\"2089\">8</sup> יוצא מעד\"ן כי כמו הנהר שנובע מן מקורו והולך בתמידות לא ינוח כו' כך בחי' המחשבה<sup data-n=\"2090\">9</sup> היא משוטטת ונובעת בתמידו' מן השכל ולא תנוח אפי' רגע כידוע והנה אנו רואי' בחוש שהמחשבה לא תפעול שום פעולה מורגשת ולא תעשה רושם כלל כמו הדיבור כי במחשבה שיחשוב באיזה דבר מה ויציירנו במחשבתו לא עשה שום רושם מורגש באותו הדבר אלא הדבר נבדל אבל בדיבור שידבר ירגיש ויפעול פעולה מורגשת באותו הדבר כידוע דהרהור<sup data-n=\"2091\">10</sup> לא עביד מידי ועיקר ההתגלות",[["2082","1","<b>להבין שרשי הדברים הנ\"ל</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (ג, א). המאמר מחולק לאותיות והאותיות עצמם הם בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ. ונמצא בכת\"י 420 צב, א. 611 ד, א (חסר התחלה). 2045 צט, א בכותרת: ביאור שני על יונתי. נדפס בשינויים ובהגהות בלקו\"ת שה\"ש יז, ג.\nבגוכתי\"ק הנ\"ל נמצא כמה דפים בודדים מגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ, ואחד מהדפים הוא הגהות על ביאור זה (שם ע' קפ, ב). והגהות הם מחולק על כל הז' אותיות שבמאמר.\nרק ההגהות (מגוכתי\"ק 1025) נדפס ג\"כ באוה\"ת שה\"ש כרך ג' ע' תתצא ואילך.\nוראה לקמן ע' שנ. ביאור שני לדרוש ע\"פ יונתי. ֿ. ליל שבת פ' צו."],["2083","2","<b>ישראל עלו במחשבה</b>: ב\"ר רפ\"א. זח\"ב קיט, סע\"א. ובזח\"א א, ב. כד, א. ובכ\"מ."],["2084","3","<b>ותורה שם בישראל</b>: תהלים עח, ה."],["2085","4","<b>בשביל ישראל שנק' ראשית</b>: רש\"י ורמב\"ן ר\"פ בראשית. וראה ב\"ר פ\"א, ד. ויק\"ר פל\"ו, ד."],["2086","5","<b>כי לא מחשבותי מחשבותיכם</b>: ישעי' נה, ח."],["2087","6","<b>שבצלם אלקים עשה את האדם</b>: בראשית ט, ו."],["2088","7","<b>המחשבה נק' נהר</b>: ראה זהר (אדרא דמשכנא) משפטים קכג, ב."],["2089","8","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["2090","9","<b>המחשבה היא משוטטת ונובעת בתמידות</b>: ראה לקו\"ת בהר מא, סע\"א. סידור שער הל\"ג בעומר שה, סע\"א ואילך. ביאוה\"ז בראשית ב, א. וישב כא, ג. נשא פט, ריש ע\"ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ס\"ע רסב ואילך."],["2091","10","<b>דהרהור לא עביד מידי</b>: ראה ברכות כ, ב. תניא רפל\"ח."]]],[2100490392,"וההרגשה הוא בקול הדיבור דוקא להיות כי קול הדיבור מורגש הוא יותר כו' אבל למעלה באלקו' נהפוך הוא ששם בחי' המחשבה העליונה עושה יותר פעולה מורגשת להיות בחי' התהוו'<sup data-n=\"2092\">11</sup> דבר מה מן המחשבה הרי יהי' בו יותר התפשטו' והתגלו' החיו' מאור האלקי ויהי' הרבה גבוה במעלה ומדרגה מבחי' התהוו' דבר שמן בחי' דיבור העליון וכידוע שכל פרטי ההשתלשלו' דאבי\"ע וכל העליו' וירידו' בג\"ע עליון ותחתון עד אחר תחיית המתים ואלף הז' הכל נתהווה רק במחשבה אחת למעלה כמ\"ש בזוהר<sup data-n=\"2093\">12</sup> בראשית שנק' מחשבה אחת ובה צופה ומביט עד סוף כל הדורו' בסקירה א' כו' אך כשבא השפע בבחי' הדיבור העליון הוא שנתצמצם האור ונחלק לחלקי' רבים במיעוט האור מיעוט אחר מיעוט עד שבא לבחי' זמן להיו' שנים וחדשי' וימי' והן שיתא<sup data-n=\"2094\">13</sup> אלפי שני דהוי עלמא כו' ואותן ו' אלפי' שנה למעלה כתיב כי<sup data-n=\"2095\">14</sup> אלף שנה כיום אתמול כו' כיום בלבד נחשב ועוד יותר למעלה דהיינו בבחי' מחשבה אחת שצופה ומביט בה כללו' הכל כא' הרי בסקירה אחת הוא ואינו אלא רגע כו' וא\"כ נמצא מובן שלמעלה בחי' המחשבה כוללת השפע במעלה היותר גבוה הרבה מבדיבור עד שגם כל פרט דבר שעלה תחלה במחשבה יש בו חיו' ואור מכמו שהוא בדיבור וכידוע שיש כל בחי'<sup data-n=\"2096\">*14</sup> דצח\"ם גם באצי' ובודאי בחי' התפוח שבאצי' יותר יש בו אור וחיו' מתפוח דבריא' לפי שערך האצי' עם הבריא' הוא כדמיון המחשבה עם הדיבור כידוע שבדבר<sup data-n=\"2097\">15</sup> ה' שמים נעשו כו' וד\"ל וזהו כי לא מחשבותי מחשבותיכם שהרי במחשבה של אדם אין הענין כמו במחשבה עליונה כנ\"ל אבל מחשבותי שם הוא יותר התפשטו' האור והחיו'<sup data-n=\"e31\">*</sup> כנ\"ל.\n<b>ב</b> והנה כשאנו אומרי' שישראל עלה במחשבה היינו בבחי' מחשבה אחת הנ\"ל והוא הנק' מחשבה הקדומה כידוע והטעם שישראל דוקא &lt;קי&gt;\nעלה במחשבה זו הקדומה כו' הנה יובן בהקדים תחלה כללו' ענין הכונה שהיה ברצון המאציל להאציל ולברוא כו' כל ההשתלשלו' הנ\"ל בהיות ידוע שעיקר הכונה הי' בשביל שיהא לו דירה<sup data-n=\"2098\">16</sup> בתחתונים דוקא והיינו בחי' גילוי אלקו' בעולמות הנפרדי' בי\"ע דוקא ולא בשביל הגילוי אור שבאצי' גם בבחי' הכלים דשם כי מאחר דבאצילו' הרי",[["2092","11","<b>התהוות דבר מה מן המחשבה</b>: ראה לקו\"ת כאן (יז, ד) שמציין — וכמ\"ש כ\"ז בפרדס (שער הצחצחות פ\"ג)."],["2093","12","<b>זוהר. . מחשבה אחת ובה צופה ומביט עד סוף כל הדורות</b>: ח\"ב כ, א. וראה הנסמן בהמ\"מ ללקו\"ת עקב טז, ד."],["2094","13","<b>שיתא אלפי שני דהוי עלמא</b>: ר\"ה לא, א."],["2095","14","<b>כי אלף שנה כיום אתמול</b>: תהלים צ, ד."],["2096","*14","<b>בחי' דצח\"ם גם באצילות</b>: ראה ביאוה\"ז נשא פט, א ואילך. סה\"מ תקס\"ב ע' קיג. אוה\"ת וישב כרך ו תתרצה, א."],["2097","15","<b>שבדבר הוי' שמים נעשו</b>: תהלים לג, ו."],["2098","16","<b>דירה בתחתונים</b>: תניא רפל\"ו. וראה הנסמן בליקוט פירושים שם."],["e31","*","<b>והחיות כנ\"ל</b>: הגהות כ\"ק אדמו\"ר הצ\"צ על סעיף א' — כי לא מחשבותי, מחשבה נהר, למטה הרהור לא עביד מידי, למעלה במחשבה א' צופה ומביט עד סוף כל הדורות בסקירא א', והתהוות זמן בבחי' דיבור (מלך מלך וימלוך), ובמדות אלף שנים כיום היינו מדה א', ובמחשבה סקירא א' א\"כ לא מחשבותי כו'."]]],[2100490393,"איהו<sup data-n=\"2099\">17</sup> וחיוהי וגרמוהי חד כו' הכל בבחי' א\"ס כי גם הכלים שנק' גרמוה\"י אין הענין שלהם כמו בחי' בריאה מוגבלת ממש יש מאין אלא הם בבחי' א\"ס בבלתי גבול רק שהם כחו' אלקיי' המצמצמי' האור וכל שהוא בבחי' אצי' הרי עדיין הוא בחי' אלקו' ממש כידוע וא\"כ הגילוי שם אין זה בבחי' נפרד מעצמותו עדיין ועיקר הכונה הי' שיתגלה כבוד\"ו בנפרדי' יש מאין דוקא וכמ\"ש ונגלה<sup data-n=\"2100\">18</sup> כבוד ה' וראו כל בשר כו' שעיקר<sup data-n=\"2101\">19</sup> הכבוד הוא לרחוקי' כו' כמ\"ש במ\"א וד\"ל אך הנה ע\"י מה נעשה לו דירה זו בתחתוני' אחר שירדו להיו' בבחי' נפרד דוקא כו' הענין הוא מפני שע\"י תורה ומצות נעשה בחי' יחוד עליון להיו' גילוי אור אלקי בתחתונים כו' והוא להיו' ידוע שרש ענין המצות<sup data-n=\"2102\">20</sup> שנק' רמ\"ח איברי' דמלכא ופי' אבר הוא בחי' אור וכלי כמו כשאור הנפש מתפשט באיברי הגוף הרי נחלק לכמה מדרגו' וכללותם הוא רק בחי' המשכו' אורו' וכחו' הנפש רק שמתחלק לכמה כלים מיוחדי' כו' כך למעלה בחי' המשכו' אור המאציל בכלים בנאצלי' נק' איברי' דמלכא והן הכל רק בחי' גילוי אורו' המאציל בנאצלי' בכלים מכלים שונים ופרטיהם הן רמ\"ח רמ\"ח גילויי' כו' והטעם לרמ\"ח מבואר בע\"ח לפי שכללו' הספירו' הן רק ט' ספי' וכאו\"א להיותו מתגדל ע\"י החסדי' נתחלק לט' פעמי' ט' שעולה בגי' פ\"א ועד שנעשה בבחי' ראש תוך סוף עולה ג\"פ פ\"א הרי רמ\"ג ועם ה' החסדי' עולה רמ\"ח כו' וד\"ל ולכך נתחלקו המצות לכמה פרטי' עד שאין אחת דומה לחברתה כלל כמו התפילין ממשיכי' בחי' מקיפי' דאור אבא והאתרוג מבחי' מלכו' והסוכה<sup data-n=\"2103\">21</sup> מקיפי' דאימא כו' וכיוצא ולפי שהן הן בחי' רמ\"ח איברי' דמלכא למעלה באצילו' והן הנקראי' חיוהי וגרמוהי שהוא כל בחי' קומת ז\"א דאצי' עם בחי' המוחי' דאו\"א שמלובשי' בו וכמארז\"ל הקדב\"ה<sup data-n=\"2104\">22</sup> מניח תפילין ומתעטף בציצית כו' וכאשר עושה צדקה והיינו ענין חסד<sup data-n=\"2105\">23</sup> דרועא ימינא להחיו'<sup data-n=\"2106\">24</sup> רוח שפלי' כו' אך בירידות המצות מבחי' אצילו' לבי\"ע נתלבשו בעניני הבריאה הגשמי' עד שבעוה\"ז התפילין נעשי' ע\"ג קלף גשמי כו' וכמבואר כל זה במ\"א וד\"ל ולהיות כן ע\"י המצות הנעשו' למטה בבי\"ע נמשך ונגלה כבוד ה' שברמ\"ח איברי' דמלכא למטה ע\"י התפילין<sup data-n=\"2107\">25</sup> המשכת אור החכמה דאצי' וע\"י הצדקה בחי' אור החסד וכיוצא כו' ועי\"ז נעשה בחי' דירה בתחתונים להיו' גילוי אלקו' למטה בנפרדי' דוקא שלזה היתה כל עיקר הכונה של המאציל כנ\"ל וד\"ל.\n<b>אך</b> הנה עדיין יש להבין האיך יוכל להיות גילוי אלקו' בתחתונים ע\"י מעשה המצו' אחר שהתחתוני' הם בחי' נבראי' גשמיי' והכח אלקי הוא בתכלית ההפשטה",[["2099","17","<b>איהו וחיוהי וגרמוהי חד</b>: ראה ת\"ז בהקדמה ג, ב."],["2100","18","<b>ונגלה כבוד הוי'</b>: ישעי' מ, ה."],["2101","19","<b>שעיקר הכבוד הוא לרחוקי'</b>: ראה גם שעה\"י קמג, א ובהערה 3. ראה תו\"ח שמות רצד, ד. תרה, ב."],["2102","20","<b>המצות שנק' רמ\"ח איברי' דמלכא</b>: ראה תיקוני זהר ת\"ל. וראה תניא פ\"ד ובליקוט פירושים ומ\"מ שם."],["2103","21","<b>והסוכה מקיפי' דאימא</b>: ראה לקו\"ת במדבר יד, ג. ובכ\"מ."],["2104","22","<b>הקדב\"ה מניח תפילין ומתעטף בציצית</b>: ברכות ו, א. ר\"ה יז, ב."],["2105","23","<b>חסד דרועא ימינא</b>: ראה ת\"ז בהקדמה (יז, א)."],["2106","24","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["2107","25","<b>התפילין המשכת אור החכמה</b>: ראה זהר (רע\"מ) בא מג, ב. ראה לקו\"ת שלח לט, ד."]]],[2100490394,"מכל בחי' גשם וגבול כו' והאיך יהי' ביכולת לקשר הרוחניו' עם הגשמיו' שהוא היפך סדר ההשתלשלו' כנודע, אך הענין הוא מפני שישראל עלה במחשבה אחת הנ\"ל הנק' מחשבה הקדומה לכך כשישראל עושין המצו' &lt;קיא&gt;\nהמה ממשיכי' ומקשרי' הרוחניו' בגשמיו' כו' וביאור טעם הדבר הנה מבשרי אחז' כו' דהלא אנו רואי' באור וחיו' הנפש שמתלבש ונמשך באיברי הגוף הן מחולקי' בשינוי המדרגו' לא ראי זה וכו' כמו ראי' ושמיעה ריחא ודיבור וכיוצא כאו\"א הוא בכח רוחני מיוחד לעצמו והן נמשכי' ויוצאי' מן הנפש בסדר ההדרגה זה למעלה מזה כח הראי' בעין והשמיעה באזן והריח בחוטם וכו' עד שיורד ונמשך למטה מטה גם באבר היותר תחתון והוא כמו צפורן שברגל שגם בו יש חיו' ואור אלא שהוא היותר אחרון כו' והנה אין לכל א' וא' קשר וחיבור זע\"ז שאין לעין חיבור עם הרגל וכן גם היד הימין עם יד שמאל אין להם חיבור כו' אבל הנה בבחי' המחשבה שבגידי מוח האדם הנה אנו רואי' שמקושרים ואחוזי' בה כל התחלקו' האורו' שבאיברי' מראש עד הצפרן שברגל כולם בהשוואה א' מבלי קדימה לא' על זולתו וכולם מתקשרי' יחד שהרי גם הכאב שבצפרן הרגל ירגיש האדם במוח בהשווא' א' כמו שירגיש כאב היד והעין וכיוצא והוא לפי שכולם מקושרי' במחשבה בסקירה אחת כי כשמביט וצופה במחשבה את כל מה שנמצא בחיו' נפשו וגופו מרגיש הוא בהרגשה אחת לכולם וכוללם יחד בהשווא' א' והמחשבה סובבם כמו סיבוב העיגול מכל צד בהשווא' א' מבלי המצא בחי' מעלה ומטה כלל והיינו שאין לא' יתרון מעלה ולא ענין קדימה על זולתו וכל זה מפני שמחשבה זו מלובש בה בחי' הרצון שהוא הנק' בחי' הכתר<sup data-n=\"2108\">26</sup> מלשון כותרת לפי שמקפת וסובבת כל כחו' המתחלקי' מהנפש בהשווא' א' כו' וע\"כ יש ביכולתה לקשר ולחבר את הכל כמו להרגיש גם כאב הצפורן שברגל כנ\"ל וד\"ל.\n<b>והדוגמא</b> מזה ממש יובן למשכיל למעלה דגם בחי' מחשבה אחת הנ\"ל מאחר שצופה ומביט בה עד סוף כל הדורו' כו' הרי הוא המקשר ומחבר כללו' כל ההשתלשלו' דאבי\"ע מכל שית אלפי שני כו' בסקירה א' בהשווא' א' לכולם וכוללם יחד מבלי המצא בחי' מעלה ומטה לפניו וכמשל צפרן שברגל היינו סוף עולם העשי' כו' עד רום המעלו' שלפני האצי' שוין הכל בהשווא' א' ובמחשבה אחת נסקרי' כו' וא\"כ בחי' אצי' ועשי' שוין לפניו והוא בחי' כתר עליון עילת העילו' כו' ונק' סובב כל עלמין הכללי והוא בבחי' א\"ק כו' וכמ\"ש במ\"א ועד\"מ העיגול של כדור השמים שאין בו מעלה ומטה כלל כו' וד\"ל, וא\"כ מובן ממשל זה דהגם שבסדר ההשתלשלו' האצי' הוא למעלה והבריאה למטה כו' וה\"ז כדמיון התחלקו' מדרגו' של כחו' הנפש באיברי הגוף העין לראו' והאזן לשמוע כו' שהוא בסדר ההדרגה זה למטה מזה כנ\"ל ואין להן חיבור דאצי' נעלם אורו בבריא' ע\"י פרסא כו' כידוע אבל ע\"י בחי' מחשבה אחת יש להם חיבור וקישור מפני שמרגיש כולם יחד כו' וע\"כ ע\"י מעשה המצות שישראל עושי' דלפי שישראל דוקא עלה במחשבה זו הכוללת כולם יחד לכך יש ביכולתם דוקא לקשר ולחבר הארת האצי' בבריא' ע\"י יחוד עליון",[["2108","26","<b>הכתר מלשון כותרת</b>: ע\"ח שער א\"א (שי\"ג) פ\"ג. שער מוחין דצלם (שכ\"ג), פ\"ב. וראה אגה\"ק פי\"ז, פכ\"ט. לקו\"ת במדבר סט, א."]]],[2100490395,"שנעשה במצו' מטעם שישראל עלה במחשבה הקדומה ואם אין העושה המצוה ישראל אינו ממשיך כלום לפי שבחי' הגילוי אלקו' בתחתוני' צריך להיו' מלמעלה מכל ההשתלשלו' דהיינו ממקום הגבוה שמעלה ומטה שוין כנ\"ל מפני שמשם דוקא יוכל להיו' היפך ההשתלשלו' &lt;קיב&gt;\nדהיינו לקשר רוחניו' בגשמיו' כנ\"ל וד\"ל, וזהו הטעם שנק' בחי' הארה זאת מעצמו' אור א\"ס לקשר ולחבר אור המאציל בנאצלי' בשם מזל כמו שידוע דמזלו' דא\"א הם שרשי המוחי' דאו\"א דאור<sup data-n=\"2109\">27</sup> אבא יונק ממזל הח' ונוצר חסד ואור אימא ממזל הי\"ג ונקה כו' לפי שבחי' התחברו' והתקשרו' זאת באה ע\"י בחי' צמצומי' גדולי' עד\"מ שישפיל האדם למטה את מחשבתו לחשב בכל מה שיש במציאו' התפשטו' כחות הנפש בפרט כו' שהוא בא ע\"י צמצום כך למעלה כדי שישפיל בחי' מחשבה הקדומה הנ\"ל להיו' מרגיש באור חכמה הנאצל כו' הרי זה בא ע\"י צמצום בלבד והוא מ\"ש והחכמה<sup data-n=\"2110\">28</sup> מאין תמצא בבחי' שערו' וצמצומי' והוא הנק' מזל ונוצר כו' לפי שאור הנאצל הוא רק בבחי' עשי' בעלמא כמ\"ש כולם בחכמה עשית כו' וזהו נעשה למעלה ע\"י ישראל למטה לפי ששרשו בבחי' מחשבה אחת הנ\"ל והוא מאיר על נפש ישראל בבחי' מקיף ונק' ג\"כ מז\"ל כו' כמבואר<sup data-n=\"e32\">*</sup> למעלה וד\"ל.\n<b>ג</b> וזהו שרש ענין ותורה שם בישראל בשביל ישראל שנק' ראשית כו'. דהנה מבואר למעלה דבחי' מחשבה דא\"ק ששם ישראל עלה כו' הוא למעלה מעלה מכל ההשתלשלו' וזהו הנק' ישראל דלעילא ובניצוץ האלקי למטה בישראל עלי' אנו או' טהורה<sup data-n=\"2111\">29</sup> היא שלמעלה מבחי' בריא' יש מאין כמ\"ש למעלה כי מאחר שעלתה במחשבה הקדומה הנ\"ל הרי נכללת באחדו' הפשוטה כמו שהי' הוא<sup data-n=\"2112\">30</sup> ושמו בלבד קודם ההשתלשלו' כו' ויש עוד בחי' ישראל ונק' ישראל<sup data-n=\"2113\">31</sup> זוטא והוא הנק' כנסת ישראל שהן כללו' נ\"י המלובשי' למטה בגופים ולמעלה הן בבחי' מל' דאצי' ונק' ג\"כ בשם אימא<sup data-n=\"2114\">32</sup> תתאה ומטרוניתא כידוע בזוהר וזהו שאמר יעקב",[["2109","27","<b>דאור אבא יונק ממזל הח'</b>: ראה זהר (אד\"ז) האזינו רפט, ב. ע\"ח שער הכללים פ\"ה."],["2110","28","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["2111","29","<b>טהורה היא</b>: ברכת אלקי נשמה."],["2112","30","<b>הוא ושמו בלבד</b>: פדר\"א פ\"ג."],["2113","31","<b>ישראל זוטא</b>: ראה זח\"ב מג, א. רטז, א."],["2114","32","<b>אימא תתאה ומטרוניתא כידוע בזהר</b>: ראה זח\"א נ, א. רמז, ב. זח\"ב פד, א. זח\"ג רנג, א. וראה תניא רפנ\"ב. אגה\"ק סכ\"ה (קלט, א), הנסמן במ\"מ ללקו\"ת שה\"ש יח, ב."],["e32","*","<b>כמבואר למעלה וד\"ל</b>: הגהות כ\"ק אדמו\"ר הצ\"צ על סעיף ב': ב. וישראל עלה במחשבה הנ\"ל כי תכלי' הבריאה שיהי' דירה בתחתונים דבאצי' בלא\"ה איהו וגרמוהי חד, ודירה זו ע\"י המצות רמ\"ח איברים ט\"ס טפ\"ט כו' וע\"י קיום מצוה בעוה\"ז נמשך א\"ס שבאבר דז\"א דאצי' בבי\"ע, וחיבור זה ע\"י נש\"י שעלו במח' (ע' קי\"ס חיבור אצי' ובי\"ע ב' הפכי' ע\"י רוח קדים) [סה\"מ תק\"ע ע' עו ואילך. אוה\"ת בשלח ע' תקסח ואילך] בנפש ב' בחי' א' ראי' שמיעה כו' ב' מחשבה כוללת כולם לכן מרגיש במח' כאב צפורן הרגל כי במח' מלובש רצון כתר כותרת, וכן למעלה יש אצי' ובריאה ופרסא ביניהם אבל מח' הקדומה כוללת כולם יחד צופה ומביט בסקירא א' לכן דוקא ע\"י שישראל שעלה במח' מקיים המצוה הוא ממשיך אצי' בעשי' ולכן נק' מזל השפלה צמצומים כו'."]]],[2100490396,"ואנכי<sup data-n=\"2115\">33</sup> איש חלק פי' שיש ביעק\"ב ב' חלקים והן בלתי ממוצעי' אלא חלק הא' הוא קצה העליון ביותר והחלק השני הוא קצה התחתון ביותר ולפי שנחלק לב' חלקי' עליון ותחתון נק' איש חל\"ק מפני החלוקה הזאת שנחלק בו הא' למעלה מעלה והב' למטה מטה כו'.\n<b>וביאור</b> הדברים מובן עפ\"י הנ\"ל דחלק העליון שביעקב הוא בחי' ישראל דלעילא הנ\"ל שעלה במחשבה הקדומה שלמעלה מעלה מכל ההשתלשלו' והחלק השני שביעקב הוא בחי' ישראל זוטא והיינו כללו' נ\"י שנק' אימא תתא' ומטרוניתא למעלה והוא בחי' מל' דאצי', והחלקים הללו הרי הם בלתי ממוצעי' אלא זה למעלה בתכלית וזה למטה בתכלית כידוע שבחי' מל' היא סוף כל המדרגו' בהשתלשלות וד\"ל ובדרך כלל החלקים הללו הן נקראים בחי' יעק\"ב ובחי' ישרא\"ל כידוע שיעק\"ב<sup data-n=\"2116\">34</sup> הוא בחי' י' עק\"ב וישראל<sup data-n=\"2117\">35</sup> לי ראש וכערך העקב לגבי הראש כו' כך ערך עלמא דאתגליא לגבי עלמא דאתכסיא שהוא בחי' ממלא כ\"ע ובחי' סובב כ\"ע בכללות כל ההשתלשלו' וד\"ל, והנה בחי' המחבר בין שני הקצוות הללו הרחוקי' זה מזה בתכלית הוא התורה שנק' בחי' ממוצע לחבר חלק העליון בחלק התחתון ולהיות נעוץ<sup data-n=\"2118\">36</sup> תחלתן בסופן כו' וזהו בראשי\"ת בשביל ישרא\"ל שנק' ראשי\"ת וכן מ\"ש ותורה שם בישראל כו' לפי שידוע שהתורה שרשה היא מבחי' אור החכמה העליונה שבאצי' כי אוריי'<sup data-n=\"2119\">37</sup> מחכמה עילאה נפקת כידוע בפי' ותמלא<sup data-n=\"2120\">38</sup> &lt;קיג&gt;\nכד\"ה כ\"ד<sup data-n=\"2121\">39</sup> ספרי' דאוריי' כו' שנשאבו מעצמו' החכמה דא\"ס שהוא בחי' מחשבה הקדומה הנ\"ל כמו שנשאב בכד מים הגדול כו' וכמ\"ש במ\"א וכאשר נשאבה ונמשך האור באצי' הנה הוא בחי' המחבר להביא עצמו' המחשבה הקדומ' בנאצלי' כולן לפי שהחכמה<sup data-n=\"2122\">40</sup> היא בחי' ראשית הגילוי בנאצלי' וכת\"א<sup data-n=\"2123\">41</sup> בראשית בחוכמתא כו' והוא התחלת בחי' הקו הימין חכמה חסד נצח כידוע וממנו משתלשל בכל פרטי ג' הקוין כידוע עד סיום כל האורו' שבאצי' כמ\"ש בע\"ח ובחי' רמ\"ח איבר\"י דמלכא הנ\"ל מקבלי' כולן מבחי' אור החכמה שבתורה כמו עד\"מ שמתפשט חיו' שפע המוח בלב ואיברי' כולן שהוא למעלה חסד דרועא ימינא כו' וכנסת ישראל שלמטה הוא בחי' מל' דאצי' למעלה מקבלת האור והשפע דרמ\"ח איבר\"י דמלכא כמשי\"ת בסמוך שנק'<sup data-n=\"2124\">42</sup> מצות המלך כו' וא\"כ מובן שהתורה היא בחי' ממוצע לחבר ולהביא אור מחשבה הקדומ' לנאצלי' עד שמקבלת בחי' חלק התחתון ג\"כ והוא בחי' ישראל זוטא ולהיו' נעוץ תחלתן בסופן כו' וזהו ותורה שם בישראל בשביל ישראל שנק' ראשית פי' בשביל",[["2115","33","<b>ואנכי איש חלק</b>: תולדות כז, יא."],["2116","34","<b>שיעקב הוא בחי' י' עקב</b>: ע\"ח (שער סדר אצי') ש\"ג פ\"ב."],["2117","35","<b>וישראל לי ראש</b>: ראה פע\"ח (שער הלולב) שכ\"ט, פ\"א."],["2118","36","<b>נעוץ תחלתן בסופן</b>: ס\"י פ\"א, מ\"ז."],["2119","37","<b>אורייתא מחכמה עילאה נפקת</b>: זח\"ב קכא, א. וראה שם פה, א."],["2120","38","<b>ותמלא כדה</b>: חיי שרה כד, טז."],["2121","39","<b>כ\"ד ספרי דאורייתא</b>: ראה ת\"ז תכ\"א (מו, ב)."],["2122","40","<b>שהחכמה היא ראשית הגילוי</b>: ראה זח\"א לא, ריש ע\"ב."],["2123","41","<b>וכת\"א בראשית בחוכמתא</b>: בראשית א, א. תרגום ירושלמי שם."],["2124","42","<b>שנק' מצות המלך</b>: אסתר ג, ג. ובזח\"ג קעה, ב."]]],[2100490397,"ישראל דלעילא שבמחשבה הקדומה הנ\"ל כדי שיתחבר ויבא למטה באבי\"ע עד שיתחבר גם בחלק היותר תחתון והוא בחי' ישראל זוטא (ויש בפי' בשביל ישראל ג\"כ בשביל ישראל זוטא שיקבל מישראל דלעילא) וזהו שאמר בזוהר<sup data-n=\"2125\">43</sup> דתלת קשרין אוריי' וקדב\"ה וישראל כו' היינו בחי' ישראל זוטא שמקבל מהתורה ואמנם בחי' ישראל דלעילא הוא בחי' הקצה היותר עליון שבעצמו' המאציל כנ\"ל אדרבה משם שרש התורה נמשך למטה וזהו ותור\"ה שם בישרא\"ל מה ששם התורה למטה באבי\"ע הוא בשביל ישרא\"ל שנק' ראשי\"ת שמעלה ומטה שוין שם כנ\"ל וד\"ל וזהו שרש ענין ישראל עלה במחשבה כדי שיוכל להיות בחי' דירה בתחתונים על ידם לפי שסוף מעשה עלה במחשבה תחלה והיינו ג\"כ ענין בראשית ברא אלקי' את השמים כו' בשביל ישראל כו' פי' בשביל ישראל דלעילא כי נעוץ סופן בתחלתן משום שסוף מעשה עלה במחשבה<sup data-n=\"e33\">*</sup> תחלה וד\"ל.\n<b>ד</b> אך הנה בהיות מבואר למעלה בבחי' מחשבה הקדומה הנ\"ל שאין שם בחי' מעלה ומטה כלל וכולם נסקרים בסקירה א' עד שאצי' ועשי' שוין כו' ושם נא' כחשיכה<sup data-n=\"2126\">44</sup> כאורה כו' לפי שאין תופסי' מקום לכך כקטן כגדול שוין לפניו כו' א\"כ יכול להיו' אור השפע נמשך משם גם לחיצונים לעוברי רצונו כי לעוצם הרוממו' אין הדבר תופס מקום כלל וכמ\"ש שממית<sup data-n=\"2127\">45</sup> בידים תתפש והיא בהיכלי מלך כו' מפני העדר תפיסת מקום לשממית בהיכל המלך וכמארז\"ל הן<sup data-n=\"2128\">46</sup> הן גבורותיו שגוים מרקדין בהיכלו והוא שותק כו' כי באמת לגדולתו אין חקר ויכולה להתפשט גם בקצה היותר תחתון וזהו מצד עוצם תגבורת השפע שיוצא גם בחי' מותרו\"ת וכענין אברהם<sup data-n=\"2129\">47</sup> שיצא ממנו ישמעאל כי מבחי' מותרו'<sup data-n=\"2130\">48</sup> של החסדי' דאברהם<sup data-n=\"2131\">49</sup> איש החסד אמר לו<sup data-n=\"2132\">50</sup> ישמעאל יחי' לפניך כו' והוא הי' בחי' הפסולת שלו כך יובן בדוגמא למעלה שיכול להיו' גם אור ושפע לע' שרים למטה מצד עוצם תגבורת האור כי רב הוא כו' ע\"כ לזה הטעם שלא יצא האור רק בבחי' פנימי' לקדושה העליונה &lt;קיד&gt;\nולא לבחי' חיצוניו' ומותרו' לחיצוני' כלל לזאת ניתנו לישראל",[["2125","43","<b>בזוהר דתלת קשרין</b>: ראה הנסמן לעיל בהמ\"מ להמאמר."],["2126","44","<b>כחשיכה כאורה</b>: תהלים קלט, יב."],["2127","45","<b>שממית בידים תתפש</b>: משלי ל, כח."],["2128","46","<b>הן הן גבורותיו שגוים מרקדין בהיכלו</b>: יומא סט, ב (כגי' הע\"י). ילקוט שמעוני נחמי' רמז תתרעא."],["2129","47","<b>אברהם שיצא ממנו ישמעאל</b>: ראה פסחים נו, א."],["2130","48","<b>מותרות של החסדים דאברהם</b>: ראה תו\"א תולדות. תו\"ח תולדות קמד, ד ואילך. ובכ\"מ."],["2131","49","<b>דאברהם איש החסד</b>: ראה ספר הבהיר סק\"צ-צ\"א, הובא גם בפרדס שער (ב) טעם האצילות. שער (כב) הכינויים פ\"ד. כד הקמח מערכת אורחים בהתחלה (לה, א). אגה\"ק ס\"ה (קח, ב)."],["2132","50","<b>לו ישמעאל יחי' לפניך</b>: לך יז, יח."],["e33","*","<b>במחשבה תחלה וד\"ל</b>: הגהות כ\"ק אדמו\"ר הצ\"צ על סעיף ג': ג. וזהו ותורה שם בישראל בחי' ישראל דלעילא עלה במחשבה דא\"ק ונש\"י שלמטה הן מל' דאצי' ותורה ח\"ע מקור רמ\"ח איברי ז\"א מקבלת ממח' הנ\"ל אבא יונק ממזלא ומשפיע למל' (וזהו רעייתי לחם לבב אנוש יסעד)."]]],[2100490398,"המצות לקיימם בפועל ממש כי על ידן יתלבש כח האלקי במעשה המצוה למטה ונק' לבוש המלך והנה כמו הלבוש שמכסה על האדם לבלתי ידבק בו דבר זר מפני שמתעלם בלבוש כמ\"כ מצות<sup data-n=\"2133\">51</sup> מעשיו' הם בחי' לבושי' להעלים את בחי' גילוי אור האלקי שמתגלה בעולמו' הנפרדי' לבלתי יקרב זר לקבל הארה האלקי' ואין החיצוני' מקבלי' שום יניקה מפני שהלבושי' דמצות מעלימי' מפניהם האור, וזהו מ\"ש ותלבש<sup data-n=\"2134\">52</sup> אסתר מלכות ואמרו בזוהר דנשמת האדם מתלבשת בלבושי המצו' בג\"ע לבלתי יקרב אליה מהיכלו' החיצוני' כו' וזהו שנק' כללו' המצו' בשם לבוש מלכות והוא מה שאנו או' בברכת המצות אלקינו מלך העולם כנ\"ל אבל כשאינו עוסק במצות מעשיו' אלא בתורה בלבד והוא האו'<sup data-n=\"2135\">53</sup> אין לי אלא תורה כו' דאפי' תורה אין לו לפי שנמשך אור ושפע הי\"ס דאצי' ששרשם בתורה דאוריי' מחכמ' נפק' כנ\"ל גם לע' שרים בהיכלו' הנוג\"ה כשאין לבוש מעלים לאותו האור אך ע\"י המצו' מעשיו' נעשה לבוש מעלים ואז האור דתורה משתמר וזהו כי<sup data-n=\"2136\">54</sup> נר מצוה ותורה אור כו' מפני שהמצוה היא בחי' כלי ולבוש כו' וד\"ל.\n<b>וזהו</b> שרש ענין הנ\"ל דבתורה בלא מצות מעשיו' נא' אלביש<sup data-n=\"2137\">55</sup> שמים קדרות כו', פי' שמים<sup data-n=\"2138\">56</sup> הוא בחי' אש ומים רצוא ושוב שהן כללו' כל התורה מפני שכלולה מאש<sup data-n=\"2139\">57</sup> ומים חו\"ג כמ\"ש מימינו<sup data-n=\"2140\">58</sup> אש דת כו' וכנ\"ל דכל האיברי' נתחלקו בהמשכו' קוין חח\"נ מימין כו' חסד דרועא ימינא כו' ויש בתורה מכל רמ\"ח האיברי' כו' צדקה בדרועא ימינא ותפילין במוחי' שבראש כו' ודרך כלל נק' שמי\"ם שהוא בחי' עולם הנאצל שכולל ו\"ק כו' וזהו שאמרו שהתורה<sup data-n=\"2141\">59</sup> ירדה מן השמי\"ם כו' שהן ז' ימי הבנין דז\"א דאצי' כו' שהתורה היא בחי' שמי\"ם העליונים ואמנם כאשר אין לבוש לכלי לאורו' דאצילו' שברמ\"ח איברי' כו' להלביש ולהעלים האור יוכל להמשך גם לחיצוני' ואזי מלביש לבוש זר והוא לבוש קדרו\"ת ולבוש ש\"ק שהחיצוני' מקבלי' משם כידוע וזהו אלביש שמים דתורה קדרו' בלבוש דקדרו' והן היכלו' החיצוני' שמקבלי' מבחי' המותרו' כנ\"ל בענין אברהם שיצא ממנו ישמעאל כו' וכך במדו' שבתורה יוכל להיו' בחי' מותרו' השפע לחיצוני', וענין ובחי' המותרו' במדות שבתורה יובן ע\"ד דוגמא מב\"ש וב\"ה שב\"ש<sup data-n=\"2142\">60</sup> מחמירי' וב\"ה מקילי' כידוע לפי שב\"ש<sup data-n=\"2143\">61</sup> מסטרא דגבורה מטי'",[["2133","51","<b>מצות. . הם בחי' לבושי'</b>: ראה תניא אגה\"ק סכ\"ט. תו\"א מקץ לב, ד ואילך. תו\"א חיי שרה טז, א. משפטים עו, ג. עט, ב. סה\"מ מלוקט ח\"ג ע' רפט ואילך."],["2134","52","<b>ותלבש אסתר מלכות</b>: אסתר ה, א."],["2135","53","<b>האומר אין לי אלא תורה</b>: ראה יבמות קט, ב."],["2136","54","<b>כי נר מצוה ותורה אור</b>: משלי ו, כג."],["2137","55","<b>אלביש שמים קדרות</b>: ישעי' נ, ג."],["2138","56","<b>שמים. . אש ומים</b>: חגיגה יב, א. וראה ב\"ר ספי\"ד."],["2139","57","<b>מאש ומים. . חו\"ג</b>: ראה פרדס (שער ערה\"כ) שכ\"ג מערכת מים. תניא פ\"ג."],["2140","58","<b>מימינו אש דת</b>: ברכה לג, ב."],["2141","59","<b>שהתורה ירדה מן השמים</b>: ראה ב\"מ נט, ב. וראה תו\"ח לך לך צג, ג ובהנסמן בהמ\"מ שם."],["2142","60","<b>שב\"ש מחמירים וב\"ה מקילים</b>: ראה פסחים נה א (במשנה). חולין יח, א."],["2143","61","<b>שב\"ש מסטרא דגבורה</b>: ראה זהר (רע\"מ) פינחס רמה, א. וראה תו\"ח בראשית י, א ובהנסמן בהמ\"מ לשם."]]],[2100490399,"לדין וצמצום וב\"ה מסטרא דחסד ולכך שכלם מטי' כלפי חסד ואמנם כאשר ב\"ש היו מחמירי' ביותר וב\"ה היו מקילין ביותר מזה נמשך הסתעפות מותרו' הדינין לעש\"ו ומותרי החסדי' לישמעא\"ל וכדומה וד\"ל.\n<b>ובכל</b> זה מובן שרש ענין רעיית\"י ויפת\"י הנ\"ל דרעיית\"י הוא התורה שהיא המזון לנפש והענין הוא כנ\"ל לפי שע\"י התורה נתחבר אור עצמו' המאציל בנאצלי' כנ\"ל מבחי' ישראל דלעילא שבמחשבה הקדומה שלמעלה מכל השתלשלו' עליון ותחתון כו' וכנ\"ל בענין ותורה שם בישראל וה\"ז כמשל המזון לנפש שמשיב את הנפש עד שיתפשטו כוחתיה באיברי' כולן כו' עד שתרגיש כולן כו' וד\"ל, ובחי' יפת\"י הוא ע\"י מעשה המצות לפי שהמצו' בפ\"מ נק' בחי' לבוש מלכות ולהיו' כי על ידם ישמור מהיות ירידת שפע מותרו' לחיצוני' בע' שרים כנ\"ל &lt;קטו&gt;\nע\"כ נא' בזה עוז<sup data-n=\"2144\">62</sup> והדר לבושה שהן לבושי' יפין עד שמייפין לכל הגוף והיינו שנק' כנ\"י בעשותה כל המצות בשם יפת\"י כו' הנה בהיפוך בתורה בלא מצות כתיב וכל<sup data-n=\"2145\">63</sup> מלבושי אגאלת\"י כמ\"ש אלביש שמי\"ם קדרו\"ת וכנ\"ל הטעם וזהו שארז\"ל שהלמד<sup data-n=\"2146\">64</sup> ואינו עושה נוח לו שיהפך שלייתו כו' וגדול<sup data-n=\"2147\">65</sup> תלמוד שמביא לידי מעשה וכו' ונמצא בחי' רעיית\"י ויפת\"י צריך להיו' שניהם דוקא והאו' אין לי אלא תורה כו' ובהיפוך בלא אור דתורה אין בחי' ממוצע לחבר ולהביא אור והיינו הטעם שנק' מזון דלכך נק' רעייתי שמפרנסי' לאביהם שבשמים כו' וכמ\"ש במ\"א וד\"ל ובדרך כלל זה החיבור רעייתי ויפתי הוא בחי' יחוד קדב\"ה ושכינתי' בכל מקום והיינו חיבור אותיו' ו\"ה שבשם הוי' הוי\"ו בתורה והה\"א במצות המלך כידוע והוא הנק' קבלת עול מלכו' שמים דלעילא<sup data-n=\"e34\">*</sup> וד\"ל.\n<b>ה</b> והנה עתה יש להבין האיך שאין זה ביכולת אלא בישראל להמשיך למעלה להיות בחי' רעיית\"י בתורה ובחי' יפת\"י במצות ומה גם שיתחברו שניהם יחדיו כו'. כי הנה מבואר למעלה בבחי' מחשבה הקדומה שאין ערך כלל לנאצלי' עמו לפי שהוא למעלה מבחי' ההשתלשלו' לגמרי ואמנם הנה הוא בחי' ממוצע בין עצמו' אור הא\"ס לנאצלים להיות כי עצמו' אור הא\"ס הוא פשוט בתכלית למעלה גם מהיות בחי' מקיף וסובב כל ההשתלשלו' בהשוואה א' אבל בחי' מחשבה זו כבר היא בחי' מקיף כנ\"ל שהוא עכ\"פ שייך לבחי' השתלשלות אלא שהוא מקיף וכוללם יחד כו' כנ\"ל וד\"ל, וזהו קומי<sup data-n=\"2148\">66</sup> לך והכתיב לכ\"י דהיינו כף יו\"ד כמ\"ש למעלה דהנה בחי' הממוצע",[["2144","62","<b>עוז והדר לבושה</b>: משלי לא, כה."],["2145","63","<b>וכל מלבושי אגאלתי</b>: ישעי' סג, ג."],["2146","64","<b>שהלמד ואינו עושה נוח לו שיהפך שלייתו</b>: ראה ירושלמי ברכות פ\"א, ה\"ב. וראה לקו\"ת אחרי כו, ד. וראה בהנסמן במ\"מ לשם."],["2147","65","<b>וגדול תלמוד שמביא לידי מעשה</b>: ראה קידושין מ, ב."],["2148","66","<b>קומי לך</b>: שה\"ש ב, יג."],["e34","*","<b>דלעילא וד\"ל</b>: הגהות כ\"ק אדמו\"ר הצ\"צ על סעיף ד: ד. אך לפי שמחה\"ק כוללת כל השתלשלות כחשכה כאורה א\"כ גם שממית בידים תתפש כו' ואברהם חסד אמר לו ישמעאל יחי' לכן ניתנו המצות שהן לבוש מל' והאומר אין לי אלא תורה ה\"ז אלביש שמים אש ומים ב\"ש וב\"ה קדרות כו' וזהו יפתי וצ\"ל ב' הבחי' רעייתי להמשיך החיבור ויפתי הלבוש."]]],[2100490400,"צריך להיות בו מהארת העליון וגם מהארת בחי' התחתון וצריך שיהי' כלול משניהם יחדיו וזהו שהוא נכתב באות כ\"ף שהכף עולה עשרים לפי שיש ב\"פ יו\"ד ספי' א' י\"ס הגנוזו' והוא בחי' האחרונה שבאור א\"ס שבמחשבה הנ\"ל אבל למעלה ממחשבה הקדומה לא שייך ענין ספי' והב' י\"ס הנאצלי' הכלולי' בו כי בהכרח שנמצא בו מכל מה שבנאצלי' ומכל מה שיבא האור והשפע מעצמו' המאציל אחר שהוא בחי' ממוצע שעל ידו יתחבר העליון בתחתון והטעם שצריך לממוצע ידוע לפי שאין ערוך כלל בין האצי' לגבי עצמו' הא\"ס אפי' לא כערך גרגיר חרדל לגבי כל חלק השטח השמים כו' וגם עוד טעם יש למה שנכתב בכ\"ף והכל ענין א' לפי שהכף הוא היד שנק' כף יד ועד\"מ היד יש בה הפשיטות ויש בה הכפיפות וכשכופף אותה ונעשית כמו חלל באמצעה והיד מקפת וסובב את הדבר שבתוכה אזי נקרא' בשם כף ידו וכמ\"ש בעודה<sup data-n=\"2149\">67</sup> בכפו כו' משא\"כ כשנפשטת ואין בה כפיפה שאין הדבר שבה מוקף מכל צד כו' כך יובן המשל למעלה בבחי' מחשבה הקדומ' הנ\"ל שמפני שהיא מקפת כל ההשתלשלו' בהשווא' א' כנ\"ל ע\"כ נק' עד\"מ כף היד שסובב מה שבתוכו כך המחשבה הנ\"ל סובב ומקיף כל ההשתלשלו' וכל ההשתלשלו' דאבי\"ע מוקף בה מכל צד וזהו כף<sup data-n=\"2150\">68</sup> אחת עשרה זהב כו' שהוא בחי' הכתר וזהו שנאמר ומתחת<sup data-n=\"2151\">69</sup> זרועו' עולם ולכאורה איך שייך ענין זרועו' למטה מתחת העולם אלא הענין הוא מפני שהזרוע הכפופה כנ\"ל מקפת מכל צד גם מתחת כמו מלמעלה הכל ביחד והוא ענין א' עם הנ\"ל &lt;קטז&gt;\nלפי שהוא בחי' הכתר<sup data-n=\"2152\">70</sup> הממוצע כו' וגם פי' כתר לשון כותרת כעטרה על הראש כו' ג\"כ ע\"ד הזה הוא, וזהו בחי' כף יו\"ד שאמר כאן והיו\"ד הוא בחי' החכמה<sup data-n=\"2153\">71</sup> דאצי' שנק' ראשית וכוללת כל האצי' והוא י\"ס בבחי' פרט וכמ\"ש ראשית<sup data-n=\"2154\">72</sup> חכמה כו' אך תחלה היו הי\"ס כלולי' בכתר הממוצע ואז הוא כ\"ף כולל עשרים ב\"פ י\"ס מטעם הנ\"ל ואח\"כ ירד אורו בחכמה והוא היו\"ד וזהו לכ\"י כף יו\"ד ועל בחי' המלכו' שהיא כנ\"י דלעילא הוא אומר קומי לך והכתיב לכ\"י כלומר קומי לשרשך העצמי והוא בחי' ישראל דלעילא הנ\"ל שעלה במחשבה דא\"ק כנ\"ל והיינו לכ\"ף יו\"ד הנ\"ל וד\"ל.\n<b>אך</b> הנה מהיכן יהי' הכח והעוז לכנ\"י דלעילא לעלו' כ\"כ עד לכ\"י כף יו\"ד כף אחת הנ\"ל הענין הוא ע\"י התפלה<sup data-n=\"2155\">73</sup> דוקא מפני שהיא בחי' הסולם שעולין בו עד השמיימה וכמ\"ש וראשו<sup data-n=\"2156\">74</sup> מגיע השמיימה דהיינו בכ\"ף אחת הנ\"ל שסובב ומקיף את הכל וזהו קומי לך קימה זו עלי' היא שעולי' כללו' נ\"י בסולם כו' וענין זה הסולם דתפלה יובן ע\"ד דוגמא מעליו' העולמו' והנשמו' בכל שבת ושבת שהרי התפלה יש בה מהארת בחי' שבת אלא שאינה אלא ברגע שמתפלל ובשבת הוא כל היום כולו כו' דהנה כתיב מלכותך<sup data-n=\"2157\">75</sup> מלכו' כ\"ע ומלכותו בכל משלה כו' דהיינו בחי' ירידת המל'",[["2149","67","<b>בעודה בכפו</b>: ישעי' כח, ד."],["2150","68","<b>כף אחת עשרה זהב</b>: נשא ז, יד. ובכ\"מ."],["2151","69","<b>ומתחת זרועות עולם</b>: ברכה לג, כז."],["2152","70","<b>הכתר הממוצע</b>: ראה ע\"ח שער (מב) דרושי אבי\"ע פ\"א. סידור שו, ב."],["2153","71","<b>החכמה דאצילות שנק' ראשית</b>: ראה ע\"ח שער מוחין דצלם פ\"ה. לקו\"ת שה\"ש כו, ד."],["2154","72","<b>ראשית חכמה</b>: תהלים קיא, י."],["2155","73","<b>התפלה. . הסולם</b>: זח\"א בהשמטות רסו, ב. ח\"ג (תוספת) שו, ב. תקו\"ז תמ\"ה (פג, א)."],["2156","74","<b>וראשו מגיע השמימה</b>: ויצא כח, יב."],["2157","75","<b>מלכותך מלכות כ\"ע</b>: תהלים קמה, יג."]]],[2100490401,"בעולמו' להחיו' רוח שפלים עד רגלי סוף עולם העשי' וזהו כל ו' יומין דחול שמסתתרת ומתלבשת עד למטה מטה כו' ובשבת היא עולה מבחי' ההסתר וההעלם הזה וכמאמר אפשיטת<sup data-n=\"2158\">76</sup> מלבושה\"א כו' והוא בליל שבת דוקא וביום השבת עולה יותר וכו' עד שבמנחה דשבת המל' עולה עד בחי' הדיקנא כו' והוא בבחי' הכתר הנ\"ל ויש פרטי הדרגות בסדרי עליו' הללו כו' וכך בעליות המל' בכל יום בתפלה ג\"כ שהיא מבחי' עליו' המל' בשבת היינו ע\"ד ההעלא' שבשבת שעולה מעט מעט עד שעולה לבחי' כתר כו', וסדרי העליו' המה מיוסדי' בסדר התפלה מב\"ש עד יוצר אור ומיוצר עד ק\"ש ובק\"ש למסור<sup data-n=\"2159\">77</sup> נפשו באחד ממש הוא עלי' היותר עליונה מעליו' שבפסוקי דזמר' ויוצר ובש\"ע עולה המל' ונכלל בכתר עליון הנ\"ל והיינו כמו הסולם שמוצב ארצה ועולה בו מעט מעט עד שעולה בראשו שמגיע השמיימ' כו' וד\"ל, ואחר שעלתה המל' שהיא כנ\"י בכתר עליון בש\"ע ע\"י העלא' מ\"ן שלה אזי ממשכת היא בחי' מ\"ד כידוע שכל המשכה יורד אחר ההעלא' כענין אין טפה יורדת כו' והיינו שתהי' בחי' רעייתי יפתי הנ\"ל דהיינו שתוכל כנ\"י לחבר אור א\"ס בנאצלי' ונבראי' תוספת אור וגילוי ברמ\"ח איברי' דמלכא ולהמשיך השפע הזאת בנבראי' ולחבר ולקשר העליון בתחתון כנ\"ל עד שהתורה נעשי' בחי' מזון למעלה והמצו' בחי' לבוש דלכך נק' רעייתי יפתי כנ\"ל שזהו ותורה שם בישראל כנ\"ל ואם לא בחי' התפלה לא הי' ביכולתם להיו' רעייתי יפתי אלא דוקא אחר שעלה ישראל במחשבה אחת הנ\"ל ע\"י התפלה וכמ\"ש קומי לכי שאז נמשך בחי' מ\"ד בתורה ומצו'<sup data-n=\"e35\">*</sup> כו' וד\"ל.\n<b>ו</b> והנה זה הפסוק דיונתי בחגוי הסלע כו' על זמן הגלות נאמר כמבואר למעלה דהסתיו עבר הגשם חלף כו' על יציאת מצרים נא' כו' &lt;קיז&gt;\nוהענין הוא לפי שבשעת יציאת מצרים הי' בחי' גילוי אור א\"ס במלכו' דאצי' ע\"י ענן ועמוד אש דכתיב וה'<sup data-n=\"2160\">78</sup> הולך לפניהם בעמוד כו' והענן יש בו עליה למעלה וכמ\"ש אעלה<sup data-n=\"2161\">79</sup> על במתי עב כו' ויש בו בחי' הירידה להיו' מלובש על ידו כו' וזהו דוגמא להבין איך שהיו כנ\"י אז במעלה עליונה לעלות בענן ועמוד אש עד שראתה שפחה על הים מה שלא ראה יחזקאל כו' אבל בגלות אין כח לכנ\"י לעלות מצד עצמן בהעלא' מ\"ן בסולם דתפלה כו' והוא לפי שכנ\"י שרשם בבחי' מל' דאצי' דבגלותא",[["2158","76","<b>אפשיטת מלבושהא</b>: ראה תקו\"ז תכ\"ד (סט, ריש ע\"ב)."],["2159","77","<b>למסור נפשו באחד</b>: ראה זהר (רע\"מ) משפטים קיט, א. צו לג, א."],["2160","78","<b>וה' הולך לפניהם בעמוד</b>: שלח יג, כא."],["2161","79","<b>אעלה על במתי עב</b>: ישעי' יד, יד."],["e35","*","<b>ומצו' כו' וד\"ל</b>: הגהות כ\"ק אדמו\"ר הצ\"צ על סעיף ה: ה. אך תחלה צ\"ל קומי לך ע\"י התפלה. הנה מחה\"ק נק' כ' כי היא ממוצע בין א\"ס שאינו אפי' סובב ובין העולמות וכל ממוצע יש בו בחי' תחתונה שבא\"ס ושרש האצי' וזהו כ' ב\"פ י\"ס וי\"ס שבבחי' תחתונה דא\"ס המלובש במחה\"ק נק' ע\"ס הגנוזות אכן בא\"ס עצמו כשאינו מלובש במחה\"ק לא שייך ספי' וגם כף ל' כף יד ומתחת זרועות עולם כותרת סובב ויוד חכמ' ראשי' כף א' עשרה זהב וזהו לכ\"י טהורה ומשמרה והעלי' לכי ע\"י התפלה וכמו שבת כי בחול יריד' המל' ובשבת עלי' עד מנח' וסדר העליו' י\"ל דו\"ר רו\"ד."]]],[2100490402,"רישא<sup data-n=\"2162\">80</sup> שכיבת לעפרא כו' ונק' סוכת<sup data-n=\"2163\">81</sup> דוד הנופלת כידוע ואז נאמר בה יונתי בחגוי הסלע פי' מסתתרת בחגוי הסלע בבקעים הנעלמי' ומצומצמי' כ\"כ שהן ע' שרים דגלו<sup data-n=\"2164\">82</sup> לאדום שכינה עמהם כו' עד שאין לה כח עלי' באוי\"ר שנק'<sup data-n=\"2165\">83</sup> גדפין כו' וכמ\"ש למעלה ולא נשאר בה רק בחי' אהבה המסותרת הטבעית כו' כמו היונה המצומצם בגדפיה בחגוי הסלע כו' וכנ\"ל.\n<b>וכך</b> הדוגמא למעלה במל' דאצי' בבי\"ע דשכיבת לעפרא בגלותא כו' עד שהיא בחגוי הסלע בסתר המדרגה כו' וא\"כ איך יהי' לה בחי' העלי' בשרשה העצמי במחשבה אחת הנ\"ל הנה לזה הוא אומר עצה נכונה לאופן עלי' גם בהיותה בסתר המדרגה כו' באמרו הראיני את מראיי\"ך כו', דהנה כנ\"י למעלה נק' בשם מראה וכמ\"ש מראה דמות כבוד ה'<sup data-n=\"2166\">84</sup> כו' וכתיב במראה<sup data-n=\"2167\">85</sup> אליו אתוודע כו' והוא הנק' אספקלריא תתאה כו' וכמבואר בזוהר משום דכל נהורין עילאי' אתחזין שם כו' ושרש הענין דמראה היינו לפי שהיא בחי' אור חוזר כידוע והוא לפי שמצופה באבר מאחריה חוזר האור לאחור ונגלה הצורה המבטת בה וה\"ז כמו המכה בכח בכותל שכאשר הגיע ההכאה בכותל יחזור הדבר לנגד המכה והוא ג\"כ משל לבחי' אור חוזר כידוע והנה שרש טעם הדבר לזה שהאור יחזור היינו בהגיע ההשפעה לידי תכלית וסוף דוקא דלפי שאין עוד מקום להליכת האור והשפע אזי בהכרח שיחזור לאחור ומכ\"ש כשיש דבר מעכב לנגדו שיחזור האור בכחו מלמטה למעלה כמו הכאת האור דשמש בארץ למטה דלפי שהוא מסתיים בארץ ואין לו עוד מקום להתפשט כי הארץ מעכבת לכך יחזור האור ויהי' בארץ עיקר החום כו' וכן כשמעמידין מסך בפני המים ששם עיקר כח המים בשאון ורעש וכן המים הנובעים מתחת לארץ לפי שהארץ מנעם ועיכבם מתגברי' לעלות מלמטה למעלה שלא כסדר המים<sup data-n=\"2168\">86</sup> שיורדין מגבוה לנמוך כו' והכל ענין הוא לפי שבחי' אור חוזר אינו אלא בב' תנאים א' שיהי' בגמר השפע כי באמצע השפע עדיין עסוק בירידה מעילה לעילה והולך ומתמעט כו' ובגמר השפע הוא שנעוץ תחלת השפע דוקא כידוע דנעוץ תחלתן בסופן דוקא והב' שיהי' דבר מעכב שלא יוכל להתפשט עוד והכל טעם א' להיו' כי אין נעוץ התחלה אלא בסוף דוקא וכשמעכב דבר ה\"ז סוף ותכלית ונעוץ שם התחלה כו' וזהו ענין המרא\"ה דלפי שמעכב עלי' הכיסוי מאחרי' חוזר האור לאחריו כו' וכל אלה המה משלים להבין למעלה בחי' אור חוזר והוא בחי' התשוב\"ה<sup data-n=\"2169\">87</sup> תשו\"ב ה\"א תתא' ותשובה עילא' תשוב &lt;קיח&gt;\nה\"א עילא' והן ב' מראו\"ת דמראיי\"ך שהוא בחי' ה\"א אחרונ' דמל' וה\"א ראשונה דבינה כידוע ולפי שהתשוב\"ה",[["2162","80","<b>רישא שכיבת לעפרא</b>: ראה זהר במדבר קיט, ב."],["2163","81","<b>סוכת דוד הנופלת</b>: עמוס ט, יא."],["2164","82","<b>דגלו לאדום שכינה עמהם</b>: ספרי בהעלותך יוד, לה. ס\"פ מסעי. מכילתא בא יב, מא. וראה מגילה כט, א."],["2165","83","<b>שנק' גדפין</b>: ראה תניא פ\"מ."],["2166","84","<b>מראה דמות כבוד ה'</b>: יחזקאל א, כח."],["2167","85","<b>במראה אליו אתוודע</b>: במדבר יב, ו."],["2168","86","<b>המים שיורדין מגבוה לנמוך</b>: ראה תענית ז, א."],["2169","87","<b>התשובה תשוב ה\"א</b>: זח\"ג (ברע\"מ) קכב, א. ראה אגרת התשובה פ\"ד. פ\"ו."]]],[2100490403,"א\"א כ\"א כאשר יסתיר מחשך החומריו' דנפש הבהמיו' ואז ויצעקו אל ה' כו' כידוע לכך ירדה הנשמ' בגוף כי ירידה<sup data-n=\"2170\">88</sup> זו לצורך עלי' היא בכדי שיהי' בחי' א\"ח עי\"ז כמשל כיסוי המראה וכמשלי' הנ\"ל לפי שנעוץ תחלתן בסופן דוקא כנ\"ל וכמ\"כ הענין בעליו' העולמו' בשבת שהוא ג\"כ בחי' א\"ח לפי שהי' ירידה ביומין דחול בבי\"ע שמזה דוקא בא סיבת א\"ח בשבת ומטעם משלי' הנ\"ל והיינו מ\"ש ביום<sup data-n=\"2171\">89</sup> ההוא יצאו מים חיים מירושלי' חציים אל הים הקדמוני שהוא בחי' מחשבה הקדומ' הנ\"ל וזהו הראיני את מראייך ב' תשובו' הנ\"ל וזהו העצה שגם בגלות השכינה שתוכל עי\"ז לעלו' עד בחי' כתר הנ\"ל להיו' כמ\"ש קומי<sup data-n=\"e36\">*</sup> לכ\"י כו' וד\"ל.\n<b>ז</b> השמיעני<sup data-n=\"2172\">90</sup> את קולך כי קולך ערב ומראך נאוה. הנה זה הפסוק שייך למה שקדם הראיני את מראייך כו' דע\"י המראה דוקא יוכל להיו' קולך ערב כו' וביאור הדברים הנה באמת אם לא נמשך האור של המאציל רק כפי המדה הראשונה שמבראשית ע\"י תורה ומצות א\"כ מהו הריוח והיתרון בירידה זו שירד אור האלקי בנבראי' בסוד גלות בע' שרים וכן ירידת ניצוץ האלקי באדם בגוף כנ\"ל דמחמת זה נעשה בחי' א\"ח למעלה אחר שאין ההמשכה עי\"ז רק כפי מדה הראשונה בלבד כו' אך הענין הוא דעלי' זאת שאחר הירידה שהוא בחי' א\"ח כנ\"ל הוא גורם תוספת גילוי אור בתוספת מרובה על עיקר המדה הראשונה וכמ\"ש כיתרון<sup data-n=\"2173\">91</sup> האור מתוך החושך כו' יתרון ממש והטעם יובן עפ\"י משלים הנ\"ל בענין א\"ח כמו עד\"מ ההכאה בכח על הכותל שיהי' הכח ניכר ביותר בהכאה שע\"ג הכותל מבהילוכו באמצעו וכן במי הנהר שנסתם במסך שימשכו המים בהסיר המסך בתוספת רב ובתגבורת עצום כו' כידוע והדוגמא מזה יובן למשכיל למעלה דלעולם יהי' תוספת אור בגילוי רב ועצום למעלה ע\"י בחי' הירידה שירד האור בתחלה למטה ונתעלם עד שחוזר ועולה מחמת זה בבחי' א\"ח וכמו בו' יומין דחול הנה ירד אור האלקי דששת יומין עילאי' דז\"א בבי\"ע בירידה והתלבשות גדולה יום א' מבחי' חסד דאצי' מתלבש כו' ולהיות כי ע\"י כל ירידה בא בחי' א\"ח לכך כשבא יום השבת עולה בבחי' א\"ח כנ\"ל כי ביום הששי כלה ונגמר כל ההתלבשו' כו' וא\"כ בכל שבת יש הוספת מוחי' חדשים בכל הפרצופי' דא\"א ואו\"א כו' וביום השבת בפרט יש בכל שבת ושבת תוס' מוחי' חדשים מסיבת הירידה של יומין דחול שלפניו אך בכל שבת יש בחי' התוס' הזה באופן חדש מה שלא הי' בשבת שקדם לו אחר שהי' ירידה ביומין דחול",[["2170","88","<b>ירידה זו לצורך עלי'</b>: נסמן לעיל בהמאמר הערה 9."],["2171","89","<b>ביום ההוא יצאו מים חיים מירושלים</b>: זכרי' יד, ח."],["2172","90","<b>השמיעני את קולך</b>: שה\"ש ב, יד."],["2173","91","<b>כיתרון האור מתוך החושך</b>: ראה קהלת ב, יג."],["e36","*","<b>קומי לכי כו' וד\"ל</b>: הגהות כ\"ק אדמו\"ר הצ\"צ על סעיף ו: ו. והנה ביצ\"מ הגשם חלף ענין עליות וירידות משא\"כ בגלות בחגוי והעצה מראיך א\"ח כמשל מכה על הכותל ואויר התחתון וכן מראה (לכן ראה ישעי' משא\"כ משה כמ\"ש במ\"א [לקו\"ת שה\"ש כח, ב] וזהו תשובה וכמו מים כשיש דף מעכב ומראייך תשו\"ת ותשו\"ע."]]],[2100490404,"מחדש ירידה זו גרמה עלי' והוספה חדשה כי<sup data-n=\"2174\">92</sup> מי שטרח בע\"ש כו' ובכל ו' יומין דחול מתחדש הבריאה בהתחדשו' שלא הי' כמוה עדיין ביומי' דחול שלפניה א\"כ בהכרח שגם העלי' בשבת שלה חדשה היא דהיינו תוס' מוחי' חדשים לגמרי שלא היו עדיין כמוהם בשבתות שעברו ועד\"ז ניתוסף האור של המאציל בנאצלי' במוחי' חדשי' בכל שבת ושבת שבכל שנה עד כלות השנה ובשנה שאחריה עליה חדשה לגמרי עד כלות שיתא אלפי שני &lt;קיט&gt;\nדהוי עלמא ויבא יום השביעי הכללי שהוא אלף הז' הנק' יום<sup data-n=\"2175\">93</sup> שכולו שבת כו' שהוא העילוי היותר גבוה מכל השבתו' שהיו בפרט וד\"ל ועד\"ז בעליו' שנעשו' בבעלי תשובה בכללו' נ\"י בתפלה בכל יום שתשוב ה\"א תתא' וה\"א עילא' עי\"ז מלמטה למעלה בבחי' א\"ח משום דמשכי<sup data-n=\"2176\">94</sup> לי' בחילא יתיר מצד המנגד המעכב כו' שנעשה מזה בחי' א\"ח כנ\"ל גם בזה הענין הוא שניתוסף האור בתוס' מוחי' חדשי' ע\"ד עליו' השבתו' כנ\"ל והיינו שארז\"ל דצדיקי'<sup data-n=\"2177\">95</sup> גמורי' א\"י לעמוד במקום שבע\"ת עומדי' מצד בחי' א\"ח שעל ידם שהוא בתוספת ועילוי רב כעילוי השבת אחר יומין דחול כנ\"ל וד\"ל.\n<b>וזהו</b> הראיני את מראייך בתשובה בבחי' א\"ח ואז ממילא יהי' קולך ערב פי' קול ערב היינו בחי' קול דתורה דוקא שהיא מזון לנפש כנ\"ל והטעם שנק' קול ערב הנה ענין העריבות מובן במאכל שכאשר אין המאכל ערב לנפש בטעם אלא הוא רק מאכל פשוט שאינו ממיני מעדנים כמו הלחם וכיוצא אינו יכול לאכלו רק כפי המדה דהיינו כפי רעבון נפשו למלאות כריסו ויותר לא יוכל אך אם המאכל הוא ממיני מעדנים העריבים מאד כמו מעדני מלכי' וכיוצא הנה יוכל לאכלם הרבה יותר מכפי המדה שלו ברעבון נפשו ומילוי כרסו משום דרווחא לבסומא שכיח כידוע דהיינו שימצא מקום להתפשט בכרסו יותר מכפי מדתו משום דרווחא לבסומי שכיח כו' וזהו דוקא להדבר הערב ומתוק ביותר כמו אביי<sup data-n=\"2178\">96</sup> דאמר שם בשיתין מיני צעי שאכל משום דבסומי היו ורצה ללחוך גם הפינכא האחרונ' כו' וד\"ל והנמשל מובן למשכיל למעלה דקול הערב דוקא הוא שמתפשט הנפש מפני שמתענג בו עד שיתרחב ויתפשט בכלי גופו הרבה יותר מכפי המדה משום דרווחא לבסומי שכיח וזהו ע\"י קול דתורה דוקא שהוא ערב למעלה ומעורר בעצמו' אור א\"ס התפשטות וגילוי אורו ביתר מכפי המדה בהשתלשלו' והוא ענין הרחבת אורו' בכלים בבחי' תוס' מוחי' חדשי' כנ\"ל וד\"ל ולהיו' כי מבואר למעלה שע\"י התורה דוקא שהוא הממוצע לחבר אור א\"ס באצי' אך שלא הי' רק כפי המדה אבל ע\"י בחי' א\"ח הנ\"ל במרא\"ה יהי' קול\"ך בתורה אור בחי' קול ער\"ב להמשיך תוס' מוחי' כו' כי ירידה זו עשתה עלי' למעלה והוא הי' כל עיקר הכונה בראשית ההשתלשלו' שיהא לו דירה בתחתונים דוקא ותענוג זה שהי' לו ממה",[["2174","92","<b>כי מי שטרח בע\"ש</b>: ע\"ז ג, א."],["2175","93","<b>יום שכולו שבת</b>: תמיד בסופה."],["2176","94","<b>דמשכי לי' בחילא יתיר</b>: זח\"א קכט, ב. אגרת התשובה פ\"ח."],["2177","95","<b>דצדיקים גמורים. . שבע\"ת עומדים</b>: ראה ברכות לד, ב. הערת כ\"ק אדמו\"ר בסה\"מ ה'תש\"ט ע' 183-4."],["2178","96","<b>אביי דאמר שם בשיתין מיני צעי</b>: ראה מגילה ז, ב."]]],[2100490405,"שיהי' לו דירה בתחתונים ע\"י תורה ומצו' כנ\"ל זהו שעלה במחשבה הקדומה בבחי' העלא' מ\"ן ונעשה מזה בחי' קול ערב להיו' תוס' מוחי' כו' כי נעוץ תחלתן בסופן דוקא וסוף<sup data-n=\"2179\">97</sup> מעשה עלה במחשבה תחלה כענין במי<sup data-n=\"2180\">98</sup> נמלך בנשמתן של צדיקי' כו' והטעם שנעשה הקול ערב כקול דתורה דוקא להיו' כי הקול מחבר המחשבה לדיבור כידוע וכך למעלה מחבר מחשבה הקדומה להיו' בתוס' מוחי' וגילוי אור בדיבור ע\"י התורה שהיא בחי' הממוצע וכל זה ע\"י שהקדים הראיני את מראיי\"ך כו' (ויש בזה ב' אופנים א' כשעלה העלא' מ\"ן ממה שיהי' לעתיד כנ\"ל והב' אחר שנתקיים מחשבתו ונעשה בחי' א\"ח מלמטה למעלה דלזה הי' הכונה בירידה שיהי' תוס' עלי' ואזי מקבל תענוג ויהי' נמשך קול ערב רווחא לבסומי כו' והכל א'), וזהו שלע\"ל נאמר אשת<sup data-n=\"2181\">99</sup> חיל עטרת בעלה כו' דהיינו שם ב\"ן שיתעלה למעלה &lt;קכ&gt;\nמשם ס\"ג מפני שיהי' מוסיף אור במחשבה הקדומ' כמו שהי' הכונה תחלה כי סוף מעשה עלה במחשבה כו' והוא ע\"י ענין בחי' תוס' גילוי אור שנעשה ע\"י בחי' א\"ח בהעלא' מ\"ן דבע\"ת וכן ביומין דחול של כל שיתא אלפי שני כו' כנ\"ל וד\"ל. וענין ומראך נאו\"ה הנה המצו' בפ\"מ הן בחי' לבושי' כנ\"ל אך כדי שיהיו הלבושים יפין ביותר מכמו שהן בעצמן אין זה אלא ע\"ד הנ\"ל ברווחא דמזון התורה דשכיח לבסומי דוקא כך הלבושי' ממעשה המצו' מתייפין ביותר ע\"י התשובה בבחי' א\"ח כי כמו שבחי' רעייתי ניתוסף המזון כך בחי' יפתי מראך נאוה כו' והרי המראה הזה שאמר הוא שהזכיר בתחלה הראיני את מראייך שהן בחי' א\"ח דוקא ועלי' א' מראך נאוה וד\"ל, וכל הנ\"ל אינו אלא מצד הירידה שניתוסף האור עי\"ז כו' אך עוד עלי' יותר לע\"ל דכתיב ונגלה<sup data-n=\"2182\">100</sup> כבוד ה' כו' כי עין<sup data-n=\"2183\">101</sup> בעין נראה אתה ה' כו' ולא במראה כו' אמנם זה הגילוי הגדול דעין בעין לא יהי' כ\"א מצד ההכנה שהכינו ישראל תחלה העלא' מ\"ן בגלות להיו' בבחי' א\"ח וכמאחז\"ל אם<sup data-n=\"2184\">102</sup> עושין תשובה נגאלי' כו' לפי שא\"ח זה מעורר בחי' עצמות אור א\"ס שיבא אח\"כ לידי גילוי ממש להיות עין בעין ממש<sup data-n=\"e37\">*</sup> נרא' כו' וד\"ל.",[["2179","97","<b>וסוף מעשה עלה במחשבה תחלה</b>: פיוט לכה דודי."],["2180","98","<b>במי נמלך בנשמתן של צדיקים</b>: רות רבא פ\"ב, ג (בשינוי לשון קצת)."],["2181","99","<b>אשת חיל עטרת בעלה</b>: משלי יב, ד."],["2182","100","<b>ונגלה כבוד ה'</b>: ישעי' מ, ה."],["2183","101","<b>עין בעין נראה</b>: שלח יד, יד."],["2184","102","<b>אם עושין תשובה נגאלים</b>: ראה סנהדרין צז, ב."],["e37","*","_<b>ממש נראה כנ\"ל וד\"ל</b>: הגהות כ\"ק אדמו\"ר הצ\"צ על סעיף ז: ז. ועי\"ז כי קולך ערב דהנה ע\"י התורה נמשך מוחי' חדשים עליונים יותר דאל\"כ מהו הריוח וכן כל שבת והיינו ע\"י העלי' תחלה קומי לכי אך ענין ערב רווחא לבסומי שכיח כו' כך הוא יותר ערב מבחי' לכו לחמי והיינו בכח התשובה וכן ומראך מצות נאוה יותר. (ע' פרדס ריש ש\"ח שאין כל מצות של כל בנ\"א שוה)."]]],[2100490406,"<h3>וקבל היהודים</h3>\n<b>פורים בעזר\"ה</b>\n<b>וקבל</b><sup data-n=\"2185\">1</sup> היהודים את אשר החלו לעשות<sup data-n=\"2186\">2</sup> וארז\"ל<sup data-n=\"2187\">3</sup> החלו בשעת מ\"ת שאמרו נעשה ונשמע כו'. הנה יפלא מאמר זה מאד איך יתכן שבשעת מ\"ת שעל<sup data-n=\"2188\">4</sup> כל דיבור ודיבור פרחה נשמתן וכו' לא הי' רק התחלה כמ\"ש החלו לעשות ובזמן אחשורוש גמרו ונתקבל אצלם, אך הענין הוא דתחלה צריך להבין מהו כל עיקר ענין מ\"ת ומה שאמרו נעשה<sup data-n=\"2189\">5</sup> ונשמע כו' דהנה לכאורה מה הי' חידוש<sup data-n=\"2190\">6</sup> במ\"ת שהרי אברהם קיים ג\"כ כל התורה עד שלא ניתנה כמשארז\"ל קיים<sup data-n=\"2191\">7</sup> אברהם כל התורה כו' שנא' עקב<sup data-n=\"2192\">8</sup> אשר שמע אברהם בקולי כו'. אך הנה עיקר עבודת אברהם הי' בבחי' רצוא ושוב שנאמר בו הלוך<sup data-n=\"2193\">9</sup> ונסוע כו' פי'<sup data-n=\"2194\">10</sup> הלוך הוא בחי' רצוא ונסוע בבחי' שוב כו' כי מדרגתו היתה במדת האהבה שהוא הדביקו' ויש באהבה ב' מדרגו' הא' בבחי' רצוא<sup data-n=\"2195\">11</sup> והוא בבחי' אור חוזר כענין כלה<sup data-n=\"2196\">12</sup> שארי ולבבי כו' והב' בבחי' שוב בבחי' הביטול שנסוג אחור כו' כמאמר הידוע בס\"י<sup data-n=\"2197\">13</sup> אם רץ לבך שוב כו' והוא בחי' אור ישר, והנה הטעם לעבודה זאת שהיא בבחי' רצוא ושוב דוקא הענין הוא לפי שבהשתלשלו' יש ב' מדרגו' א' בחי' ממלא כ\"ע והב' בחי' סובב כ\"ע כידוע והנה להבין ולהשכיל היטב בבחי' ממלא וסובב צריך להקדים הפסוק יהללו<sup data-n=\"2198\">14</sup> את שם הוי' כי הוא צוה ונבראו כו' ולכאורה אינו מובן מה שאמר ונבראו<sup data-n=\"2199\">15</sup> לשון וענין ממילא ומאליו שממילא ומאליו נבראו ומהו ענין התהוות הבריאה &lt;קכא&gt;\nממילא ולמה לא אמר כי הוא ציוה ובר\"א כמו שאמר בכל מקום ברא כמו בראשית בר\"א כו' וכיוצא אך הענין הוא כידוע שכל התהוות העולמו' כולן הוא רק מבחי' שמו ית' וכמ\"ש יהללו את שם",[["2185","1","<b>וקבל היהודים</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (יא, א). הנחה אחרת נדפסה בתו\"א צו, ג.\nוראה שערי אורה שער הפורים פח, ב.\nהמאמר עם הגהות נדפס באוה\"ת מג\"א ע' קנו ואילך. קעא ואילך.\nלכמה ענינים שבמאמר זה ראה גם סה\"מ תקס\"ד ע' סא ואילך. סה\"מ תקע\"א ע' קלה. וראה לקמן (ע' שפה) ביאור על מאמר זה. הנחת ר' משה בן אדה\"ז נדפס לקמן ע' שכו."],["2186","2","<b>וקבל היהודים את אשר החלו לעשות</b>: אסתר ט, כג."],["2187","3","<b>וארז\"ל החלו בשעת מ\"ת</b>: ראה שבת פח, א. שבועות לט, א. וראה סה\"מ מלוקט ח\"א ע' שיז."],["2188","4","<b>שעל כל דיבור ודיבור פרחה נשמתן</b>: שבת פח, ב. מאמרי אדה\"א ויקרא ח\"א ע' ג. וש\"נ. נ\"ך ע' שפא וש\"נ. תו\"ח בראשית יז, ב."],["2189","5","<b>נעשה ונשמע</b>: משפטים כד, ז."],["2190","6","<b>חידוש במ\"ת. . אברהם קיים</b>: ראה גם תו\"א עג, ג-ד."],["2191","7","<b>קיים אברהם כל התורה</b>: קידושין פב, א. לקו\"ש כרך לה ע' 107 ואילך."],["2192","8","<b>עקב אשר שמע אברהם בקולי</b>: תולדות כו, ה."],["2193","9","<b>הלוך ונסוע</b>: לך לך יב, ט."],["2194","10","<b>פי' הלוך</b>: ראה זהר לך פ, א. פד, א. תו\"א יתרו עג, ד."],["2195","11","<b>רצוא. . בבחי' אור חוזר. . שוב. . אור ישר</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ע' רפז. סידור שער התפילין יז, ב. אמרי בינה קב, ד."],["2196","12","<b>כלה שארי ולבבי</b>: תהלים עג, כו."],["2197","13","<b>בס\"י אם רץ לבך שוב</b>: פ\"א, מ\"ח. תקו\"ז בהקדמה (ז, א)."],["2198","14","<b>יהללו את שם הוי' כי הוא צוה ונבראו</b>: תהלים קמח, יג. וראה תו\"א מג\"א צו, א. לקו\"ת ראה כו, ד. סידור שחרית סו, ג."],["2199","15","<b>ונבראו. . ובר\"א</b>: ראה לקו\"ת שה\"ש יד, ג."]]],[2100490407,"ה' כי הוא ציוה כו' פי' כי הוא קאי אדסמיך לי' דהיינו שם הוי' והגם שהוא בחי' סובב כ\"ע מ\"מ אינו אלא בחי' שם בלבד לגבי עצמו' אור א\"ס ב\"ה כי אינו בחי' סובב*<sup data-n=\"2200\">*15</sup> רק לפי ערך ההשתלשלו' בבחי' ממלא וא\"כ גם הוא נחשב בכלל בחי' השתלשלו' ההשפעה ואין לו ערך ויחוס לגבי העצמו' כו' ואמנם בזה יתרון מעלתו על בחי' ממלא במה שנק' סובב שהוא בחי' מקיף לכל העולמו' בהשווא' א' מכל צד כעיגול השמים ואין בו בחי' מעלה ומטה כידוע וזהו הטעם עצמו שנזכר בו ענין התהוו' הבריאה ממילא וכמ\"ש ונבראו ולא אמר ברא כו' כי הנה דוקא בבחי' ממלא כ\"ע שהוא בא בבחי' השתלשלו' מעילה לעילה ובכללו' נק' בשם כח הפועל בנפעל כידוע שייך לומר בו ברא כלומר שבורא מאין ליש מפני שהוא ממלא כל עלמין כמו בחי' כח הפועל בנפעל באדם התחתון שמכח הפועל ממש ימצא מציאת הפעולה כו' אבל בבחי' סובב אחר שהוא נבדל מבחי' השתלשלו' מעילה לעילה ונק' סובב להיותו רק בבחי' מקיף כנ\"ל א\"כ איך שייך לומר בו בר\"א שפי' בר\"א הוא מה שבורא יש מאין והרי הוא מובדל מערך ההשתלשלו' מלהיו' נקרא כח הפועל בנפעל כו' ולכך נאמר בו כי הוא ציוה ונבראו פי' ממילא נמצאו למטה כי ההתהוו' שלהם מבחי' סובב אינה באה בדרך כח הפועל כו' וד\"ל.\n<b>וזהו</b> שלא נזכר בכל מקום לשון ברא אלא במה שהוא כמו בחי' ממלא כמו בראשית<sup data-n=\"2201\">16</sup> ברא אלקים לפי ששם<sup data-n=\"2202\">17</sup> אלקי' הוא מבחי' ממלא כ\"ע כידוע וגם הוא נחשב מז'<sup data-n=\"2203\">18</sup> שמות שאינן נמחקין כידוע אבל הוא בחי' כח הפועל בנפעל כידוע דאלקי'<sup data-n=\"2204\">19</sup> מלשון כח הוא כמו יש לאל ידי כו' וכמ\"כ שם אד' אבל שם הוי' עפ\"י הרוב אינו נזכר רק בבחי' סובב כ\"ע וכן מ\"ש כאן יהללו את שם הוי' דקאי בבחי' סובב לכך אמר ונבראו ממילא ולא אמר ברא וד\"ל.\n<b>והנה</b> כאשר השיג אברהם בבחי' סובב כ\"ע לכך היתה עבודתו בבחי' רצוא ושוב כמ\"ש הלוך ונסוע כו' כי בחי' סובב כ\"ע הרי הוא למעלה מבחי' התהוו' נברא בדרך השתלשלו' כנ\"ל וא\"כ הרי גם למטה במי שחפץ לידבק בבחי' סובב לא יוכל ליגבל אור האהבה בכלי אלא הוא תמיד בבחי' רצוא ושוב דהיינו שרוצה לצאת מן הכלי וחוזר האור למקורו וכמ\"ש כלה שאירי כו' ואע\"פ שחוזר האור ומתיישב בבחי' שוב מיד חוזר האור כי הוא רצוא ושוב בתמידו' וכמ\"ש והחיו'<sup data-n=\"2205\">21</sup> רצוא ושוב כמראה הבזק ומראה הבזק ידוע שהלהב עולה תמיד כו' וכמ\"ש במ\"א",[["2200","*15","<b>סובב רק לפי ערך ההשתלשלות</b>: ראה תניא פמ\"ח. מאמרי אדה\"א דברים ח\"ד ע' א'רפז. וש\"נ. תו\"ח וישב קצט, ד."],["2201","16","<b>בראשית ברא אלקים</b>: בראשית א, א."],["2202","17","<b>ששם אלקים הוא מבחי' ממלא כ\"ע</b>: ראה תו\"ח וישב קצט, ד. ובהערה 62. וארא קז, א. וש\"נ."],["2203","18","<b>מז' שמות שאינן נמחקין</b>: ראה תו\"א י, ב — בכהאריז\"ל ובפרדס. ראה שולחן ערוך אדה\"ז או\"ח ספ\"ה, ס\"ג. לקו\"ש חכ\"א ע' 195 הערה 60."],["2204","19","<b>דאלקים מלשון כח</b>: ראה שו\"ע אדה\"ז חאו\"ח ס\"ה ס\"ג. אוה\"ת יתרו ע' תשנא. תו\"ח וארא קט, ב.\n20 יש לאל ידי: ויצא לא, כט."],["2205","21","<b>והחיות רצוא ושוב</b>: יחזקאל א, יד. ראה גם תו\"ח בשלח רל, ב."]]],[2100490408,"וד\"ל ולע\"ל כתיב כי<sup data-n=\"2206\">22</sup> עין בעין יראו כו' היינו שיתגלה למטה בחי' סובב כ\"ע וזהו ונגלה<sup data-n=\"2207\">23</sup> כבוד הוי' כו' וע\"כ כתיב בהם אז בבכי<sup data-n=\"2208\">24</sup> יבאו כו' אז דוקא בבכי יבאו ולא מקדמת דנא והוא שמחמת גילוי בחי' סובב אין אור האהבה מתיישבת בכלי הלב ובכלי המוח כלל וע\"כ מפני דחיקת המוח שלא יוכל לסבול אור האהבה ואור ההשגה יצא מן המוח בחי' המותרו' והן הדמעות כידוע<sup data-n=\"2209\">25</sup> שסיבת ירידת דמעות הוא מפני דחיקת המוח כאשר אין כלי המוח יכול לסבול אם רוב שמחה יותר מדאי או רבוי צער כו' אך מה שהוא &lt;קכב&gt;\nלמעלה מן הכלי כענין ר' עקיבא<sup data-n=\"2210\">26</sup> שזלגו עיניו דמעו' כששמע רזין דאוריי' מר' אליעזר וכיוצא וכמ\"ש במ\"א וזה הענין מופת גמור למה שמבואר למעלה דבבחי' סובב לא יוכל האור להיו' מוגבל בכלי וע\"כ הי' אברהם הלוך ונסוע כו' שהוא בחי' רצוא ושוב וד\"ל וזהו שקיים אברהם כל התורה עד שלא ניתנה כו' והוא בבחי' רו\"ש לפי שהשיג בבחי' סובב שזהו קוטב ויסוד העיקר שבכל התורה והמצות דהנה ענין המצו' ברמ\"ח<sup data-n=\"2211\">27</sup> פקודי' שנק' רמ\"ח איברי' דמלכא היינו בחי' הכלים לאורו' למעלה להיו' נק' חסד<sup data-n=\"2212\">28</sup> דרועא ימינא כו' כמשל האבר שמקבל חיו' הנפש ומתיישב בו האור כו' ושרש כל החיו' של כל האיברים נמשך מן המוח כידוע ולכך ת\"ת<sup data-n=\"2213\">29</sup> כנגד כולם לפי שהתורה שרשה בחכמה עילא' כידוע דאורייתא<sup data-n=\"2214\">30</sup> מחכמה עילא' נפקת כו' וגם במצות<sup data-n=\"2215\">31</sup> יש בחי' רצוא ושוב הנ\"ל א' בבחי' אור חוזר<sup data-n=\"2216\">32</sup> וא' בבחי' אור ישר והיינו רמ\"ח מ\"ע שהם בחי' ה\"ח בכלל כידוע לכך עיקר ענינם בכלים דוקא ושס\"ה ל\"ת הן מבחי' ה\"ג בכלל ולכך הם בבחי' מניעת האור מלבא בכלי כענין לא<sup data-n=\"2217\">33</sup> תלבש שעטנז כו' וכמ\"ש במ\"א וזהו ג\"כ ענין הלוך ונסוע שבעבודת אברהם ולכך קיים כל התורה כו' והיינו שאמרו בשעת מ\"ת נעשה ונשמע דהיינו עשי' בתחלה ואח\"כ שמיעה והוא כלים תחלה ואח\"כ שמיעה כידוע המאמר",[["2206","22","<b>כי עין בעין יראו</b>: ישעי' נב, ח."],["2207","23","<b>ונגלה כבוד הוי'</b>: ישעי' מ, ה."],["2208","24","<b>בבכי יבואו</b>: ירמי' לא, ח. ראה מאמרי אדה\"א דברים ח\"ג ס\"ע א'צג ואילך."],["2209","25","<b>כידוע שסיבת ירידת דמעות</b>: ראה מאמרי אדה\"א דברים ח\"ג ע' תתקנז, וש\"נ. נביאים וכתובים ע' קסד."],["2210","26","<b>ר' עקיבא שזלגו עיניו דמעות</b>: ראה ט\"ז הל' שבת סרפ\"ח סק\"ב: ברע\"ק בזוהר חדש שהי' בוכה מאד באמרו שיר השירים. תורה אור וישלח כו, א ובמקבילות לשם במאמרי אדה\"ז תקס\"ה ח\"א ע' עט (בב' הנוסחאות): בזוהר שה\"ש. באמרי בינה (קה\"ת תשמ\"ה) שער התפילין קיא, ב: בזהר. מאמרי אדה\"ז הקצרים ע' תמח (ושם: בזהר. . פסוק [בשה\"ש] סמכוני באשישות. ראה זהר (מדרש הנעלם) וירא צח, ב). לקוטי תורה תצא לז, ד: שאמרו רז\"ל. . כשהשיג סודות התורה בשה\"ש. ובמקבילות לשם בספר המאמרים תקס\"ה ח\"ב ע' תתמא (תקס\"ח ח\"ב ע' תקלה): במה\"נ [במדרש הנעלם. ראה מדרש הנעלם וירא הנ\"ל, ושבזהר חדש בראשית ז, א]. וראה גם רקאנטי ויחי (לז, ד) ד\"ה: ספר הזהר תא חזי: תמצא בספר הזהר. . בגילוי נסתרות קם רבי פלוני ובכה."],["2211","27","<b>ברמ\"ח פיקודי'. . רמ\"ח אברי' דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א)."],["2212","28","<b>חסד דרועא ימינא</b>: ת\"ז בהקדמה (יז, א)."],["2213","29","<b>ת\"ת כנגד כולם</b>: פאה רפ\"א."],["2214","30","<b>דאורייתא מחכמה עילאה נפקת</b>: זהר בשלח סב, א. יתרו פה, א (ח\"א מה\"מ נא). משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["2215","31","<b>במצות. . אור חוזר ואור ישר</b>: ראה קו\"א לתניא (להבין מ\"ש בפרע\"ח) קנח, ב."],["2216","32","<b>אור חוזר. . אור ישר</b>: ראה עץ חיים שער (כה) דרושי הצלם דרוש ו."],["2217","33","<b>לא תלבש שעטנז</b>: תצא כב, יא."]]],[2100490409,"דנעוץ<sup data-n=\"2218\">34</sup> תחלתן בסופן פי' בסוף מעשה דוקא וזהו גבורי כח עושי דברו ואח\"כ לשמוע בקול דברו וד\"ל.\n<b>וזהו</b> שארז\"ל את אשר החלו לעשות זה מ\"ת כו' כי ע\"י שאמרו נעשה ונשמע הי' התלבשו' האורות בכלים כנ\"ל דנעשה שאמרו שהוא בחי' עשי' היינו לעשות בחי' הכלים תחלה משום דנעוץ תחלתן בסופן בסוף מעשה דוקא כו' רק שאז בשעת מ\"ת לא הי' רק בחי' התחלת המעשה לעשות בחי' הכלים וכמו שאמרו נעשה כו' אבל עדיין לא עשו גמר המלאכה אמנם בזמן אחשורוש קיבלו היהודים את אשר החלו דהיינו שגמרו את אשר התחילו בזמן מ\"ת כו' והטעם לזה הוא לפי שבימי אחשורוש הי' להם בחי' מס\"נ<sup data-n=\"2219\">35</sup> גמור כל אותה השנה דגזרת המן שהרי כל אותה השנה נחלט אצלם שהמה נתונים מדת המלך ליהרג כולם ובודאי היה מוחלט אצלם שלא להמיר דת גם שיהרגו ויאבדו כולם ולא עלה על לבם מחשבת חוץ ח\"ו וא\"כ עמדו במס\"נ אמיתי' כל ימי' אותה השנה במה שקיבלו עליהם הריגה בלב שלם ולא יעבורו דתם וידוע דבחי' מס\"נ הוא יציאת האור מן הכלי ועלו מס\"נ למעלה מעלה בבחי' א\"ח עד שנמשך להם אח\"כ האור ממקום היותר גבוה ונתיישב בכלים שלהם כי כל היותר גבוה יוכל יותר להשפיל א\"ע והיינו שנמשך להם התורה בבחי' לבוש כמ\"ש יביאו<sup data-n=\"2220\">36</sup> לבוש מלכות כו' שהוא התורה דכתיב בה עוטה<sup data-n=\"2221\">37</sup> אור כשלמ\"ה ואין<sup data-n=\"2222\">38</sup> אור אלא תורה כו' וכמ\"כ במעשה המצו' שהן בחי' כלים<sup data-n=\"2223\">39</sup> מכלים שונים ובכלל נק' בחי' סוס<sup data-n=\"2224\">40</sup> אשר רכב עליו המלך כי האור<sup data-n=\"2225\">41</sup> נק' רוכב והכלי שמלביש לאור נק' סוס וזהו יביאו לבוש מלכות אשר לבש בו המלך הוא אור התורה שנתעטף בלבוש דתורה כמ\"ש עוטה אור כו' וסוס אשר רכב עליו המלך היינו רמ\"ח מ\"ע דנק' רמ\"ח &lt;קכג&gt;\nאיברים דמלכא עילא' כו' וד\"ל.\n<b>וביאור</b> הדברים יותר הנה כתיב כי<sup data-n=\"2226\">42</sup> תרכב על סוסיך מרכבותיך ישועה פי' סוסיך ב' סוסים א' מרומם את הרוכב וא' שמורידו כי עד\"מ הסוס שרץ למעלה בגובה ההר וכן רץ למטה בעומק כו' והנמשל מובן למעלה דכמו שיש בכלי המרכבה מעלה יתירה מה שנושא את הרוכב כך בחי' מרכבה העליונה שבכלים שממעשה המצות יש בהן מעלה יתירה שמגביהין ומנשאי' את האורות שנק' רוכב וזהו כי תרכב על סוסיך מרכבותיך ישועה שיש ישועה לרוכב עי\"ז כו' וד\"ל, אך ב\"פ סוס יובן ממה שגם בסוס אחד יש ב' מדרגו' הללו דהעלא' וההמשכה כנ\"ל במשל",[["2218","34","<b>דנעוץ תחלתן בסופן</b>: ראה ס\"י פ\"א, מ\"ז."],["2219","35","<b>מס\"נ גמור כל אותה השנה</b>: ראה תו\"א צז, א. ד\"ה בלילה ההוא נדדה תשמ\"ד ס\"ו ובהערה 56 (סה\"מ מלוקט ח\"ב ע' ער)."],["2220","36","<b>יביאו לבוש מלכות</b>: אסתר ו, ח."],["2221","37","<b>עוטה אור כשלמה</b>: תהלים קד, ב."],["2222","38","<b>ואין אור אלא תורה</b>: תענית ז, ב."],["2223","39","<b>כלים מכלים שונים</b>: לשון אסתר א, ז."],["2224","40","<b>סוס אשר רכב עליו המלך</b>: לשון אסתר ו, ח."],["2225","41","<b>האור נק' רוכב</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע קנה ואילך (נוסח א'). תקס\"ז ע' יד. הנחת הר\"פ ע' א."],["2226","42","<b>כי תרכב על סוסיך מרכבותיך ישועה</b>: חבקוק ג, ח."]]],[2100490410,"הגשמי בסוס הגשמי וזהו גי' דסוס<sup data-n=\"2227\">43</sup> ב\"פ ס\"ג כי יש בו ב\"פ ס\"ג והוא א' באור חוזר וא' באור ישר וענין ס\"ג הוא שם ס\"ג<sup data-n=\"2228\">44</sup> שהוא בחי' גיאות והתנשאו' וכמ\"ש כולו סג<sup data-n=\"2229\">45</sup> יחדיו נאלחו כו' וענין התנשאות זו הוא להיות למעלה בחי' מלך המרומם המתנשא מימות עולם ואז הוא נק' רם<sup data-n=\"2230\">46</sup> על כל גוים כלומר שמסתלק ומתנשא מהם ונק' גאה<sup data-n=\"2231\">47</sup> גאה כתרגומו גיאה על גיוותניא פי' דוקא על גיאים כמו הגוים הוא גאה ומתנשא עליהם כלומר שמסתלק מהם כמ\"ש רם על כל גוים בבחי' רוממות והתנשאות משא\"כ על ישראל שהם שפלים ונמשלים לעפר כמ\"ש אברהם ואנכי<sup data-n=\"2232\">48</sup> עפר ואפר אדרבה דוקא בהם הוא שוכן ומתלבש מן ההעלם לגילוי וכמ\"ש אל<sup data-n=\"2233\">49</sup> זה אביט אל עני ונכה רוח כו' את מי אשכון<sup data-n=\"2234\">50</sup> את דכא ושפל רוח כמאמר<sup data-n=\"2235\">51</sup> דיורא דקדב\"ה באינון מאנין תבירי' וזהו היפך הגיאים שעל הגיאים הוא גאה ומרומם כו' וזהו*<sup data-n=\"2236\">*51</sup> פי' ונפשי<sup data-n=\"2237\">52</sup> כעפר לכל תהי' פתח לבי בתורתך ולכאורה אין להם שייכו' זע\"ז אך הענין הוא להיות ידוע דפתיחת הלב להיות רעותא דלבא הוא בא ונמשך מלמעלה דוקא וזהו פתח לבי בתורתך כו' ואמנם גילוי אור זה מלמעלה אינו אלא דוקא כשיש בחי' שפלות למטה והוא כאשר נפשו כעפר דוקא ומטעם הנ\"ל דעל גיאי' הוא מתגאה ומתנשא אבל על שפלים הוא משפיל ונמשך בהם כו' וכמ\"ש את מי אשכון את דכא ושפל רוח כו' והנה כל זמן אותה השנה דגזרת המן שהיו משולים לעפר ממש הפקר להריגה לכל מי שירצה לאבד ולהשחית בהם ע\"כ זכו לב' דברים שיתגלה בהם מבחי' עצמו' אור א\"ס ולהיות מתיישב בכלים שלהם והוא מב' טעמי' הנ\"ל הא' מפני בחי' מס\"נ שלהם בבחי' אור חוזר כנ\"ל הוא שעלו ברום המעלות והב' בבחי' אור ישר מה שנמשך ונתקבל בכלים שלהם מטעם שהיו אז בתכלית השפלות ומטעם הנ\"ל, וזהו את אשר החלו לעשות במ\"ת קיימו וקיבלו דוקא בזמן אחשורוש שנעשו בחי' כלים גמורים להשראת עצמו' אור א\"ס מטעמי' הנ\"ל וד\"ל.\n<b>וזהו</b> כי תרכב על סוסיך ב\"פ ג\"ס א' בחי' אור חוזר להיות עי\"ז רם על כל גוים כו' כמ\"ש כי גאה גאה כו' ואח\"כ בחי' אור ישר להיות שוכן בשפלים וה\"ז כמשל הסוס שרץ למעלה ויורד לעומק כו' והכל ענין א' למעלה דלפי שהוא גאה גאה ע\"כ הוא משליך ומשפיל הגיאים ומגביה השפלים כו' וזהו כי תרכב על סוסיך ב\"פ ס\"ג",[["2227","43","<b>דסוס ב\"פ ס\"ג</b>: ראה מאמרי אדה\"א קונטרסים ע' שצ. תו\"ח בשלח רכו, א וש\"נ."],["2228","44","<b>ס\"ג. . גיאות</b>: ראה גם שעה\"י קמא, ב ובהערה 23. תו\"ח שמות רכו, א וש\"נ."],["2229","45","<b>כולו סג יחדיו נאלחו</b>: תהלים נג, ד."],["2230","46","<b>רם על כל גוים</b>: תהלים קיג, ד."],["2231","47","<b>גאה גאה כתרגומו גיאה על גיוותניא</b>: בשלח טו, א ות\"א שם."],["2232","48","<b>ואנכי עפר ואפר</b>: וירא יח, כז."],["2233","49","<b>אל זה אביט</b>: ישעי' סו, ב."],["2234","50","<b>את מי אשכון</b>: ראה ישעי' נז, טו."],["2235","51","<b>כמאמר דיורא דקדב\"ה באינון מאנין</b>: ראה זהר ויקהל ריח, א."],["2236","*51","<b>וזהו פי' ונפשי כעפר</b>: באוה\"ת בלק ע' תתקסא — שייכות עפר לתורה כמ\"ש ונפשי כעפר כו' פתח לבי בתורתך והטעם נתבאר בתורת פורים תקס\"ו, וקבל היהודים כי הוא ית' נק' גאה על גוותניא ר\"ל שמסתלק מהם ואת מי אשכון כו' לכן אז בימי אחשורוש שהי' בתכלית השפלות זכו לבחי' הדור קבלוה דתורה כי תרכב על סוסיך ע\"ש."],["2237","52","<b>ונפשי כעפר לכל תהי'</b>: תפלת אלקי נצור (סיום תפלת העמידה. ברכות יז, א)."]]],[2100490411,"אזי מרכבותיך ישועה להשפיל הגיאים כו' וד\"ל, וזהו ג\"כ פי' סוס<sup data-n=\"2238\">53</sup> ורוכבו רמה בים שיש בפי' רמה<sup data-n=\"2239\">54</sup> ב' ענינים הנ\"ל א' ענין רוממות וא' ענין השלכה וכמ\"ש במ\"א והא בהא תליא מטעם הנ\"ל וד\"ל.\n<b>ובכל</b> זה יובן &lt;קכד&gt;\nמה שעיקר קיום התורה והמצות תלוי בישראל דוקא כי הרי הגוים*<sup data-n=\"2240\">*54</sup> הגם שיקיימו כל המצות אינם ממשיכים כלום והראי' לזה ממצות הצדקה דכתיב וחסד<sup data-n=\"2241\">55</sup> לאומים חטאת דאע\"פ שהצדקה מצוותה היא להחיות<sup data-n=\"2242\">56</sup> רוח שפלים וא\"כ למה יהי' החסד שעושה הגוי<sup data-n=\"2243\">57</sup> חטא ועון הרי מחי' רוח שפלים בחסד שעושה כמו הישראל ולא עוד אלא שנחשב חסד לאומים כחטאת, אך הענין הוא משום דמצות<sup data-n=\"2244\">58</sup> צריכות כונה ופי' כונה היינו רעותא דלבא כענין פתח לבי כו' וזה א\"א כ\"א בחי' שפלות דוקא וכנ\"ל בענין ונפשי כעפר לכל תהי' אז דוקא פתח לבי כו' והנה בישראל יש ירושת מדת השפלות מן האבות ובפרט מאברהם שאמר ואנכי עפר ואפר משא\"כ אוה\"ע שירושתם מאבותיהם מבחי' הגסות דוקא ולכך נא' בהם רם על כל גוים כו' כלומר שמסתלק מהם ועל כן הגם שיעשו המצוה אין בהם הכונה ברעותא דלבא לפי שמסתלק מן הגיאים כנ\"ל ולכך אינם ממשיכים כלום ואע\"פ שחסד זה מחי' רוח שפלים אין בו גילוי אלקו' כלל כצדקה וחסד שישראל עושה מפני שהישראל יש לו כונה והוא מפני השפלות ובלא רעותא דלבא אין שום המשכה מלמעלה שהרי נא' אם<sup data-n=\"2245\">59</sup> ישים אליו לבו רוחו ונשמתו אליו יאסוף פי' אם ישים אליו לבו דוקא ברעותא דלבא אזי רוחו ונשמתו של הקדב\"ה אליו יאסוף לשכון בו בבחי' דירה והשרא' כו' ולא כשאינו משים אליו לבו, ואוה\"ע אין ביכולתם זה מצד הגסו' וא\"כ אדרבה מן החסד שלהם ניתוסף חיות ואור להיכלות החיצונים<sup data-n=\"2246\">60</sup> דנוג\"ה מפני שזה החסד מטוב שבנוג\"ה כו' ולכך נק' חטאת וכמ\"ש לפתח<sup data-n=\"2247\">61</sup> חטא\"ת רובץ כו' וד\"ל.\n<b>וזהו</b> שאמר המן יביאו<sup data-n=\"2248\">*61</sup> לבוש מלכות אשר לבש בו המלך כו' ונתון הלבוש והסוס ע\"י איש משרי המלך הפרתמים כו'. דהנה פי' לבוש זה הנק' לבוש מלכות מבואר למעלה שהוא אור לבוש דתורה והסוס אשר רכב עליו המלך כו' הן רמ\"ח מ\"ע שזה שייך דוקא לישראל מטעם הנ\"ל והוא אשר אנו אומרים בדרך הודאה בברכות כל המצות אשר קדשנו במצוותיו קדשנו דוקא וקדושה זו היא בחי' רוממות קדושה העליונה דהיינו כמ\"ש כי גאה גאה כנ\"ל, והנה המן רצה שיומשך בחי' קדש זה אליו מצד הגסו' שהי' בו ולכך אמר למי<sup data-n=\"2249\">62</sup> יחפוץ המלך לעשות יק\"ר יותר ממני כי קדש זה",[["2238","53","<b>סוס ורוכבו רמה בים</b>: בשלח טו, א."],["2239","54","<b>רמה. . ענין רוממות. . ענין השלכה וכמ\"ש במ\"א</b>: ראה גם תו\"ח בשלח רלז, ב וש\"נ."],["2240","*54","<b>הגוים. . אינם ממשיכים כלום</b>: ראה גם סה\"מ תקע\"א ע' לה. מאמרי אדה\"א שמות ח\"א ע' ו. וש\"נ."],["2241","55","<b>וחסד לאומים חטאת</b>: משלי יד, לד."],["2242","56","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["2243","57","<b>הגוי חטא ועון</b>: ראה לקו\"ש ח\"כ ע' 102 הערה 28."],["2244","58","<b>דמצות צריכות כוונה</b>: עירובין צה, סע\"ב."],["2245","59","<b>אם ישים אליו לבו</b>: איוב לד, יד."],["2246","60","<b>החיצונים. . נק' חטאת</b>: ראה מאו\"א מערכת חטאת אות כד."],["2247","61","<b>לפתח חטאת רובץ</b>: בראשית ד, ז."],["2248","*61","<b>יביאו לבוש מלכות</b>: אסתר ו, ח."],["2249","62","<b>למי יחפוץ המלך</b>: אסתר ו, ו."]]],[2100490412,"נק' יק\"ר מפני שהוא עטרת תפארת כו' וע\"כ אמר איש אשר המלך חפץ ביקרו יביאו לבוש מלכות אשר לבש בו כו' שהן התורה והמצות, אבל שגה ברואה כי לישראל דוקא ניתנו והם אשר חפץ בהם המלך לעשות יקר זה וכמ\"ש כ\"א חפץ בה המלך ונקראה בשם ולע\"ל כתיב ואתם<sup data-n=\"2250\">63</sup> תהיו לי ארץ חפץ וכן כתיב תקרא<sup data-n=\"2251\">64</sup> חפצי בה כו' וד\"ל.\n<b>וזהו</b> שארז\"ל עתידי'<sup data-n=\"2252\">65</sup> צדיקים שיאמרו לפניהם קדוש כו' כי פי' קדוש<sup data-n=\"2253\">66</sup> בוי\"ו ענין המשכה הוא מבחי' קדש העליון הנ\"ל כי כל וי\"ו הוא מורה ענין המשכה מן ההעלם לגילוי אור כידוע וע\"י מעשה המצות נמשך בהם מבחי' קדש העליון כמו שאו' אשר קדשנו במצוותיו כו' עד שהמלאכי' יאמרו &lt;קכה&gt;\nלפניהם קדוש והוא כמו ענין לעשות יקר למי שהמלך חפץ ביקרו שמביאים לבוש מלכות שלבש בו המלך כו' וד\"ל. והנה עוד אמר המן ונתון<sup data-n=\"2254\">67</sup> הלבוש והסוס ע\"י איש כו' פי' איש משרי המלך הפרתמים הוא מיכאל<sup data-n=\"2255\">68</sup> כהנא רבא שהוא מלביש בג\"ע את כל הנשמות בלבושי יקר של מעשה המצות שעשו בעוה\"ז כמבואר<sup data-n=\"2256\">69</sup> במדרש וגם בספרי המקובלים והיינו לפי שמיכאל<sup data-n=\"2257\">70</sup> זה הוא בחי' ענף החסד ולכך נק' כהנא רבא וע\"כ על ידו נמשך האור להלביש את כל נשמה ונשמה אשר המלך חפץ ביקרה בג\"ע כו' בלבוש מלכות שלבש בו המלך כו' וזהו ונתון הלבוש והסוס ע\"י איש משרי המלך הפרתמים דוקא כי זהו יקר וכבוד הרבה ביותר כשלבוש מלכות נתון ע\"י מיכאל שר המלך כו' משהי' נתון ע\"י זולתו וד\"ל.\n<b>וזהו</b> וקבל היהודים את אשר החלו לעשות כו' וקבל לשון יחי' כו'. דהנה מבואר למעלה דע\"י מס\"נ שהי' להם כל אותה השנה וע\"י השפלות זכו להיו' אור העליון שבתורה ומצות להתקבל ולהתיישב בהן וזהו וקבל היהודים את אשר החלו כו', אך עדיין יש להבין מהו שאמר וקבל לשון יחיד, וגם מה שאמר היהודים מה זה שקורא אותם עכשיו בזמן גלות אחשורוש בשם יהודים דוקא ולא בשם ישראל או יעקב כמו בשאר הנביאי' וכתובי' ובמגלת אסתר אינם נקראי' רק בשם יהודים כמו ליהודים<sup data-n=\"2258\">71</sup> היתה אורה כו'.\n<b>אך</b> הנה הב' קושיו' הללו יתורצו בהקדמה אחת והוא אשר מצינו בשעת מ\"ת שהיו כל ישראל בענין האחדות האמיתי עד שלא נחשבו במדרגת רבים כלל אלא רק כמו איש אחד בלבד שהרי נאמר ויחן<sup data-n=\"2259\">72</sup> שם ישראל נגד ההר כו' ופי' ויחן<sup data-n=\"2260\">73</sup> הוא",[["2250","63","<b>ואתם תהיו לי ארץ חפץ</b>: מלאכי ג, יב."],["2251","64","<b>תקרא חפצי בה</b>: ישעי' סב, ד."],["2252","65","<b>עתידים צדיקים שיאמרו לפניהם קדוש</b>: ראה בבא בתרא עה, ב."],["2253","66","<b>קדוש בוי\"ו ענין המשכה</b>: ראה תו\"א כאן צז, ריש ע' ד. קכו, א. לקו\"ת נצבים נ, ב. מאמרי אדה\"א הנחות תקע\"ז ע' רסג, וש\"נ."],["2254","67","<b>ונתון הלבוש והסוס</b>: אסתר ו, ט."],["2255","68","<b>מיכאל כהנא רבא</b>: ראה זהר (ס\"ת) לך פ, סע\"א ואילך."],["2256","69","<b>כמבואר במדרש וגם בספרי המקובלים</b>: נסמן במאמרי אדה\"א בראשית ע' נו."],["2257","70","<b>שמיכאל. . ענף החסד</b>: ראה גם תו\"א מג\"א צו, ד. שערי אורה צג, א."],["2258","71","<b>ליהודים היתה אורה</b>: אסתר ח, טז."],["2259","72","<b>ויחן שם ישראל נגד ההר</b>: יתרו יט, ב."],["2260","73","<b>ויחן הוא בלשון יחיד</b>: פרש\"י עה\"פ. וראה מכילתא שם."]]],[2100490413,"בלשון יחיד כאילו הם כולם איש אחד ולא אמר ויחנו כו' לשון רבים כו' והענין הוא לפי שאנו<sup data-n=\"2261\">74</sup> או' ברכינו אבינו כולנו כאחד באור פניך דוקא כולנו כאחד שכאשר כולנו כאיש א' בתכלית האחדו' אזי יברכנו באור פניו שהוא אור קבלת התורה וכמו שמפרש כי באור פניך נתת לנו תורת חיים כו' והטעם הוא לפי שאור פני אלקי' חיים שבתורה הוא בתכלית היחוד העליון הנק' אחד פשוט כי אין התלבשו'<sup data-n=\"2262\">75</sup> אור א\"ס אלא בחכמה כו' לכך לא היו יכולי' לקבל הארת הפנים שבמ\"ת כ\"א כאשר היו ג\"כ בבחי' האחדו' בתכלית כאיש א' ולא בבחי' רבים שהוא בחי' הפירוד היפך היחוד כו' כדי למהוי<sup data-n=\"2263\">76</sup> אחד באחד כו' ואזי הי' אור פנים העליונים מאירי' בהם וכמ\"ש באור<sup data-n=\"2264\">77</sup> פניך כי רציתם כו' וד\"ל.\n<b>אך</b> מהיכן הי' בהם אחדו' האמיתי' הזאת עד שלא הי' בהם בחי' רבים כלל, הענין הוא לפי שכל עיקר סיבת בחי' הפירוד דרבים נמצא מסיבת ההתחלקו' אורו' בריבוי הכלים וכמו התחלקות אור השכל בצרופי אותיו' הרבה כו' ועד\"ז גם השכל לגבי עצמות הנפש שהרי מתחלק האור השכלי לכמה אופני' שונים כי לא יוכל לחשוב שכל אחד באופן א' בלבד כו' כי גוף השכל ג\"כ יוצא מחודש ממקורו בריבוי התחלקו' ומזה יובן בכללו' נש\"י שכל א' הרי שכלו והשגתו מיוחדת מזולתו וכמ\"ש בזוהר<sup data-n=\"2265\">78</sup> ע\"פ נודע בשערים בעלה כל חד לפום למאי דמשער כו' דהיינו כאו\"א לפי השגתו כו' ויש ס\"ר ניצוצו' בהתחלקו' ואמנם כאשר כולם מתייחדי' והיו &lt;קכו&gt;\nלאחדי' בתכלית אין זה כ\"א כאשר כאו\"א יוצא מבחי' השגת שכלו אלא מגיע לבחי' רעותא דלבא שהוא נקודת הרצון שבלב שהוא למעלה מבחי' התחלקו' בשכל ומחשבה אלא הוא פשוט בתכלית ואזי כללו' נ\"י אין בהם בחי' פירוד כלל כי בבחי' רעותא דלבא שלמעלה מן האותיו' שם כולם כאחד בהשווא' א' ואזי אור פנים העליונים דאחדו' הפשוטה מאיר בהם למהוי אחד באחד כו' ועד\"ז הי' ג\"כ בזמן הגזרה דהמן כי מפני בחי' מס\"נ שהי' להם יצאו כולם מגדר שכל והשגה שבאותיו' אלא נתדבקו בו ית' בבחי' רצון פשוט שכולם משתווי' בו יחד כאילו אינו אלא רצון א' מאיש א' כו' ואזי הגם שנא' כי<sup data-n=\"2266\">79</sup> לא יראני האדם כו' כי<sup data-n=\"2267\">80</sup> לית מחשבה תפיס' בי' כלל אעפ\"כ ברעותא דלבא הוא נתפס ולכך עין בעין נגלה עליהם בשעת מ\"ת כידוע וזהו באור פניך כי רציתם וגם בזמן אחשורוש היו כולם בתכלית היחוד ולכך נא' בהם וקבל לשון יחיד דוקא וד\"ל.\n<b>ובזה</b> יתורץ גם הקושיא השני' למה לא נזכרו במגלת אסתר רק בשם יהודים כו' דהנה פי' יהודים היינו לשון הודי' כי יש ב'<sup data-n=\"2268\">81</sup> מדרגות ברכה והודאה כידוע,",[["2261","74","<b>שאנו אומרים ברכנו. . כי באור פניך</b>: בסיום תפלת העמידה [בדילוג]."],["2262","75","<b>התלבשו' אור א\"ס אלא בחכמה</b>: ראה תניא פל\"ה, בהג\"ה."],["2263","76","<b>למהוי אחד באחד</b>: זהר תרומה קלה, סע\"א."],["2264","77","<b>באור פניך כי רציתם</b>: תהלים מד, ד."],["2265","78","<b>בזוהר. . כל חד לפום למאי דמשער בליבי'</b>: זהר וירא קג, רע\"ב. ראה לקו\"ת מסעי פה, ב."],["2266","79","<b>כי לא יראני האדם</b>: שמות לג, כ."],["2267","80","<b>כי לית מחשבה תפיסא בי' כלל</b>: ראה ת\"ז בהקדמה (יז, א)."],["2268","81","<b>ב' מדריגות ברכה והודאה</b>: ראה ג\"כ לקו\"ת מסעי פט, א. עקב טז, ד. ובכ\"מ."]]],[2100490414,"ופי' ברכה הוא ענין המשכה והשפעה שהוא בחי' גילוי אור מן ההעלם כידוע בפי' ברוך<sup data-n=\"2269\">82</sup> ה' מן העולם ועד העולם כו' פי' שיתברך ויומשך מן ההעלם לגילוי דהיינו מעלמא דאתכסיא לעלמא דאתגליא כו' וזהו בכלל ובדרך פרט הנה מסיבת זה ימצא מציאות כל פרטי ההשתלשלות מעילה לעילה עד שנמצאו רבבו' עולמו' והיכלות כמ\"ש ועלמו'<sup data-n=\"2270\">83</sup> אין מספר א\"ת עלמו' אלא עולמו' כו' כמ\"ש במ\"א, אמנם בחי' הודאה היא למעלה הרבה מבחי' ברכה והיינו שהוא מדרגה גבוה מאד נעלה שלמעלה מבחי' ירידת אור מן ההעלם לגילוי אלא הוא בבחי' עצמו' אלקות וכענין המאמר הטוב<sup data-n=\"2271\">84</sup> שמך ולך נאה להודות הרי מבואר דבבחי' שמך הוא ענין ההשתלשלו' במדת הטוב דמטבע<sup data-n=\"2272\">85</sup> הטוב להיטב כו' וזהו הטוב שמך אבל לך נאה להודות פי' לך לעצמותך ומהותך שלמעלה מבחי' שם נאה להודות בבחי' הודאה בלבד שא\"א לבא בבחי' גילוי אור וכמ\"ש הפעם<sup data-n=\"2273\">86</sup> אודה את ה' כו' וכמ\"ש<sup data-n=\"2274\">87</sup> במ\"א באורך ע\"פ יהודה אתה יודוך אחיך וד\"ל, וזהו שנקראו יהודים דוקא כי אז זכו לבחי' הודאה שלמעלה מן ההשתלשלו' אלא הוא בעצמו' אלקו' ולכך נא' ליהודי' היתה אורה כו' וכן וקבל היהודי' כו' והכל מטעם א' לפי שע\"י מס\"נ ברעותא דלבא הגיעו למדרגה שלמעלה מן ההשתלשלו' כנ\"ל וד\"ל.\n<b>וזהו</b> וימי<sup data-n=\"2275\">88</sup> הפורים כו' לא יעברו מתוך היהודים כו'. כי הנה מבואר למעלה דלע\"ל כתיב בבכי יבאו כו' מפני שלא יתיישב האור בכלי המוח והלב ויצא בדמעות כו', אבל בזמן אחשורוש מפני שזכו שיתיישב האור בכלים שלהם כנ\"ל ע\"כ עשו אותם ימי משתה ושמחה דוקא היפך הבכיי' כי מה שלע\"ל לא יוכלו לקבל ואזי בבכי יבאו כו' אבל בימי אסתר יכלו לקבל ולכך עשו אותם ימי משתה ושמחה דוקא כי הנה ענין המשתה והשמחה הוא ענין גילוי אור מן ההעלם כנראה בחוש בעת אשר ישמח האדם יתגלה כל מצפונו כו' וא\"כ הרי יש בחי' כלים לגילוי אורו' והוא היפך הבכיי' שלפי שלא יש כלי יוצא בדמעות כו' וזהו שסמך ענין זה וימי הפורים האלה לא יעברו כו' למה שקדם לומר שעשו אותם ימי משתה ושמחה דלפי &lt;קכז&gt;\nשעשו אותם ימי משתה ושמחה שהוא התיישבו' וגילוי אורו' בכלים לכך ימי הפורים לא יעברו גם לע\"ל וזהו שארז\"ל כל<sup data-n=\"2276\">89</sup> המועדים בטילי' כו' ועיקר הטעם מבואר למעלה למה לא נתיישב האור בכלי אלא בזמן אסתר ומזה הטעם עצמו יובן איך שמפני זה נשארה בחי' רשימ\"ו קיימת ונצחית בכנ\"י להיות המשכה זו של האורו' בכלים",[["2269","82","<b>ברוך ה' מן העולם. . מעלמא דאתכסיא</b>: תהלים קו, מח. דה\"א טז, לו. מאמרי אדה\"א דברים ח\"א ע' קכד. וש\"נ. תו\"ח שמות כה, ב וש\"נ."],["2270","83","<b>ועלמות אין מספר א\"ת עלמות אלא עולמות</b>: שה\"ש ו, ח. ת\"ז בהקדמה (יד, ב). ראה זהר אחרי עא, ב. ע\"ז לה, ב."],["2271","84","<b>הטוב שמך ולך נאה להודות</b>: תפלת העמידה."],["2272","85","<b>דמטבע הטוב להיטיב</b>: ראה מאמרי אדה\"א דברים ח\"ג ע' תתמג, וש\"נ."],["2273","86","<b>הפעם אודה את ה'</b>: בראשית כט, לה."],["2274","87","<b>וכמ\"ש במ\"א באורך ע\"פ יהודה אתה</b>: ראה תו\"א מה, ג."],["2275","88","<b>וימי הפורים כו' לא יעברו מתוך היהודים</b>: אסתר ט, כח."],["2276","89","<b>כל המועדים בטלים</b>: ראה מדרש משלי ט, ב. יל\"ש שם רמז תתקמד."]]],[2100490415,"לעולם בל תמוט וזהו וימי הפורים האלה לא יעברו כו' וזכרם כו' וד\"ל משא\"כ במה שקיבלו האור במ\"ת לא הי' נצחי וכמ\"ש בבכי יבאו כו' אבל אשר קבל היהודי' את אשר החלו כו' הוא שנשאר קיים לעולם וד\"ל."],[2100490416,"<h3>נוסח שני: וקבל היהודים</h3>\n<b></b><b>בעזרת ה' בפורים בסעודה</b>\n<b>וקבל</b><sup data-n=\"2277\">1</sup> היהודים<sup data-n=\"2278\">2</sup> את אשר החלו לעשות זה מ\"ת<sup data-n=\"2279\">3</sup> שהקדימו נעשה<sup data-n=\"2280\">4</sup> לנשמע ואז החלו לעשות כי לא עשו עדיין אלא החלו לעשות במה שאמרו נעשה ונשמע והדר קבלוה בימי אחשורוש דווקא את אשר כבר החלו לעשות כו', וצ\"ל תחילה ענין קבלת התורה בחורב דכתיב וירד<sup data-n=\"2281\">5</sup> ה' על הר סיני כו' שאז החלו לעשות שבשעה שהקדימו נעשה לנשמע כו', והרי אמרז\"ל שקיימו<sup data-n=\"2282\">6</sup> אאע\"ה כל התורה כולה אפי' ע\"ת עד שלא נתנה שנאמר עקב<sup data-n=\"2283\">7</sup> אשר שמע אברהם וישמור משמרתי וחוקותי ותורותי, ומעתה מה החידוש נתחדשה להם בחורב במ\"ת מאחר שאברהם קיימה ג\"כ עד שלא נתנה.\n<b>אך</b> הענין הוא דהנה כתיב באברהם ויסע<sup data-n=\"2284\">8</sup> אברם הלוך ונסוע הנגבה פי' אברם הוא אברהם<sup data-n=\"2285\">9</sup> הי' מרכבה לבחי' החסד שלמעלה ע\"י התקשרותו לה' ית' במדתו מדת האהבה והחסד להיות נמשך אחריו כמים וזהו ויסע הלוך<sup data-n=\"2286\">10</sup> ונסוע שהוא בחי' רו\"ש הנגבה במקום שורש מדת החסד עליון שהוא סט'<sup data-n=\"2287\">11</sup> ימינא בחי' דרום כנודע וזהו הלוך ונסוע בתמידות ממטה למעלה בעילוי אחר עילוי במדריגה אחר מדריגה בבחי' רצו\"ש<sup data-n=\"2288\">12</sup> כמראה הבזק מצד שהאהבה שלו לא היתה יכולה לתפוס בגדר כלי גבולים כלל מפני שהאהבה והחפץ שלו הי' אל מהותו ועצמותו ית' בלבד המרומם<sup data-n=\"2289\">13</sup> לבדו ומתנשא מימות עולם אשר אין<sup data-n=\"2290\">14</sup> לו תחילה ולא תכלה לכך לא היתה יכולה האהבה לתפוס בגדר כלי גבולים ואין לה שיעור כלל לכך הי' הלוך ונסוע בתמידות בעילוי אחר עלוי בבחי' רו\"ש.",[["2277","1","<b>וקבל היהודים</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 735 (קכד, א). הנחת כ\"ק אדמו\"ר האמצעי נדפס לעיל ע' שיז. וראה בהנסמן שם."],["2278","2","<b>וקבל היהודים</b>: אסתר ט, כג."],["2279","3","<b>זה מ\"ת</b>: שבועות לט, א."],["2280","4","<b>נעשה לנשמע</b>: משפטים כד, ז."],["2281","5","<b>וירד ה' על הר סיני</b>: יתרו יט, כ."],["2282","6","<b>שקיימו אאע\"ה כל התורה כולה</b>: קידושין פב, א. לקו\"ש כרך לה ע' 107 ואילך."],["2283","7","<b>עקב אשר שמע אברהם</b>: תולדות כו, ה."],["2284","8","<b>ויסע אברם</b>: לך לך יב, ט."],["2285","9","<b>אברהם הי' מרכבה לבחי' החסד שלמעלה</b>: ראה זהר בראשית מז, ב."],["2286","10","<b>הלוך ונסוע. . רו\"ש</b>: לך לך יב, ט. וראה זהר לך פ, א. פד, א. תו\"א יתרו עג, ד."],["2287","11","<b>סט' ימינא בחי' דרום</b>: ראה זהר במדבר קיח, ב. וראה ג\"כ תו\"א נה, ג. דרך מצותיך קכד, ב. ובכ\"מ."],["2288","12","<b>רצו\"ש כמראה הבזק</b>: יחזקאל א, יד."],["2289","13","<b>המרומם לבדו</b>: ברכת יוצר."],["2290","14","<b>אין לו תחילה</b>: ראה חובת הלבבות שער היחוד פ\"ה. המשך תרס\"ו ע' כ."]]],[2100490417,"<b>והענין</b> הוא דהנה כתיב יהללו<sup data-n=\"2291\">15</sup> את שם ה' כי הוא ציווה ונבראו, פי' כל סדרי השתלשלות העולמות מריש כל דרגין עד סוף כל דרגין כולם יהללו את שם יהו\"ו כי עיקר קיומן וחיותן הוא מבחי' שם הוי' בלבד וכמשל השם של האדם שנק' בשם ראובן או שמעון שאין השם שלו ממהותו ועצמותו ממש כי הרי יכול לחיות ולהתקיים אף בלעדו ואין לו ערך ויחוס אל מהות עצמיות האדם רק הוא הארה והתפשטות ממהותו להיות נפנה לקוראיו בשמו כו', כך עד\"מ החיות של כל הנפעלים מריש כל דרגין עד סוף כל דרגין הוא רק מבחי' שמו הגדול ית' בלבד שהוא בחי' הארה בעלמא ממנו ית' כדכתיב הודו<sup data-n=\"2292\">16</sup> על ארץ ושמים כי נשגב שמו לבדו ולכך כולם יהללו את שם הוי' מקור החיים של כל הנפעלים כי הוא צווה ונבראו הוא בחי' מהותו ועצמותו ית' שנק' בשם הוא ציווה ונבראו, ובראם לא כתיב אלא ונבראו מפני שבאמת אם הי' נמשך החיות שלהן מעצמותו ית' ויתלבש בתוכם ממש הי' נאמר ובראם ממש שהוא מתלבש בתוכם ממש לברוא אותם מאין ליש אבל באמת מהותו ועצמותו ית' מרומם ונשגב לבדו רק הודו על ארץ ושמים שבחי' שמו ית' המתפשט על כל הנפעלים כולן דהיינו מדת מל' ית' המתפשט על כל העולם, שמה שמלך שמו נקרא עליהם זהו ממש הקיום והחיות שלהן ולכך נאמר כי הוא ציווה ונבראו<sup data-n=\"2293\">17</sup> ולא נאמר ובראם כ\"א ונבראו כאילו נבראו ממילא ע\"י הציווי של מהותו ועצמותו ית' בלבד שציווה כביכול שמותיו להפעיל ולברוא אותם ולא שהוא בעצמו ית' מתלבש בתוכם לברוא אותם והיינו כדכתיב במע\"ב בראשית<sup data-n=\"2294\">18</sup> ברא אלקים ששם נאמר ברא ממש דהיינו שהוא שם אלוקים<sup data-n=\"2295\">19</sup> שהוא מדות הצמצום שהוא א' מז'<sup data-n=\"2296\">20</sup> שמות שאינם נמחקים שהוא רק שמו ית' לכך נאמר בו ברא ממש דהיינו שהבורא את הנברא הוא מתלבש בתוך הנברא וימצא בהפועל בחי' כח הפועל ממש שמלובש בהנפעל לקיימו ולהחיותו תמיד, וזה לא יתכן בעצמותו ית' שיהי' הוא בעצמו בחי' כח הפועל שבנפעל שיקרא בעצמו ית' בשם בורא וכח הפועל שבנברא ונפעל עד שיכתב שהוא בראם כו' כ\"א מהותו ועצמותו ית' מרומם לבדו ואני<sup data-n=\"2297\">21</sup> ה' לא שניתי כי אין בין קודם שנברא לאח\"כ, רק שמו ית' הוא המתפשט על כל עלמין להחיותם מצד שעצמותו ית' א\"א להתלבש בתוך כ\"ע ממש לברוא אותם (וגם הי' בחי' שינוי והתפעלות שיתפעל כח הפועל מכח הנפעל כי כל מניע מתנונע כו' כמ\"ש במ\"א) זולת שמו שם אלקים הוא הבורא אותם מאין ליש בציווי ורצון המאציל ב\"ה כדכתיב בכל מע\"ב ויאמר<sup data-n=\"2298\">22</sup> אלקים יהי אור יהי רקיע כו' ולכך נאמר שם לשון ברא ממש אבל מהותו ועצמותו נשגב לבדו ולכך נאמר כי הוא צווה ונבראו לשון ממילא ע\"י שמותיו ית' ולא נאמר ובראם כי",[["2291","15","<b>יהללו את שם ה'</b>: תהלים קמח, ה."],["2292","16","<b>הודו על ארץ ושמים</b>: שם יג."],["2293","17","<b>ונבראו. . ובראם</b>: ראה לקו\"ת שה\"ש יד, ג."],["2294","18","<b>בראשית ברא אלקים</b>: בראשית א, א."],["2295","19","<b>אלקים. . הצמצום</b>: ראה שער היחוד והאמונה פ\"ד."],["2296","20","<b>מז' שמות שאינם נמחקים</b>: במאמרי אדה\"ז על פרשיות התורה ע' סג (ע\"ח). בתו\"א י, ב (כהאריז\"ל ובפרדס). ראה שו\"ע אדה\"ז או\"ח ספ\"ה, ס\"ג. לקו\"ש כרך כא ע' 195 הערה 60."],["2297","21","<b>ואני ה' לא שניתי</b>: מלאכי ג, ו."],["2298","22","<b>ויאמר אלקים יהי אור יהי רקיע</b>: בראשית א, ג. ו."]]],[2100490418,"אתה<sup data-n=\"2299\">23</sup> הוא עד שלא נברא העולם ואתה הוא משנברא כו' בלי שנוי והתפעלות כלל כי אין ערך אליו כנודע.\n<b>והנה</b> אחר הדברים והאמת האלה כאשר יתבונן המשכיל בכל זאת יתעורר לבבו באה\"ר ושלהבת עזה בבחי' רצוא לכלות נפשו ממש אל מהותו ועצמותו ית' דווקא ולא לחפוץ בשום חפץ בעוה\"ז ובעוה\"ב בלתי לה' לבדו אשר אין לו תחילה ותכלה ואין לו שייכות אל סדרי השתלשלות כ\"א מרומם לבדו כי הוא ציווה ונבראו כו' וכדכתיב מי<sup data-n=\"2300\">24</sup> לי בשמים ועמך לא חפצתי בארץ פי' אפי' עמך מקור חיים ב\"ה הוא בחי' שמו ית' מדת מל' ית' המאיר על כל עלמין להחיותם כדכתיב כי<sup data-n=\"2301\">25</sup> עמך מקור חיים באורך נראה אור שנק' בחי' עמך לשון טפל ובטל אליך כביטול הזיו השמש בשמש כנודע, גם זה לא חפצתי בלתי לה' לבדו מהותו ועצמותו ית'.\n<b>והנה</b> מאחר שהאהבה והחפץ לדבר המוגבל ההווה ונפסד הי' גם האהבה בגבול ושיעור ויש לה קץ ותכלית משא\"כ בחי' האהבה והחפץ הוא לבחי' א\"ס ב\"ה שהוא בלתי גבול ממש ואין לה קץ כלל ולכך א\"א לשום כלי גבולית להכיל אותה ולקבלה לתוכה ממש ולכך נאמר באברהם ויסע כו' הלוך ונסוע כו' בתמידות בבחי' רו\"ש עלוי אחר עלוי מדריגה אחר מדריגה אשר אין קץ להעלות כלל לחפוץ ולהתקשר בשרשו הנגבה כנ\"ל.\n<b>וזהו</b> כוונת רז\"ל קיים אאע\"ה את כל התורה אפי' ע\"ת דהיינו אפי' ברוחניות למעלה הלוך ונסוע הנגבה אבל לא התורה גשמיות דעשי' ולכך לא הי' בחי' כלי קבלה שתוכל מדת האהבה לשרות בתוכה אך הלוך ונסוע כנ\"ל, משא\"כ ישראל בזמן קבלת התורה בחורב שהמשיכו בבחי' גלוי אוא\"ס למטה בעשי' גשמיות באמרם נעשה ונשמע שהקדימו נעשה לנשמע מפני שתחילה מצטרך להמשיך גלוי אא\"ס ב\"ה בבחי' עשי' בתורה ומצות גשמית שלמטה בעשי' דווקא ואח\"כ ונשמע וקיבל את התורה בבחי' הבנה והשגה שמיעה<sup data-n=\"2302\">26</sup> הוא לשון הבנה כנודע משא\"כ טרם שנמשך לבחי' עשי' אז בלתי אפשר להתקיים בבחי' ונשמע לקבל השפע העליונה הבלתי בע\"ג זולתי לאחר שנמשכה בעשי' אז יוכלו לקבל השפע בבחי' כלי ממש ברמ\"ח<sup data-n=\"2303\">27</sup> פיקודין דעשה ושס\"ה ל\"ת שזהו ונשמע, והטעם לזה הוא כמ\"ש בס\"י<sup data-n=\"2304\">28</sup> נעוץ סופן בתחילתן ותחילתן בסופן דווקא ולכך בעשי' דווקא סופא דכל דרגין נעוץ שם התחילה להיות נמשך גלוי אוא\"ס ב\"ה ושיוכל לקבלו השפע בבחי' כלי ממש בהתלבשותו ברמ\"ח מ\"ע שהם אברי דמלכא כמשל אברי האדם שהחיות שבמוח נמשך ונתפשט בתוכם ושורה בתוכם בבחי' הלבשה ממש ולכך הקדימו נעשה",[["2299","23","<b>אתה הוא עד שלא נברא העולם</b>: פרדר\"א פ\"ג. תפלת השחר."],["2300","24","<b>מי לי בשמים</b>: תהלים עג, כה. וראה מאמרי אדה\"א בראשית ע' תקע. שמות ח\"ב ע' שפ."],["2301","25","<b>כי עמך מקור חיים</b>: תהלים לו, י."],["2302","26","<b>שמיעה הוא לשון הבנה</b>: ואתחנן ו, ד. ראה זהר (אד\"ר) נשא קלח, ב."],["2303","27","<b>ברמ\"ח פיקודין דעשה</b>: ראה ת\"ז ת\"ל (עד, סע\"א)."],["2304","28","<b>בס\"י נעוץ סופן בתחלתן</b>: פ\"א, מ\"ז."]]],[2100490419,"לנשמע להמשיך תחילה בעשי' ואח\"כ ונשמע כנ\"ל וזמ\"ש וירד ה' על הר סיני בבחי' ירידה גדולה ועצומה בחי' התלבשות בעשי' ממש ברמ\"ח פיקודין דעשה ושס\"ה ל\"ת וכנראה בעליל שכאשר ישראל דווקא מקיימין המצוות להתעטף בטלית ותפילין וליתן צדקה ודומיהם ממשיכים גילוי אא\"ס למטה משא\"כ אוה\"ע<sup data-n=\"2305\">*28</sup> אף שיתעטף הגוי בטו\"ת לא ימשוך כלום וכן כשיתן צדקה אף שמשפיע לעני דלית ליה מגרמיה כלום שהוא בחי' חסד כתיב כי<sup data-n=\"2306\">29</sup> חסד לאומים חטאת והטעם מצד שישראל<sup data-n=\"2307\">30</sup> משולים לעפר שהן בבחי' ביטול ושפלות נמשל לעפר נדמה בביטולה להיות מדרס לכל רגלי הצועדים עליו שנעוץ תחילתן בסופן דווקא משא\"כ אוה\"ע שהמה גסי הרוח האומרים ידינו<sup data-n=\"2308\">31</sup> רמה וכו' ומגביהים א\"ע כנשר ועזות וחוצפה לכך לא ימשיכו כלום בקיום המצווה.\n<b>וביאור</b> הענין הנה כתיב בהפטורה דחג השבועות זמן מ\"ת כי<sup data-n=\"2309\">32</sup> תרכב על סוסיך ומרכבותיך ישועה פי' כמו עד\"מ הסוס הגשמי מוליך את רוכבו ממקום למקום מלמטה למעלה מבקעה להר ומלמעלה למטה מהר לבקעה כך עד\"מ למעלה בחי' ההמשכה של גילוי אוא\"ס ב\"ה מלמעלה למטה להתלבש בתומ\"צ מעשיות הוא ע\"י בחי' מרכבות הסוס אשר רכב עליו המלך כדכתיב יביאו<sup data-n=\"2310\">33</sup> לבוש וסוס אשר רכב עליו המלך פי' התורה נק' בחי' לבוש מל' כי<sup data-n=\"2311\">34</sup> אורייתא מחכמה נפקת שהי' מעטה לבושו נק' בשם חכים<sup data-n=\"2312\">35</sup> ולא בחכמה ידיעה כי מהותו ועצמותו מרומם לבדו כו' עד שהחכמה<sup data-n=\"2313\">36</sup> כעשי' גשמית נחשבת קמי' כמ\"ש כולם<sup data-n=\"2314\">37</sup> בחכמה עשית והוא מתלבש במדת מל' ית' להיות מלכותו<sup data-n=\"2315\">38</sup> מכ\"ע ומעולם ועד עולם עיקר השראתו דווקא בבחי' התורה דווקא כנודע, וזהו יביאו לבוש מל' וסוס אשר רכב עליו המלך דהיינו שהסוס ממשיך בחי' הרוכב המלך ב\"ה שיתלבש למטה בעשי' גשמית בתומ\"צ מעשיות שלמטה כי סוס<sup data-n=\"2316\">39</sup> הוא גימטרי' ב\"פ ס\"ג שלמעלה אותיות התורה<sup data-n=\"2317\">40</sup> שנק' סוס שהמה גורם בחי' התלבשות בלבוש מל' בתומ\"צ שלמטה, ואשר ניתן כ' מלכות בראשו שזהו נק' בחי' כ' מלכות כידוע.",[["2305","*28","<b>אוה\"ע. . לא ימשוך כלום</b>: ראה גם סה\"מ תקע\"א ע' לה. מאמרי אדה\"א שמות ח\"א ע' ו. וש\"נ."],["2306","29","<b>כי חסד לאומים חטאת</b>: משלי יד, לד."],["2307","30","<b>שישראל משולים לעפר</b>: ראה ג\"כ שערי אורה צא, א. אוה\"ת בלק ע' תתקכא. סה\"מ תרכ\"ז ע' רז. ובכ\"מ."],["2308","31","<b>ידינו רמה</b>: האזינו לב, כז."],["2309","32","<b>כי תרכב על סוסיך</b>: חבקוק ג, ח."],["2310","33","<b>יביאו לבוש וסוס אשר רכב עליו המלך</b>: אסתר ו, ח."],["2311","34","<b>אורייתא מחכמה נפקת</b>: זהר בשלח סב, א. יתרו פה, א (רע\"מ). משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["2312","35","<b>חכים ולא בחכמה ידיעה</b>: ראה תקו\"ז בהקדמה (יז, א)."],["2313","36","<b>שהחכמה כעשי' גשמית</b>: ראה תו\"א מקץ לד, ד. לקו\"ת בחוקותי מו, ג. ובכ\"מ."],["2314","37","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["2315","38","<b>מלכותו מכ\"ע</b>: תהלים קמה, יג."],["2316","39","<b>סוס הוא גימטרי' ב\"פ ס\"ג</b>: ראה מאמרי אדה\"א קונטרסים ע' שצ. תו\"ח בשלח רכו, א. וש\"נ."],["2317","40","<b>אותיות התורה שנק' סוס</b>: ראה ג\"כ תו\"א (כאן) צא, ב."]]],[2100490420,"<b>אך</b> הנה כתיב כי תרכב על סוסיך לשון רבים ומיעוט<sup data-n=\"2318\">41</sup> רבים שנים ב' סוסים במשמע דהיינו כמו שהסוס הגשמי יש בו ב' בחי' הא' שינשא הרוכב מלמטה למעלה והשנית ההיפוך להשפילו ממקום גבוה למקום נמוך כך עד\"מ למעלה כתיב אשירה<sup data-n=\"2319\">42</sup> לה' כי גאה גאה סוס ורוכבו רמה בים פי' שבחי' הסוס הא' הוא מלמטה למעלה בחי' ההתנשאות דכנ\"י באתעדל\"ת באהבה רבה וההתנשאות מלמטה למעלה אליו ית' שעי\"ז מעורר למעלה ג\"כ מדות ההתנשאות להיות מתנשא מימות עולם שכ\"ז היא בחי' ומדריגות הסוס הא' כי סוס<sup data-n=\"2320\">43</sup> בגימטרי' ב\"פ ס\"ג שהוא ב\"פ גס שהוא בחי' הגסות וההתנשאות שלמטה באתעדל\"ת שעי\"ז גורמים סיבת ההתנשאות למעלה להיות מתנשא מימות עולם וזהו כי גאה גאה שני פעמים שני גיאות כנגד ב\"פ ג\"ס שבסוס ורוכבו שרמה לשון רוממות וההתנשאות שלמטה כנ\"ל, והסוס הב' הוא הסוס אשר רכב עליו המלך שהוא ההיפוך מן הראשון ממש דהיינו שממשיך בבחי' גאה גאה למטה מטה לישראל שמשולין לעפר דווקא בתורה ובמצות דעשי' דווקא כי<sup data-n=\"2321\">44</sup> רם ה' ושפל יראה דווקא משא\"כ אוה\"ע שמתנשאים בבחי' גסות הרוח להגביה א\"ע כנשר הוא משפילם ומרחיקם משפיל גאים ומגביה שפלים ולכן אינן יכולין להמשיך כלום ע\"י קיום המצוות כי חסד לאומים חטאת כו' כנ\"ל, וזהו כי תרכב על סוסיך ב' סוסים כנ\"ל אז מרכבותיך ישועה שעי\"ז נמשכה התורה למטה גם בתומ\"צ מעשיות גשמית וזהו ענין קבלת התורה כנ\"ל.\n<b>וז\"ש</b> ונתון הלבוש והסוס ע\"י איש א'<sup data-n=\"2322\">45</sup> משרי הפרתמים והלבישו כו' וקראו לפניו ככה כו' אשר המלך חפץ ביקרו, הנה איש א'<sup data-n=\"2323\">46</sup> משרי הפרתמים הוא מלאך<sup data-n=\"2324\">47</sup> מיכאל שר הגדול כהנא רבא אפטרופס' דישראל שמלביש נשמות הצדיקים בלבוש מל' הנ\"ל וקרא' לפניו ככה יעשה וגו' זהו כמארז\"ל עתידים צדיקים<sup data-n=\"2325\">48</sup> שיאמר להם קדוש שנאמר כל<sup data-n=\"2326\">49</sup> הנשאר בציון כו' קדוש יאמר לו כו' פי' קדוש בלא וא\"ו הוא בחי' סובב כ\"ע דלית מח' תפיסא כלל שהוא מובדל ומתנשא מימות עולם, קדוש<sup data-n=\"2327\">50</sup> בוא\"ו מורה על המשכה שנמשך מקדש עליון כנ\"ל הסוכ\"ע למטה וזהו עתידין צדיקים שיאמר לפניהם קדוש היינו בחי' המשכה קודש עליון עליהן להלבישן בבחי' קדוש עליון וזה תעשה ע\"י המלאכים שהם יאמרו לפניהם קדוש עליון היינו שילביש אותו בלבוש בחי' קדוש שנעשה להם ללבוש ומקיף מלבושי התורה ומצוות שנתקיימו",[["2318","41","<b>מיעוט רבים שנים</b>: שו\"ת הר\"א בן הרמב\"ם סי' פו. סי' קי בשם אביו. ובלשון מחז\"ל גירסת שדה יהושע בירושלמי סוף ברכות."],["2319","42","<b>אשירה לה'. . גאה גאה. . שני גיאות</b>: בשלח טו, א. וראה תו\"א שם."],["2320","43","<b>סוס. . בחי' הגסות</b>: ראה גם שעה\"י קמא, ב ובהערה 23."],["2321","44","<b>כי רם ה'</b>: תהלים קלח, ו."],["2322","45","<b>איש. . משרי הפרתמים</b>: אסתר ו, ט."],["2323","46","<b>א'. . הוא מלאך מיכאל</b>: ראה ג\"כ תו\"א (כאן) צו, ד."],["2324","47","<b>מלאך מיכאל. . כהנא רבא</b>: ראה זהר (ס\"ת) לך פ, סע\"א ואילך. הנסמן במאמרי אדה\"א בראשית ע' נו."],["2325","48","<b>עתידים צדיקים שיאמר להם קדוש</b>: ראה ב\"ב עה, ב."],["2326","49","<b>כל הנשאר בציון</b>: ראה ישעי' ד, ג."],["2327","50","<b>קדוש בוא\"ו מורה על המשכה</b>: ראה תו\"א (כאן) צז, רע\"ד. קכו, א. לקו\"ת נצבים נו, ב. מאמרי אדה\"א הנחות תקע\"ז ע' רסג. וש\"נ."]]],[2100490421,"למטה שזהו בחי' לבוש מל' שיתלבשו בהם והמלאכים יקראו לפניהם ככה יעשה לאיש אשר המלך חפץ ביקרו יקרו הוא הלבוש הנעשה להם בבחי' קדוש שהקריאה הוא האמירה שלהם קדוש וזהו וקראו לפניו ככה כו' כנ\"ל וד\"ל.\n<b>וזהו</b> וקיבל היהודים את אשר החלו לעשות דהנה בשעת מ\"ת רק החלו לעשות שאמרו נעשה לשון עתיד אבל לא עשו עדיין רק בתחי' המעשה הוא ההבטחה על העשי' שיהי' לעתיד בימי אחשורוש שאז קבלו היהודים את אשר החלו לעשות והיינו כמשנ\"ת אאע\"ה הלוך ונסוע הנגבה בלתי יכול להתלבש בכלי כלל זולת בכלים של המצוות מעשיות תוכל השפע עליונה דווקא להתלבש ולכך אמרו נעשה אך הגמר<sup data-n=\"2328\">51</sup> של המעשה הי' בחג הפורים שאז קיבלו היהודים את אשר החלו כנ\"ל לתוכם ממש להיות נקלט השפע עליונה לתוך הכלים שלהם ממש מה שלא הי' כן מלפנים מקדם אשר לא נעשה ומה שלא יהי' כן אפי' לע\"ל בהגלות נגלות<sup data-n=\"2329\">52</sup> כבוד ה' לעיני כל בשר אשר עין<sup data-n=\"2330\">53</sup> בעין יראו כדכתיב בבכי<sup data-n=\"2331\">54</sup> יבואו ובתחנונים אובילם פי' כמו עד\"מ הבכי' הגשמית שהיא באה ונסתעפה מסיבת דבר שלמעלה מערך הכלי שלו שאינה יכולה לסבול שעי\"ז יורד הדמעות<sup data-n=\"2332\">55</sup> מכווץ ליחות המוח לדחות לחוץ מהעדר הגבלה לתוכו כגון שנתבשר בשמחה פתאומית אשר אין כלי המוח יכילנו שזולגים עיניו דמעות (כמו ר\"ע<sup data-n=\"2333\">56</sup> ששמע שיר השירים מפי ר\"א רבו זלגו עיניו דמעות כדאיתא במדרש וכמ\"ש במ\"א) וכן להיפוך מאיזה צער גדול אשר לא יוכל המוח להכילנו ולקבלו לתוכו שעי\"ז יתכווצו ליחות המוח ונדחים לחוץ דרך העינים כך לע\"ל בהיגלות נגלית כבוד ה' ית' אשר עין בעין יראו ולא יוכלו לקבל השפע לתוך הכלים שלהם ולכך בבכי יבואו מצד רוב אור וקטנות הכלים שלהם שלא יוכלו לסובלו ולקבלו לתוכו כנ\"ל, אכן בנס דפורים זכו היהודים לקבל השפע עליונה לתוך כליהם ממש שזהו הדבר נפלא הפלא ופלא מה שלא קם כמוהו ואחריו לא יהי' כן, שאף לע\"ל בבכי יבואו כנ\"ל.\n<b>והסיבה</b> לזה הוא מצד שמסרו<sup data-n=\"2334\">57</sup> נפשם על קדה\"ש בימי הפו\"ר כי הגזירה הי' שם רק על היהודים, אבל אם היו ממירים דתם ח\"ו לא היו עושים להם מאומה והם עמדו בפרץ בנסיונם למסור נפשם על קה\"ש לעמוד בדת היהודים אף ליהרג בפ\"מ ולא עלתה שום מח' זרה בכ\"א מהן בהמשך הזמן רב שהפיל<sup data-n=\"2335\">58</sup> פור מחודש לחודש עד חודש שנים עשר הוא חודש אדר כו' בלתי למסור נפשם על קדושת שמו ית' שעי\"ז זכו לבחי' שם זה להיותם נקראים בשם יהודים<sup data-n=\"2336\">59</sup> שהוא",[["2328","51","<b>הגמר. . הפורים</b>: ראה תו\"א מג\"א (כאן) צו, ג. ובאריכות ד\"ה וקבל היהודים פורים קטן תרפ\"ז."],["2329","52","<b>נגלות כבוד ה'</b>: ישעי' מ, ה."],["2330","53","<b>עין בעין יראו</b>: ישעי' נב, ח."],["2331","54","<b>בבכי יבואו</b>: ירמי' לא, ח."],["2332","55","<b>הדמעות מכווץ ליחות המוחין</b>: ראה מאמרי אדה\"ז הקצרים ע' תמח."],["2333","56","<b>ר\"ע. . זלגו עיניו דמעות</b>: מדרש הנעלם צח, ב. ז\"ח בראשית לג, א."],["2334","57","<b>שמסרו נפשם על קדה\"ש</b>: ראה ג\"כ תו\"א הוספות מג\"א קיח, ד. קכ, ד."],["2335","58","<b>שהפיל פור</b>: אסתר ג, ז."],["2336","59","<b>יהודים שהוא מלשון הודאה</b>: ראה תו\"א מד, א. צט, א. קכא, ד. ובכ\"מ."]]],[2100490422,"מלשון הודאה, שיהודי הוא לשון הודאה שמודה לה' ית', שבחי' הודאה הוא בחי' מדריגה גבוה מאוד נעלה שמגיע לבחי' סתימו דכ\"ס מה שא\"א להתגלות כלל ולכך ע\"י המס\"נ שלהם בפ\"מ זכו ליקרא בשם יהודים ולכן בחנוכה ופורים הם בהלל ובהודאה כו', ולז\"א קבלו היהודים אשר החלו לעשות בזמן מ\"ת שאז הי' רק ההתחלה בלבד אבל הגמר של המעשה לקבל השפע הי' בפורים דווקא שזכו לזה ע\"י מס\"נ בפ\"מ להיותם נקראים בשם יהודים כנ\"ל.\n<b>אך</b> מ\"ש וקבל היהודים וקבל לשון יחיד הענין הוא שלצורך קבלת השפע עליונה מצטרכים להיות כנ\"י בצוותא חדא בתכלית אמיתי בתכלית היחוד בלי פירוד לבבות כלל ח\"ו והיינו כמ\"ש במ\"ת ויחן שם<sup data-n=\"2337\">60</sup> ישראל כו' מפני שכולם כוונו לשמים ברעו' דליבא לומר נעשה ונשמע שנעשו כלב<sup data-n=\"2338\">61</sup> א' מיוחד לאביהם שבשמים, כמו\"כ בשעת גמר המעשה בשעת הקבלה לתוכה ממש לשון יחיד שאז מסרו כולם כא' נפשם לה' א' ברעותא דליבא שהוא פשוט בתכלית הפשיטות שלמעלה מגדר ההתחלקות משא\"כ המחשבה מצורפת מאותיות רבים מחולקים וזהו מצוות<sup data-n=\"2339\">62</sup> צריכות כוונה כוונת הלב רעותא שלמעלה מבחי' אותיות שמתפשטת מגדר ההתחלקות ולכך נאמר וקיבל לשון יחיד כנ\"ל וד\"ל.",[["2337","60","<b>ויחן שם ישראל</b>: יתרו יט, ב."],["2338","61","<b>כלב א'</b>: פרש\"י עה\"פ. וראה מכילתא שם."],["2339","62","<b>מצוות צריכות כוונה</b>: ראה עירובין צה, סע\"ב."]]],[2100490423,"<h3>ויאמר המן בליבו למי יחפוץ המלך</h3>\n<b></b><b>בעזרת ה' בסעודה<sup data-n=\"2340\">1</sup> הנ\"ל</b>\nבסעודה הנ\"ל\n<b>ויאמר</b><sup data-n=\"2341\">2</sup> המן בליבו למי יחפוץ המלך וגו' הנה אמרז\"ל בת\"ח<sup data-n=\"2342\">3</sup> שצריך להיות בו גסות הרוח משמיני שבשמינית ומעטר' ליה כסאסאה דשבלת', וצ\"ל ענין זה היטב מהו השבח דגסות הרוח של ת\"ח וזהו חלק שמיני שבשמינית ומה מהדמיון זה לסאסאה דשבלתי'. אך הענין הוא דהנה ת\"ח שנזכר בגמ' בכל התלמוד הכוונה על היותו כלי הטפל ובטל לחכ\"ע שורש התורה דאורייתא מחכמה נפק' ולכך מי שהוא כלי להשראות החכמה עליונה טפל ובטל אלי' נק' בשם ת\"ח שהוא התלמיד",[["2340","1","<b>בסעודה הנ\"ל</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 735 (קכו, א). הנחת כ\"ק אדה\"א נדפס בתו\"א בהוספות מג\"א קיט, ג בד\"ה ”ויקח המן את הלבוש ואת הסוס\" מגוכתי\"ק 1025 (יב, ב). וד\"ה זה נזכר באוה\"ת מג\"א ע' דש. המאמר עם הגהות וקיצורים באוה\"ת מג\"א ע' נא. סח. עג."],["2341","2","<b>ויאמר המן בלבו למי יחפוץ המלך</b>: אסתר ו, ו."],["2342","3","<b>בת\"ח. . משמיני שבשמינית</b>: ראה סוטה ה, א. מאמרי אדה\"א ויקרא ח\"ב ע' תעז. וש\"נ. קונטרסים ס\"ע שפח. וש\"נ. לקו\"ש בהר בחוקותי (כרך כב) ע' 162 הערה 32. שיחת שמחת בית השואבה תרצ\"ג מכ\"ק אדמו\"ר נשיא דורנו (נדפסה ברשימות חוברת טו ע' 6 ואילך). יום ב' דחה\"ש תשי\"א נדפסה בתורת מנחם התוועדויות ח\"ג ע' 151. וראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ הנחות הר\"פ ע' קצב."]]],[2100490424,"להכלי הבטל לבחי' חכים ולא בחכמה ידיע' כמאמר<sup data-n=\"2343\">4</sup> אליהו אנת חכים ולא בחכמה ידיעא כו'.\n<b>והנה</b> כתיב באור<sup data-n=\"2344\">5</sup> פניך כי רציתם פי' פניך נק' בחי' ח\"ע חכים ולא בחכמה ידיעא שהוא הפנים העליון שורש התורה והמצות שלמטה מבחי' באור פניך הוא בחי' ההארה העליונה הנשפע למעלה מהחכמה והרצון ממקור הרצון בבחי' פנים העליון וזהו באור פניך שהוא האור העליון ממקור הרצון הנשפע בפניך, כי רציתם שמזה נמשכים התורה ומצוות שלמטה להיות מתלבש אור פניו ית' בבחי' חכמתו ורצונו ית' לבד שהם התומ\"צ שלמטה כדכתיב יאר<sup data-n=\"2345\">6</sup> ה' פניו אליך דווקא אל ישראל מקיימי התורה והמצוות שעליהם דווקא מאיר אור פניו מקור הרצון עליון אבל לא לעוברי רצונו ח\"ו, ולזאת ת\"ח שהוא כלי הבטל והטפל לחכ\"ע הנק' פנים העליון בכדי לקבל אור פניו ית' מקור הרצון והחכמה עליונה מצטרך לשמור ולעשות את כל דברי התורה הזאת והן מבחי' סו\"מ להשמר מכל השס\"ה ל\"ת דאורייתא ודרבנן ואפילו דקדוק של ד\"ס בתכלית הזהירות והפרישות שלא יהי' עוונותיו ח\"ו מבדילים ומונעים עליו מלקבל אור פניו ית' שאינו מאיר זולתו לעושי רצונו ית' כמ\"ש יאר ה' פניו כו' באור פניך כי רציתם והם במעשה טוב לקיים כל רמ\"ח<sup data-n=\"2346\">7</sup> פיקודין דעשה שנמשך מרצונו ית' שמתלבש אור פניו ית' שנק' אברין דמלכא כאברי האדם שחיות הנפש שבמוח מתפשט בהם בבחי' הלבשה ממש, ולכך צ\"ל מקיים התורה והמצוות ולשמור אותם בתכלית השמירה המעולה והזהירות והפרישות שלא לעבור אפי' על דקדוק קל שבד\"ס.\n<b>והנה</b> אופן הזהירות שלו מאיסור קל של ד\"ס ולכבוש היצר מכל תאוות של העוה\"ז הוא מצד שאינו רוצה ליפרד מיחודו ית' כ\"א לדבקה בו ית' ומצד זה מונע א\"ע מכל חפצי העוה\"ז ומכל דבר הגורם פירוד בין הדבקים ח\"ו ומתקשר עצמו בקשר אמיץ וחזק ביחודו ואחדותו ית' בלתי להיות נפרד ממנו אפי' שעה אחת ח\"ו והנה באמת ידוע למביני מדע שזהו מדריגה נמוכה ואין זה עדיין בתכלית שלימות הביטול האמיתי כ\"א הוא בחי' יש ודבר מה בפ\"ע ויש לו רצון בפ\"ע רק שהוא הנפרד ליש ודבר בפ\"ע אינו רוצה להיפרד מיחודו ית' משמע שיש איזה סברא להעלות על ה[דעת] להיפרד ח\"ו רק שהוא אינו חפץ בזה, וגם הלשון אינו חפץ כנ\"ל משמעו שהוא מהות דבר בפ\"ע שבוחר בטוב ואומר אני אני הוא אשר איני חפץ לבחור ח\"ו שלא ליפרד ממנו ית' וה\"ז כמשל מי שתובע ממון מהנתבע והנתבע משיב לו פרעתי שהם ב' בני אדם זה תובע ממנו וזה הנתבע משיב לו, כך זה ממש כי מי שואל ותובע ממנו מה אשר אומר איני חפץ בזה ואני בוחר באלה אלא זהו מצד היותו באמת יש ודבר בפ\"ע רק הוא חפץ בקרבת אלקים ולא להפרד ממנו ח\"ו, אבל באמת תכלית הביטול האמיתי בו ית' הוא כשאינו נחשב למהות דבר",[["2343","4","<b>כמאמר אליהו חכים ולא בחכמה ידיעא</b>: ת\"ז בהקדמה (יז, ב). ראה ז\"ח יתרו לד, ד."],["2344","5","<b>באור פניך כי רציתם</b>: תהלים מד, ד."],["2345","6","<b>יאר ה' פניו אליך</b>: נשא ו, כה."],["2346","7","<b>רמ\"ח פיקודין. . אברין דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א)."]]],[2100490425,"בפ\"ע כלל כ\"א מושקע בבחי' היחוד והביטול האמיתי עד שאינו עולה בשם דבר בפ\"ע ולומר אני איני חפץ ברע ח\"ו איך יעלה על הדעת כלל, ועוד מי הוא שאומר ואיזהו שאומר זאת מאחר שבטל בתכלית הביטול ומיוחד עמו בתכלית היחוד והיו לאחדים עמו ית' ממש בלי תפיסת מקום ולהיות מתפיס למהות דבר מה בפ\"ע הטפל ובטל אליו, וז\"ש באברהם ע\"ה שאמר ואנכי<sup data-n=\"2347\">8</sup> עפר ואפר בתכלית הביטול אליו ית' בלי תפיסת מקום בפ\"ע כלל כעפר הארץ שהי' מדרס לרגלי האנשים שעליה ובמה נחשב הוא, אתה הוא<sup data-n=\"2348\">9</sup> כו' אשר בחרת באברם והוצאתו כו' ומצאת את לבבו<sup data-n=\"2349\">10</sup> נאמן לפניך לבבו חדשה במשמע דאתהפכא חשוכא לנהורא ונתאחדו ב' לבבות להיות לב א' אליו ית' וכרות עמו הברית וכו', את ארץ הכנעני כו' כל הז'<sup data-n=\"2350\">11</sup> עממין שהם ז' מדות הרעות לתת לזרעו פי' שלא די שאינו מצטרך ללחום עמהם ולכבוש אותם ולהכניעם אלא אדרבה הם ניתנו לזרעו ממש להיות נכנעים אליהם ולהיותם מתהפכים מחשוכא לנהורא לקדושה ממש, ועכ\"ז זכה אאע\"ה ע\"י תכלית הביטול באמת עד שאמר ואנוכי עפר ואפר ממש בלי תפיסת מקום כלל, וזהו אשר הוצאתו מאור כשדים ושמת שמו אברהם דווקא ומצאת את לבבו נאמן לפניך אז דווקא וכרות עמו הברית כו'.\n<b>אך</b> באמת לא כל אדם זוכה למדריגות אברהם להיות עפר ואפר ולכך עולם כמנהגו נוהג להיות העבודה באופן זו עכ\"פ שלא לחפוץ להיות נפרד מיחודו ית' שעי\"ז יהי' שומר נפשו מכל איסור קל של ד\"ס בתכלית הזהירות ויקיים כל רמ\"ח פיקודין דעשה בכדי לדבקה בו וקרבת<sup data-n=\"2351\">12</sup> אלקים לי טוב, ואף שזה אינו עדיין תכלית השלימות של הביטול כ\"א הוא בחי' יש, עכ\"פ מזה יסתעף הפעולה לשמור מ\"ע ולהזהר מכל האזהרות שבתורה דאורייתא ודרבנן.\n<b>ולזאת</b> אמרז\"ל בת\"ח שצריך להיות בו גסות הרוח שמיני שבשמינית ומעטרה לי' כסאסאה דבשיבלת', פי' שהגסות הרוח חלק שמיני שבשמינית היא מדריגה זו שאינו חפץ להיות נפרד שזהו עדיין בחי' גסות ויש כנ\"ל וזהו בחי' ומדריגות הסוס הא' כנ\"ל כי סוס הוא ב\"פ ג\"ס (וזהו חלק ס\"ד צריך להיות בו וד\"ל) שגס הא' הוא של ת\"ח שמעטרא לי' כסאסאה דשבלת' כו' כמו עד\"מ העטרה להשיבולת שהוא הקליפה שסביב לשיבולת מבחוץ שהוא קליפה גסה השומר לפרי הגרעין שבשיבולת להיות למחסה ולמסתור עלי' מזרם וממטר ומקור וחום שלא ירקבו הגרעינין ויתקלקלו משטף הגשם או מתוקף הקור או שלא יקדיר אור השמש עליהם ויכלו בשריפתה ודומיהן, ולאחר גמר בישולן שנקצרו בזמן הקציר אזי זורה ודש מהם המוץ והתבן להפריד הפסולת מן המאכל אזי גם הסאסאה בכלל הפסולת",[["2347","8","<b>ואנכי עפר ואפר</b>: וירא יח, כז."],["2348","9","<b>אתה הוא כו' אשר בחרת באברם</b>: נחמי' ט, ז."],["2349","10","<b>לבבו. . לבבו חדשה</b>: נחמי' ט, ח. וראה תו\"א מג\"א קיט, ד."],["2350","11","<b>ז' עממין. . מדות הרעות</b>: ראה ג\"כ מאמרי אדה\"ז תקס\"ג ח\"א ע' קצח. תקס\"ה ח\"ב ע' תתב. לקו\"ת מטות פה, סע\"ד. מסעי צד, א. מאמרי אדה\"א במדבר ח\"ה ע' א'תשלט. וש\"נ."],["2351","12","<b>וקרבת אלקים לי טוב</b>: תהלים עג, כח."]]],[2100490426,"והמוץ והתבן שמפרידין אותו לחוץ מן האוכל, וכמחז\"ל במעשר שאינו<sup data-n=\"2352\">13</sup> חייב להפריש עד שיתמרח בכרי שכבר נתמרח ונפרד הפסולת והמוץ ממנו אבל קודם לכן אינו חייב במעשר ויכול לאכול אכילת עראי כו' והטעם בזה מפני שבמעשר נאמר קודש להיות המוץ והתבן הם הפסולת האוכל<sup data-n=\"2353\">14</sup> והם מבחי' הקליפות לכך אסורים לבוא בקהל ה' בבחי' קודש העליון, נמצא העולה מזה שהסאסאה בשיבלתי' אף שהוא בחי' קליפה ממש השומר לפרי שאחר גמר בישולן יומרח בכדי להפרידן מן האוכל ולחוץ אעפ\"כ קודם גמר בישולן בעודינו באיבו הוא עיקר השומר לפרי משרב וממטר ומצטרך עלי' מאוד להיות למחסה ולמסתור על הפרי שבלעדה לא הי' קיום להשיבולת כלל, כך בחי' גסות הרוח חלק שבשמינית שבת\"ח מעטר' ליה כסאסאה דשיבולת' פי' כנ\"ל שאף שזהו בחי' גסות ויש ואין זה תכלית שלימות הביטול אעפ\"כ זהו עיקר השומר אותו מכל חטא ועוון כלל של ד\"ס, מצד בחי' היש והגסות זו יהי' איך שיהי' עכ\"פ אינו רוצה להיפרד ממנו ח\"ו כ\"א לדבקה בו ית' וזה גורם לו סיבת הריחוק מכל העבירות שבתורה דאורייתא ודרבנן וסיבת הקיום כל מ\"ע דאורייתא ודרבנן שבלעדי זאת לא הי' לו קיום כלל ולכך מעטר לי' הגסות הזה כסאסאה המעטר לשיבלת' כנ\"ל.\n<b>והנה</b> זהו בחי' ומדריגות הסוס הא' שעולה ג' ב\"פ ג\"ס דהיינו שבחי' ג\"ס הא' הוא של ת\"ח המעטר לי' כסאסאה דשיבלת' שע\"י אתעדל\"ת בבחי' ומדריגה זו יעורר למעלה ג\"כ במדריגה זו ובדוגמא זו ממש דהיינו שיהי' הקב\"ה מתנשא מימות עולם בבחי' גיאות והתנשאות למעלה מעלה שלא תרד השפע עליונה אף להחיצונים כ\"א יהי' כמ\"ש רמה<sup data-n=\"2354\">15</sup> ידך בל יחזיון כו' שזהו היתרון והפעולה מבחי' ומדריגה זו בבחי' הג\"ס של ת\"ח מבחי' הביטול האמיתי מבחי' עפר ואפר דאברהם, דהיינו שבאמת למטה בעבודה הגבה למעלה מאוד נעלה בחי' ומדריגות השפלות וביטול דאברהם שאמר ואנכי עפר ואפר כו' מבחי' ומדריגות זו של הג\"ס דת\"ח כו' אך בבחי' ההתעוררות שלמעלה דאתעדל\"ע הוא דוגמת אתעדל\"ת ממש יש מעלה יתירה בבחי' הג\"ס דת\"ח מבחי' השפלות דאברהם, דהיינו שאברהם מעורר לבחי' האתעדל\"ת שלו בשפלות האמיתי שלו דוגמ' ממש אתעדל\"ע שישפיל השפע דאוא\"ס ב\"ה מלמעלה למטה מטה בתכלית הירידה והשפלות כמ\"ש המשפילי<sup data-n=\"2355\">16</sup> לראות בשמים ובארץ כו', ולזאת יוכל להסתעף מזה שתגיע השפע אף להחיצונים מצד גודל עוצם הירידה והשפלות השפע דאוא\"ס ב\"ה דקמי' כחשיכ'<sup data-n=\"2356\">17</sup> כאורה שווים וכמ\"ש שממית<sup data-n=\"2357\">18</sup> בידים תתפש והיא בהיכלי מלך פי' אף השממית ששנואה למלך אעפ\"כ היא בהיכלי מלך ואינו תופס מקום כלל בעיני המלך לרגוז עליה ולהקפיד עלי' מצד עוצם גודל שפלו' שהוא שפל ברי' אשר איננה תופסת מקום כלל (משא\"כ",[["2352","13","<b>אינו חייב להפריש עד שיתמרח בכרי</b>: מנחות ע, א."],["2353","14","<b>האוכל</b>: תיבה זו אינה ברורה בהכת\"י."],["2354","15","<b>רמה ידך בל יחזיון</b>: ישעי' כו, יא."],["2355","16","<b>המשפילי לראות בשמים ובארץ</b>: תהלים קיג, ו."],["2356","17","<b>כחשיכה כאורה</b>: תהלים קלט, יב. וראה עטרת ראש לעשי\"ת ע' נא."],["2357","18","<b>שממית בידים תתפש</b>: משלי ל, כח."]]],[2100490427,"האדם בדומה לו השונא יגרשו בחימה עזה כו'), כך עד\"מ לגבי עצמות המאציל ב\"ה אף עוברי רצונו המה הגוים אוה\"ע נמשלו לשממית נדמו שאינם תופסים מקום כלל ולכך יוכל להתפשט השפע אף עליהם וכדכתיב המשפילי לראות בשמים ובארץ כו' וכמ\"ש במ\"א.\n<b>וז\"ש</b> רז\"ל ודלא<sup data-n=\"2358\">19</sup> כאברהם שיצא ממנו ישמעאל שמבחי' הביטול והשפלות דאברהם שאמר ואנכי עפר ואפר גרם סיבת התפשטות החכ\"ע במורד למטה מאוד יותר מדאי עד שהגיע אף לבחי' ישמעאל כמ\"ש בעצמו ישמעאל<sup data-n=\"2359\">20</sup> הוא בחי' לפניך כנ\"ל, אכן בזאת נאות בחי' ומדריגות הג\"ס דת\"ח אף שהוא במדריגה נמוכה בעצם אעפי\"כ בזה ימצא בו יתרון שמעוררת למעלה ג\"כ דוגמתה ממש להיות המאציל ב\"ה מתנשא מימות עולם בבחי' התנשאות והסתלקות למעלה מהם שלא תתפשט השפע רק לישראל בלבד ולא לאוה\"ע שעליהם נאמר רם<sup data-n=\"2360\">21</sup> על כל גוים ה', רמה ידך בל יחזיון כו', וזהו באור פניך כי רציתם אל ישראל מקיימי המצות שנמשכים מרצונו ית' בלבד יאר ה' פניו, ולא לאוה\"ע וזהו מ\"ש נטית<sup data-n=\"2361\">22</sup> ימינך תבלעימו ארץ כתרגומו ארימת ידך כנ\"ל תבלעימו לשון הבלעה וביטול של הארץ ע\"י התרוממות ידו ית' למעלה כנ\"ל וד\"ל.\n<b>וזהו</b> אשירה<sup data-n=\"2362\">23</sup> לה' כי גאה גאה ב' גיאות (גם ב' בחי' ג\"ס שהם ב' שמות ס\"ג הג\"ס הא' הוא בחי' אתעדל\"ת של ת\"ח דמעטרי' לי' כסאסאה שבלת' כנ\"ל והשנית הוא בחי' הג\"ס שלמעלה שנתעורר ע\"י בחי' אתעדל\"ת זאת להיותו מתנשא מימות עולם מבלי תת מקום להחיצונים לינק כי רם על כל גוים ה', רמה ידך כנ\"ל וד\"ל, וזהו סוס<sup data-n=\"2363\">24</sup> ורוכבו רמה בים רמה<sup data-n=\"2364\">25</sup> לשון רוממות והתנשאות וגם לשון הרמה והפלה למטה ושניהם אמת, זה לישראל וזה לאוה\"ע, לישראל התרוממות ולאומות מפלה וד\"ל.\n<b>והנה</b> כ\"ז הוא בחי' ומדריגות הסוס הא' אבל בחי' ומדריגות הסוס הב' הוא להיפוך ממש כמ\"ש יביאו<sup data-n=\"2365\">26</sup> לבוש מל' והסוס אשר רכב עליו המלך כו' שזהו בחי' אותיות<sup data-n=\"2366\">27</sup> התורה שנק' בשם סוסים שבהם מתלבשים האורות עליונים דמדת מלכותו ית' ולכן נק' בחי' סוס, כסוס הבטל להרוכב ונעשה בחי' כלי הבטל לרוכבו כך אותיות התורה והמצוות הם הכלים להשראות אוא\"ס ב\"ה. והנה כמה מיני",[["2358","19","<b>ודלא כאברהם שיצא ממנו ישמעאל</b>: ראה פסחים נו, א. וראה זהר בראשית מז, ב."],["2359","20","<b>ישמעאל. . לפניך</b>: ראה לך לך יז, יח."],["2360","21","<b>רם על כל גוים ה'</b>: תהלים קיג, ד."],["2361","22","<b>נטית ימינך</b>: בשלח טו, יב."],["2362","23","<b>אשירה לה' כי גאה גאה</b>: בשלח טו, א."],["2363","24","<b>סוס ורוכבו רמה בים</b>: בשלח טו, א."],["2364","25","<b>רמה לשון רוממות. . והפלה למטה</b>: ראה ג\"כ תו\"ח בשלח לז, ב. וש\"נ."],["2365","26","<b>יביאו לבוש מלכות</b>: אסתר ו, ח."],["2366","27","<b>אותיות התורה שנק' בשם סוסים</b>: ראה תו\"א (כאן) צא, ב. מאמרי אדה\"א שמות ח\"א ע' קכג. וש\"נ. תו\"ח ויצא קסב, ב והערה 33. בשלח רכח, ב ובהערה 69."]]],[2100490428,"מרכבות ימצא למעלה במלכו ש\"ע ב\"ה כענין מארז\"ל ג'<sup data-n=\"2367\">28</sup> שעות ראשונות יושב הקב\"ה כו' עד בלילה מאי קעביד כו' רוכב על כרוב קל שלו ושט בי\"ח אלף עולמות כמ\"ש רכב<sup data-n=\"2368\">29</sup> אלקים רבותיים אלפי שנאן שאינן כו' דלכאורה הוא פלאי ענין רכיבתו על כרוב דווקא ושט כו', אך באמת כנ\"ל כי עצמותו מרומם לבדו וא\"א להתגלותו למטה כ\"א ע\"י כלי הבטל לגבי' שע\"י השראתו בה יכול להתגלות למטה וזהו רוכב על כרוב קל שהוא כלי הבטל אליו להיות בחי' מרכבה אליו ע\"י ההעלאות מ\"ן שלמטה (וזהו כרוב קל בחי' המ\"ן שלמטה), וברכיבתו ובהשראתו על הכרוב קל הוא שט בח\"י אלף עלמין בבחי' גלוי בתוכם וכן נראה בעליל שיש בזה כמה מדריגות שונות באופן הכלים עליונים, כלים מכלים שונים שנתלבש בהן ושורה בהן אוא\"ס ב\"ה הכל לפי העת והזמן, שבזמן התנאים בעלי המשנה והאמוראים בעלי הגמרא הי' עיקר הגילוי של אוא\"ס ב\"ה בעסק התורה הנגלית לנו בתושבע\"פ אשר היו מבלים כל ימיהם בזה וחדשו הלכות רבות אין קץ, ובזמן הגאונים ופוסקים ראשונים הי' למטה במורד יותר לא בערך הזמן של התנאים והאמוראים, וכ\"ש וק\"ו בימי האחרונים ועתה בזמן הזה ועיקבתא דמשיחא עיקר העסק במצוות מעשיות בגמ\"ח ודומיהן (ומאיר אור ה' זורח הוא בעבודת<sup data-n=\"2369\">30</sup> ה' זו תפילה בהתבוננות בגדולת ה' מה שבזה נתעוררו הלבבות מאוד והכל לפי העת והזמן), והיינו כנודע שיש ד'<sup data-n=\"2370\">31</sup> עולמות אבי\"ע כנגד שם הוי' ב\"ה י' אצילות ה' בריאה ו' יצירה ה' עשי', וזה המרכבות שונות של מעלה מקרא משנה הלכות ואגדות וכ\"ז נק' דרך כלל הסוס אשר רכב עליו המלך להמשיך השפע מלמעלה למטה בתומ\"צ שלמטה וכנ\"ל וד\"ל.\n<b>וזהו</b> וקבל היהודים את אשר החלו לעשות שעיקר זמן קבלת התורה לתוך כליהם ממש הי' בפורים את אשר לא זכו לזה מקודם רק החלו לעשות בלבד וכן לע\"ל כתיב בבכי יבואו כנ\"ל, והסיבה לזה הוא מצד שאז זכו לשם יהודים שהוא בחי' הודאה שמגעת לבחי' סתימא דכל סתימין שא\"א להתגלות כלל שלמעלה מבחי' ברכה שהוא בחי' המשכה וגלוי מלמעלה למטה כמ\"ש ברוך<sup data-n=\"2371\">32</sup> ה' מן העולם ועד העולם כנ\"ל והיינו מצד מה שמסרו נפשם על קדוהי\"ת בפ\"מ כי הגזירה הנחרצה הי' רק על דת יהודים לכל איש אשר בשם ישראל יכונה להשמידו כו' ולא עלתה שום מחשבה זרה ח\"ו בכ\"א מהם להמיר דת ח\"ו וליצא מן הכלל כו'.\n<b>והנה</b> זאת ידוע שבחי' הכוח למסור נפשו בפ\"מ על קדושת השם שנמצא בכל בר ישראל הוא למעלה מהדעת והשכל כי ע\"פ הדעת והשכל אינו מחייב זאת שימסור את נפשו ממש בפ\"מ מצד שהאהבה וכל ההשכלות והטעמים שנמצאו בספרי מוסר הבנויים ע\"פ שכל אנושי למצוא טעם לאהבה את הוי' לא ימצא טעם זר למס\"נ בפ\"מ כי זה למעלה מהשכל כי השכל אינו מחוייב רק לאהבה כנפשו בלבד",[["2367","28","<b>ג' שעות ראשונות יושב</b>: ראה ע\"ז ג, ב."],["2368","29","<b>רכב אלקים רבותיים</b>: תהלים סח, יח."],["2369","30","<b>בעבודת ה' זו תפלה</b>: ראה ספרי ופרש\"י עקב יא, יג. תענית ב, סע\"א."],["2370","31","<b>ד' עולמות אבי\"ע כנגד שם הוי'</b>: ראה ע\"ח (שער סדר אצי') ש\"ג, פ\"א. לקו\"ת להאריז\"ל בראשית עה\"פ (ג, כג) וישלחהו ה\"א."],["2371","32","<b>ברוך ה' מן העולם</b>: תהלים קו, מח."]]],[2100490429,"ולא יותר ע\"כ להפקיר א\"ע מצד אהבה (וכמ\"ש בספרי המוסר בר\"ח<sup data-n=\"2372\">33</sup> וס' היש' לר\"ת וחוב\"ה לההסבר באופן האהבה לה', שכל הטעמים לא יועילו נגד מס\"נ בפ\"מ כי מאחר שיש טעם להאהבה הרי כי בטל הטעם בטל האהבה כו'), ואין זאת כ\"א בחי' שלמעלה מהדעת והשכל שנקבע בתוך לב כאו\"א מישראל בהסתר והעלם בחי' האהבה המסותרת למסור נפשו על קדוה\"ש<sup data-n=\"2373\">34</sup> בלי טעם ודעת כלל, שאם נאמר טעם למס\"נ בכדי שיהי' לו עוה\"ב ה\"ז לקבל פרס שהוא מו\"מ גדול שמחליף כל תענוגי הגופניים דעוה\"ז בתענוג רוחנים של הג\"ע וסובל כל יסורי מיתה של הגוף בכדי לחיותם אח\"כ בחיי עולם בג\"ע ואין זה מס\"נ כ\"א אדרבה עושה להנאתו שעוזב הנאה מועטת בשביל שישיג אח\"כ הנאה רבה וה\"ז כהעוסק במו\"מ להרויח שסובל עינוי הדרך וכל יסורים קשים בכדי שיתעשר אח\"כ וירויח ממון הרבה כו', אבל עיקר אמיתית המס\"נ הוא שמוסר נפשו במסירה ממש לקונו ליהרג על קדוה\"ש בלי שום מח' ופנים כלל אף שלא ישיג גם התענוג של העוה\"ב כי אינו יודע לאיזה דרך מוליכין אותו ואינו מהרהר בזה רק בלי טעם וחשבון מוסר נפשו על ק\"ה ודבר זה הפלא ופלא מגדר שכל האנושי אשר לא השיגו בזה חכמי שכל האנושי כ\"א חכמי הקבלה האמיתית והיינו כמשנ\"ת לעיל (בתורה<sup data-n=\"2374\">35</sup> פ' תצוה) ע\"פ<sup data-n=\"2375\">36</sup> ופתחת עליו פתוחי חותם פי' פתוחי חותם נק' בחי' נקודת הלב שבכאו\"א מישראל בחי' רעוד\"ל שלמעלה מהדעת שנמשל לחותם דכמו עד\"מ החותם של האדם החקוק על השעוה או על הנפש ראובן בן יעקב עד כדומה שאין זה ערך מהותו ואיכותו של ראובן בן יעקב ממדותיו ושכלו ומזגו ואעפי\"כ יש בכלל החתימה הארה מכל מהות האדם שמקיים בזה כל הקיומים לעדות ולכ\"ד בעולם.\n<b>כך</b> עד\"מ הרעוד\"ל האהבה המסותרת בלב כנ\"י שלמעלה מהדעת למסור נפשו על ק\"ה בלי טעם כלל בחי' חותמו של הקב\"ה, שז\"ש כי כתב<sup data-n=\"2376\">37</sup> אשר נכתב בטבעת המלך ונחתם בטבעת המלך אין להשיב פי' עד\"מ הטבעת הגשמי שהיא עגולה ועלי' נחקק חותם המלך כך ממש למעלה בחי' רעותא דליבא אהבה המסותרת דכנ\"י למסור נפשו בלי טעם כלל נק' בשם טבעת המלך שהוא בחי' מקיף וסובב למעלה מהשכל והדעת ובמקיף זה הוא חותמו של המלך הקב\"ה כי אין זה ערך למהותו ועצמותו ית' שנק' עליהם הוא חותמו ממש שנחקק מהם שעי\"ז נמצ' בהם בחי' האהבה של מס\"נ בלי טעם, וגם נראה בעליל שטבע איש יהודי אף שנהנה מכל עניני עוה\"ז אכילה ושתי' ודומיהן שאין לו שלימות נחת רוח מזה כ\"א כל עיקר מגמתו וטבעו לדבקה בו ית' משא\"כ אוה\"ע שמקבלים תכלית שלימות נח\"ר מעניני העוה\"ז, שזהו מצד חותמו של הקב\"ה החקוק על לוח לבם, דכמו בחותם הגשמי החקוק על השעוה אין בו טעם",[["2372","33","<b>בר\"ח וס' היש' לר\"ת וחוב\"ה</b>: בראשית חכמה וספר הישר [ספר מוסר המיוחס] לר\"ת וחובת הלבבות."],["2373","34","<b>קדוה\"ש בלי טעם ודעת כלל</b>: ראה גם מאמרי אדה\"ז תק\"ע ע' לה וע' מא."],["2374","35","<b>(בתורה פ' תצוה)</b>: נדפס בתו\"ח תצוה [הוצאת קה\"ת — תשס\"ג] שנו, א ואילך. וראה תו\"א תצוה פג, א."],["2375","36","<b>ופתחת עליו פתוחי חותם</b>: תצוה כח, לו."],["2376","37","<b>כי כתב. . ונחתם בטבעת המלך</b>: ראה אסתר ח, ח."]]],[2100490430,"וריח מכוחות האדם והשכל והמדות ואע\"פ כן כל מהותו כולה נכלל בו כך עד\"מ בטבעת המלך ב\"ה החקוק על לוח לבבם של כנ\"י שאין להם טעם והרגשה באלקות שלא טעמו מעולם איך ומה הוא (אם מתוק או חמוץ עד\"מ) ואעפי\"כ נמשך כמים לבם לילך אחרי ה' וחוקותיו שלא להפרד ממנו ח\"ו ולא נפנה בטבע לבבם אל כל התועבות האל דעוה\"ז לקבל שלימות התענוג ונ\"ר שזהו מצד טבעת המלך שהוא בחי' מקיף עליהם שלמעלה מהדעת והטעם והשכל שאין בו הרגשה וטעם כלל ובו חקוק חותמו של המלך ב\"ה דכאשר נחתם בטבעת המלך אין להשיב כו' וכנ\"ל וד\"ל.\n<b>והנה</b> את<sup data-n=\"2377\">38</sup> זה לעומת זה עשה האלקים דכמו בקדושה ימצא בחי' מקיף למעלה מהשכל והדעת שזהו בחי' האהבה המסותרת בתוך כנ\"י למסור נפשם בפו\"מ בלי טעם ודעת כלל כך לע\"ז בקליפה הוא בחי' המן שמתנשא בעזות וחוצפה<sup data-n=\"2378\">39</sup> להגביה א\"ע כנשר בלי טעם ודעת כלל כי הוא מזרע עמלק דכתיב ראשית<sup data-n=\"2379\">40</sup> גוים עמלק כמבואר במ\"א.\n<b>ולכך</b> הפיל פור הוא הגורל פי' הפור דהמן הוא הגורל דקדושה שהי' ביו\"כ שבגורל הוא ג\"כ בבחי' למעלה מהדעת שאין בו ברירה ובחירה בדעת כ\"א איך שנפל מלמעלה מהשכל איזה שעיר יהי' לה' וכך יהא כו'. ולנגד זה עשה המן בקליפה ג\"כ בבחי' התנשאות למדרי' זו להיות מפילים הפור הוא הגורל לפניו מבחי' שלמעלה מהדעת ואיך שיפול כך יהי' בלי בחירה ודעת כלל.\n<b>והנה</b> כל פרטי אריכות הענין של המקיף מראש ע\"ס קצר המצע מהשתרע רק דרך כלל תחילה מזמן חורבן בית ראשון ירדה מדת מל' דאצילות בסתר המדריג' להתלבש בטוב שבקליפת נוגה דבי\"ע שזהו בחי' אחשוורוש וושתי המלכה ואח\"כ העבירה<sup data-n=\"2380\">41</sup> וימלוך<sup data-n=\"2381\">42</sup> לאסתר תחת ושתי ואח\"כ גדל<sup data-n=\"2382\">43</sup> את המן ויעבור<sup data-n=\"2383\">44</sup> טבעתו מעל ידו ויתנה להמן שבחי' הטבעת המלך הנ\"ל נתן להמן בקליפה ואח\"כ ע\"י התשובה של ישראל במס\"נ בפועל זכו שיעבירנה מהמן ויתנה למרדכי היהודי דווקא מצד שזכו למדריגות שם היהודים בחי' הודאה שזהו מדריגות טבעת המלך, וז\"ש המן בליבו למי יחפוץ המלך לעשות יקר יותר ממני מצד גודל עוצם התנשאותו כנשר למעלה רצה להמשיך בחי' יקר העליון של הלבוש והסוס העליון אליו לקליפה אבל ה' ברחמיו הרבים הפר<sup data-n=\"2384\">45</sup> עצתו וקלקל מחשבתו והושיב לו גמולו בראשו להיות הוא דווקא מלביש למרדכי בלבוש מל' הנ\"ל, וירכיבהו<sup data-n=\"2385\">46</sup> ברחוב העיר כו' שזה המדריגה בחי' ההכנעה דקליפה שאדרבה דווקא הוא הלבישו כו' וכ\"ז זכו ע\"י התשובה ע\"י המס\"נ",[["2377","38","<b>את זה לעומת זה עשה האלקים</b>: לשון הכתוב קהלת ז, יד."],["2378","39","<b>וחוצפה. . מזרע עמלק</b>: ראה גם תו\"א פג, ד. פה, ב."],["2379","40","<b>ראשית גוים עמלק כמבואר במ\"א</b>: בלק כד, א. וראה סה\"מ תקס\"ה ח\"א ע' שצג. ובכ\"מ."],["2380","41","<b>העבירה</b>: תיבה זו אינה ברורה בהכת\"י."],["2381","42","<b>וימלוך לאסתר תחת ושתי</b>: ראה אסתר ב, ד. יז."],["2382","43","<b>גדל את המן</b>: שם ג, א."],["2383","44","<b>ויעבור טבעתו מעל ידו</b>: שם ג, י."],["2384","45","<b>הפר עצתו</b>: נוסח על הניסים."],["2385","46","<b>וירכיבהו ברחוב העיר</b>: אסתר ו, יא."]]],[2100490431,"בפ\"מ בפורים, וזהו מה ששמע<sup data-n=\"2386\">47</sup> ממורו הרב המגיד דמעזריטש ע\"ה שיוה\"כ<sup data-n=\"2387\">48</sup> הוא זמן התשו\"ע של כנ\"י הוא נמשל ונדמה לפורים שהוא כפורים ולא כפורים ממש שבחי' פורים הוא למעלה ממנו עד שנדמה לפורים להיות נק' כפורים והיינו מפני שעיקר תשו\"ע הי' בפורים שמסרו נפשם בפו\"מ עד שלא ימצא דווקא ימי משתה ושמחה כתיב פי' משתה הוא יין בחי' התגלות הסוד עליון כי נכנס<sup data-n=\"2388\">49</sup> יין יצא סוד וכן שמחה היא בחי' התגלות הנעלם כנודע והיינו שבפורים זכו לקבל השפע עליונה של התורה בתוך גלוי הכלים ממש מה שלא הי' מקודם אף בשעת מ\"ת שרק החילו לעשות וכן לעת\"ל נאמר בבכי<sup data-n=\"2389\">50</sup> יבואו כו' וזהו וקבלו היהודים את אשר החלו לעשות וד\"ל.",[["2386","47","<b>ששמע ממורו הרב המגיד דמעזריטש</b>: [הובא גם בתו\"א צב, ד. צג סע\"ג. צה, סע\"ד. ק, סע\"א ואילך. קכא, א]. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שפב. מאמרי אדה\"א נ\"ך ע' שסו ואילך. ויקרא ח\"א ע' קפט. דברים ח\"א ע' לו וע' עה. ח\"ג ע' תתלז. שם דרושי חתונה ח\"א ע' רו."],["2387","48","<b>שיוה\"כ. . ונדמה לפורים</b>: ראה ת\"ז תכ\"א (נז, ב). סידור שער הפורים רפג, סע\"ב."],["2388","49","<b>נכנס יין יצא סוד</b>: עירובין סה, סע\"א."],["2389","50","<b>בבכי יבואו</b>: ירמי' לא, ח."]]],[2100490432,"<h3>אם ישים אליו לבו</h3>\n<b>בסעודה הנ\"ל</b>\n<b>אם</b><sup data-n=\"2390\">1</sup> ישים<sup data-n=\"2391\">2</sup> אליו לבו רוחו ונשמתו אליו יאסוף, להבין מפני מה שינה הלשון שבתחילה אמר אם ישים אליו לבו ולבסוף נאמר בלשון יאסף והל\"ל בתחילה ג\"כ יאסוף או אף בסוף ישים כו'.\n<b>אך</b> הענין הוא דהנה ישים הוא בחי' עשי' מלשון שם<sup data-n=\"2392\">3</sup> שם לו כו', דהיינו מפני שבחי' התעוררות הרעותא דליבא שלמטה של כנ\"י נחשב לגבי עצמותו ית' לבחי' עשי' גשמית כי יהי' איך שיהי' היא מגושמת לגבי' ית' ונחשב לעשי' גשמיות ממש וזהו אם ישים אליו ליבו לכשיתעורר לבבו שהיא גשמי לשום אותה אליו בבחי' עשי' גשמית ממש (וזהו אם ישים אליו ליבו) אזי בזה נק' חסידיו הגדול ית' שיומשך עי\"ז בלבבו הגשמי בחי' אתעדל\"ע שרוחו ונשמתו של הקב\"ה אליו יאסוף, רוחו הוא בחי' ממכ\"ע ונשמתו הוא בחי' סוכ\"ע אליו יאסוף ממש, וזהו קיימו וקבלו היהודים, וקבלו קרי וקבל כתיב דהיינו שבאמת למעלה כנ\"י צרורות ומיוחדות בתכלית היחוד בבחי' רעותא דליבא שלמעלה שהיא למעלה מבחי' התחלקות אבל למטה נעשה ענפין מתפרדין בבחי' התחלקות צרופי האותיות כו' וזהו וקבלו קרי שהקרי הוא למטה מהכתיב כנודע ליו\"ח וד\"ל.",[["2390","1","<b>אם ישים</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 735 (קכח, ב). הנחת כ\"ק אדה\"א (מגוכתי\"ק 1025 יד, ב) נדפס בתו\"א קכא, ג.\nהגהות על תו\"א נדפס באוה\"ת מג\"א ע' סו."],["2391","2","<b>אם ישים אליו לבו</b>: איוב לד, יד."],["2392","3","<b>שם שם לו</b>: בשלח טו, כה."]]],[2100490433,"<h3>ביאור על הנ\"ל</h3>\n<b>קצת ביאור על הנ\"ל</b>\n<b>ושורש</b> הדברים הנ\"ל, הנה סוסים נקראו בחי' הכלים דנוק' עליונים והרוכבים הם בחי' האורות דמ\"ד המלובשים תוך הכלים שנק' בשם רוכבים מצד התלבשותן בתוכם, והנה לכך נק' הכלים דנוק' בשם סוסים מצד שיש מעלה יתירה בהכלים דמ\"נ יותר מבהאורות דמ\"ד כמו שיש מעלה יתירה בהסוס יותר מהרוכב דהיינו שהסוס מגביה ומנשא את הרוכב ממקום מדרון למקום הר גבוה אשר לא הי' ביכולת הרוכב להגיע שם כשהי' הולך רגלי כך ימצא מעלה יתירה בהכלים דמ\"נ יותר מהאורות בזה במה שבלתי ההעלאות לא הי' נמשך המ\"ד מעצמו כלל כ\"א ע\"י ההעלאות מ\"ן נתעורר למעלה אתעדל\"ע להשפיע המ\"ד לתוך הכלים דמ\"נ נמצא יש בזה מעלה יתירה בהמ\"נ שלמעלה מהמ\"ד שמעורר המ\"ד ממקור שורשו מה שלא הי' בכוחו ויכולתו בעצמו כנ\"ל ולכך נק' בחי' הכלים דמ\"נ בשם סו\"ס גימטר' ב\"פ גס פי' כי הנוק' עיקר בנינה מהגבורות שהם המ\"נ דילה שהם בגבורות רשפי אש למעלה מעלה בחי' התנשאות והסתלקות כמ\"ש אלקים אל דומיה לך כו' וזהו בגבורת הסוס שהוא בחי' גס מצד ההגבהה וההתנשאות בגבורות רשפי אש למעלה וזהו בחי' גס הא' שבבחי' העלאות מ\"ן, והשני הוא בבחי' המ\"ד שלמעלה שנמשך ע\"י המ\"נ הזה שהוא מתנשא מימ\"ע בבחי' רוממות והתנשאות מהחיצונים שלא יגיע השפע אליהם זולתו לסט' דקדושה בלבד, וזהו סוס<sup data-n=\"2393\">4</sup> ורוכבו רמה בים רמה<sup data-n=\"2394\">5</sup> יש ב' משמעות לשון התרוממות ולשון מפלה והרמה למטה, זה לישראל וזה לאוה\"ע, וזהו הקו האמצעי שהוא דת\"י שעולה עד הכתר שלשם אין מגיע השפע להחיצונים מצד הארת הכתר בחי' התנשאות בהם משא\"כ בחי' קו ימינא ושמאלא שאמרז\"ל דלא<sup data-n=\"2395\">6</sup> כאברהם שיצא ממנו ישמעאל ודלא כיצחק שיצא ממנו עשו אלא כיעקב כו' כי אברהם<sup data-n=\"2396\">7</sup> ויצחק שלמעלה הם ב' ידות העליונים ימינא ושמאלא ששניהם מגדלים הצפרנים הם המותרות שלהם שנאחזים בהם החיצונים אבל לא בקו האמצעי דע\"י שעולה עד הכתר כנ\"ל וד\"ל.\n<b>וזהו</b> שאמרו נעשה ונשמע כמ\"ש בע\"ח שמבחי' הכלים דאצילות נעשו אורות בבי\"ע ולכן תחילה צריכים להמשיך בחי' האורות בהכלים דאצילות שאף שזה מקרי עשי' לגבי עצמות המאציל שאף החכמה ראשית הנאצלים נחשבת לעשי' גשמיות כמ\"ש כולם<sup data-n=\"2397\">8</sup> בחכמה עשית כו' ואח\"כ כשכבר המשיכו האורות בהכלים דאצילות אז ונשמע וקבל השפע דהכלים דאצילות שמשפיעים בבי\"ע בחי' אורות וד\"ל.\n<b>וזהו</b> סוד יביאו לבוש מלכות והסוס אשר רכב עליו המלך ואשר ניתן כתר מל' בראשו זהו כללות ע\"ס דאצילות ואשר ניתן כתר מל' בראשו הוא בחי' כתר",[["2393","4","<b>סוס ורוכבו רמה בים</b>: בשלח טו, א."],["2394","5","<b>רמה. . התרוממות. . מפלה</b>: ראה גם תו\"ח בשלח [הוצאת קה\"ת — תשס\"ג] קסט, א. וש\"נ."],["2395","6","<b>דלא כאברהם שיצא ממנו ישמעאל</b>: ראה פסחים נו, א."],["2396","7","<b>אברהם ויצחק. . ימינא ושמאלא</b>: ראה זהר בראשית קנ, א."],["2397","8","<b>כולם בחכמה עשית</b>: תהלים קד, כד."]]],[2100490434,"דאצילות שנק' בשם כתר מל' ועליה<sup data-n=\"2398\">9</sup> אתמר מגיד מראשית אחרית ואיהו קרקפתא דתפילין כו' פי' כי בחשבון ומנין הע\"ס מלמעלה למטה אזי כתר הוא כתר ומל' הוא מל' אבל בחשבון ומנין הספי' [מלמטה למעלה] אזי מל' הוא כתר וכתר הוא מל' העשירית. והטעם לזה הוא כמ\"ש בס\"י<sup data-n=\"2399\">10</sup> נעוץ תחילתן בסופן וסופן בתחילתן דווקא שהארת הכ\"ע הוא במל' סופא דכל דרגין דווקא, וזהו מגיד מראשית אחרית ראשית הוא הכ\"ע מגיד ונמשך לאחרית הוא בחי' מל' דאצילות וזהו ואשר ניתן כתר מל' בראשו בראשו דאיש אשר המלך חפץ ביקרו הוא בחי' ז\"א דאצילות שנק' איש הכולל כל הע\"ס דאצילות וכנ\"ל וד\"ל.\n<b>והנה</b> בזכרי'<sup data-n=\"2400\">11</sup> נאמר המרכבה של הסוסים סוסים אדומים מסט' דגבורה סוסים לבנים מסט' דחסד סוסים אמוצים וברודים הם מקו האמצעי בחי' ארגמן הכולל כמה גוונין ביחד, וזהו ענין הסוס אשר רכב עליו המלך כו' כנ\"ל וד\"ל.\n<b>",[["2398","9","<b>ועליה אתמר מגיד מראשית. . קרקפתא דתפילין</b>: פתח אלי'."],["2399","10","<b>בס\"י נעוץ תחלתן בסופן</b>: ראה ס\"י פ\"א, מ\"ז."],["2400","11","<b>בזכרי'</b>: ו, ב-ג."]]],[2100490435,"<h3>בגמרא</b> (מסכת פסחים קיט, ב) דרש רב עוירא עתיד הקב\"ה לעשות סעודה</h3>\n<b>בגמרא</b><sup data-n=\"2401\">1</sup> (מסכת פסחים קיט, ב) דרש רב עוירא זמנין אמר לה משמי' דרב אמי וזמנין אמר לה משמי' דרב אסי מ\"ד ויגדל<sup data-n=\"2402\">2</sup> הילד ויגמל ויעש אברהם משתה גדול ביום הגמל את יצחק עתיד הקב\"ה לעשות סעודה לצדיקים ביום שיגמל חסד עם זרעו של יצחק אחר שאוכלין ושותין נותנין לו כוס של ברכה (פי' כוס יין<sup data-n=\"2403\">3</sup> המשומר בענבין משי\"ב כמ\"ש במ\"א) לאברהם לברך אומרים לו ברוך אומר להם אני לא אבריך כו' עד שאומרים לדוד טול אתה לברך אומר אני אבריך ולי נאה לברך שנאמר כוס<sup data-n=\"2404\">4</sup> ישועות אשא וכו'.\n<b>הנה</b> כתיב ויין<sup data-n=\"2405\">5</sup> ישמח לבב אנוש כו' המשמח<sup data-n=\"2406\">6</sup> אלוקי' ואנשים כו' דהיינו כמארז\"ל נכנס<sup data-n=\"2407\">7</sup> יין יצא סוד להיות פועל השמחה בלב האדם שהשמחה הוא בחי'",[["2401","1","<b>בגמרא (מסכת פסחים קיט, ב) דרש רב עוירא</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 735 קלב, ב.\nהנחת כ\"ק אדמו\"ר האמצעי ממאמר זה נדפס בסידור קב, א. [מגוכתי\"ק 1025 ה, ב] בד\"ה ענין ברכת הזימון.\nהנחת המהרי\"ל ממאמר זה נדפס לקמן ע' שמו בד\"ה הנותן שלג כצמר. וע' רעה בד\"ה ענין יין המשומר.\nראה אוה\"ת עקב ע' תקלט ואילך.\nמאמר זה נדפס ג\"כ במאמרי אדה\"ז ש\"ס ע' פא."],["2402","2","<b>ויגדל הילד ויגמל</b>: בראשית כא, ח."],["2403","3","<b>יין המשומר בענבין משי\"ב</b>: ברכות לד, ב. (וראה עוד מזה בארוכה בהנסמן בס' הלקוטים למאמרי אדמו\"ר הצ\"צ ערך יין ע' תשכז)."],["2404","4","<b>כוס ישועות אשא</b>: תהלים קטז, יג."],["2405","5","<b>ויין ישמח לבב אנוש</b>: תהלים קד, טו."],["2406","6","<b>המשמח אלקי' ואנשים</b>: שופטים ט, יג."],["2407","7","<b>נכנס יין יצא סוד</b>: עירובין סד, א."]]],[2100490436,"התגלות אשר צהבו פניו כו' ויצא סוד הנעלם בגלוי הלב בשמחה בבחי' השמחה והתבונה כו' והיינו בעבודת ה' כשיתבונן המשכיל בגדולת א\"ס ב\"ה בהרחבת דעתו אזי יוליד מזה בחי' שמחה בלבו לשמח בה' ית' כמ\"ש ישמח<sup data-n=\"2408\">8</sup> ישראל בעושיו כו' שזהו שורש ענין היין שלמעלה שישמח לבב אנוש (וכמ\"ש אם<sup data-n=\"2409\">9</sup> הבנים שמחה וכמ\"ש במ\"א) אך כ\"ז בחי' היין שנסחט מענביו דווק' שאז דווק' מקרי יין אבל בעודינו עצור וכנוס בענביו לא מקרי יין וכמארז\"ל בגמ' וזהו בחי' עה\"ד טו\"ר כמארז\"ל אשכול<sup data-n=\"2410\">10</sup> של ענבים סחטה לו דייק' שהוא מקרי יין המשמח כו' והיינו שמבחי' היין זה יוכל להיות טוב שהוא פעולת המשחה באלוקות להיות ישמח ישראל בעושיו בהתגלות לבבו וכן יוכל להסתעף ממנו ההיפוך בחי' רע כו' מפני שהוא בחי' אלינא דטו\"ר שזהו עה\"ד שחט'<sup data-n=\"2411\">11</sup> בו עה\"ד והענין הוא בהיות היין הוא נסחט מענב' שהם הכלים שלו שנפרד מהם ויצא בבחי' התגלות לחוץ לזאת פועל ג\"כ השמחה בהתגלות הלב שמסתעף מהדעת וההרגשה שהוא בחי' התגלות יש ודבר מה שמרגיש בבחי' הרגשה בדעתו ממש בגדולת ה' ב\"ה ולכך מסתעף ממנו השמחה בהתגלות לבבו בבחי' יש ודבר נרגש בלב ממש ולזאת יוכל להסתעף ממנו גם ההיפוך בחי' רע ח\"ו כמ\"ש במ\"א אבל בחי' יין המשומר בענביו משי\"ב פי' הוא חמר' דמנטר' תוך ענביו בבחי' העלם שכנוס בתוכם ולא נפרד מהם עדיין לחוץ והוא מו' י\"ב קודם חט' אדה\"ר הוא בחי' עה\"ח.\n<b>וביאור</b> הענין הוא דהנה אמרז\"ל הרואה<sup data-n=\"2412\">12</sup> ענבים אוכמין בחלום סימן רע לו ענבים חוורין סימן יפה לו פי' ענבים של מעלה הם בחי' הכלים דאצילות שהן הכלים של היין המשומר בתוכם הוא בחי' אור א\"ס ב\"ה המלובש בהם בבחי' העלם ומיוחד עמהם בתכלית היחוד דאיהו וגרמוהי כולא חד בהון ממש כמו היין הגשמי המשומר בענביו טרם הפרדו מהם שלא נק' עדיין שם יין עליו מצד היחוד שלו בתוך הכלים שלו הם הענבים שלא נסחט ונפרד מהם עדיין להיות עלה בשם דבר בפ\"ע כ\"א יחיד ומיוחד עימהם מתחי' בריאתם ונעלם בהם בבחי' העלם עד שאינו עולה בשם דבר בפ\"ע כלל משא\"כ כשנסחט מהם שאז נפרד ויצא לחוץ בבחי' התגלות להיות מהות דבר בפ\"ע אז נק' בשם יין כו' כמו\"כ עד'מ למעלה בחי' יין המשומר בענביו מו' י\"ב הם בחי' האורות עליונים דאצילות שנמשכו באוא\"ס בתחי' האצילות שמשומרים בתוך הכלים בבחי' העלם והסתר דאצילות שנק' ענבים ומיוחדים עמהם בתכלית היחוד להיות איהו וגרמוהי חד ממש והם משתמרים בתוך הכלים בבחי' העלם והסתר עד שאינו עולים בשם דבר בפ\"ע ולא מקרי עדיין יין כנ\"ל מצד שאינם נרגשים עדיין בבחי' גלוי למהות דבר בפ\"ע כו' כ\"א נעלמים וגנוזים בתוך הענבים בבחי' העלם והתכללות בתכלית היחוד מתחי' האצילות וכ\"ז",[["2408","8","<b>ישמח ישראל בעושיו</b>: תהלים קמט, ב."],["2409","9","<b>אם הבנים שמחה</b>: שם קיג, ט."],["2410","10","<b>אשכול של ענבים סחטה לו</b>: ראה ב\"ר פי\"ט, ה. זח\"א לו, א. קצב, א. זח\"ב רסז, ב. זח\"ג רלו, א."],["2411","11","<b>שחט' בו עה\"ד</b>: כ\"ה בהכת\"י. ואוצ\"ל: שחטא בו אדה\"ר."],["2412","12","<b>הרואה ענבים אוכמין בחלום סימן רע לו</b>: ראה ברכות נו, סע\"ב. מדרש תהלים קכח, ד. זח\"א קצב, א. זח\"ב קמד, א."]]],[2100490437,"קודם חט' אדה\"ר אבל לאחר חט' אדה\"ר נפרדו האורות מתוך הכלים להיות יוצאין בבחי' גלוי שאז נק' יין המשמח כו' שאין הכלים מיוחדים בתכלית היחוד עם האורות כמקדם כי הרי יש בהן בחי' עליות וירידות בשבת ויו\"ט עליות ובחול ירידות כו'.\n<b>וביאור</b> הענין בחי' יין המשומר למט' הוא כענין שנאמר שמחו<sup data-n=\"2413\">13</sup> צדיקים בה' וישמחו<sup data-n=\"2414\">14</sup> בך כל חוסי בך כו' פי' שאין השמחה בהתגלות לבבו בבחי' יש ודבר נרגש בפ\"ע המסתעף מהדעת וההרגשה ממש שזהו בחי' יין סתם שנסחט מענביו המשמח לבב אנוש כנ\"ל כ\"א השמחה נעלמה וגנוזה ומיוחדת בהוי' ממש בתכלית היחוד בבחי' הוי' ממש בלי הרגשה כלל שהוא בבחי' אין האמיתי שהוא בבחי' יין המשומר בענביו ממש שהוא בחי' עה\"ח שלא יתסעף מהם בחי' רע ח\"ו כלל למעלה מבחי' עה\"ד טו\"ר כנ\"ל ומה שארז\"ל נכנס יין דווק' יצא סוד פי' מה שנק' בשם יין שנסחט מענביו ונפרד להיות יש ודבר בפ\"ע להיות נק' בשם יין זה מגלה הסוד הנעלם להיות מתגלה בבחי' גלוי הלב בבחי' שמחה וחדווה כו' אבל יין המשומר בענביו הוא עיקר הסוד הנעלם שהיין כנוס ועצור בתוך ענביו הם הכלים שלו בהעלם גדול ובהתכללות ויחוד אמיתי והיינו כמ\"ש שמחו צדיקים בה' וישמחו כל חוסי בך כו' וד\"ל.\n<b>והנה</b> לע\"ל יהי' מבחי' יין המשומר בענביו כוס של ברכה בסעודת הצדיקים כו' דהיינו כמה שנת' שע\"י כוס של ברכה מזמנין בחי' הבריכה עליונה ממקור הברכה ע\"י ברכת הזימן ואח\"כ מתחלק השפע לחלקים בבחי' ג' קוין העליונים כו' שעתה בחי' הברכה עצמה שמזמנין בכוס של ברכה הוא בחי' יין המשומר בענביו כנ\"ל שהוא בחי' הבריכה העליונה כנודע אבל לע\"ל יהי' מזה הברכה בחי' כוס גדול של ברכה ויצטרכו לזמן בו ברכה עליונה וגבוה הגבה למעלה מאוד נעלה ממנו מפני שאף הוא יצטרך להמשכת ברכה עליונה הגבוה מאוד נעלה ממנו כמו שמצטרכים עתה בכוס של ברכה שלמטה להמשיך ממנו הבריכה כו' והיינו<sup data-n=\"2415\">15</sup> שלע\"ל בזמן עליות העולמות יהי' הוא בחי' כוס של ברכה שלמטה להמשך ממנו הבריכה כו' והיינו שלע\"ל בזמן עליות העולמות יהי' הוא בחי' כוס של ברכה לבד והבריכה יהי' נמשכת מעצמות אוא\"ס ב\"ה שלמעלה מבחי' הכלים הפשוט בתכלית הפשיטות מגדר הכלים לגמרי שבחי' יין המשומר בענביו הוא בחי' האורות המלובשים בתוך הכלים ומיוחדים בתכלית היחוד להיות איהו וגרמוהי חד דהיינו בחי' השמחה הנעלמה בהוי' שהוא בבחי' אין כו' אבל הבריכה העליונה תהי' נמשכת מעצמות אוא\"ס ב\"ה שהוא למעלה מהכלים שמופשט מגדר הכלים לגמרי שהוא למעלה אף מבחי' מקור התענוגים וזהו ע\"י הזימון בכוס של ברכה של יין המשומר כנ\"ל.\n<b>וז\"ש</b> באגדה הנ\"ל לאחר שאוכלין ושותין נותנים כוס של ברכה לאברהם כו' ואמר להם אני לא אברך לפי שכבר יצא ממני ישמעאל כנ\"ל פי' אברהם הוא בחי'",[["2413","13","<b>שמחו צדיקים בה'</b>: תהלים צז, יב."],["2414","14","<b>וישמחו בך כל חוסי בך</b>: שם ה, יב."],["2415","15","<b>והיינו. . הבריכה כו'</b>: כ\"ה בהכת\"י. והוא טעות המעתיק, ומיותר."]]],[2100490438,"קו ימין חח\"ן באצילות שיצא ממנו ישמעאל בחי' חסד דקליפה שנסתעף מבחי' חסד דקדושה דקו ימין דאצילות ולכך אינו יכול לברך על כוס ש\"ב של יין המשומר להמשיך הבריכה מאוא\"ס ב\"ה שלמעלה מהכלים מאחר שהוא בחי' קו כזו שיכול להסתעף ממנו בחי' ישמעאל הגם שלע\"ל כתיב ואת<sup data-n=\"2416\">16</sup> רוח הטומאה אעביר מן כו' ולא יהי' עוד בחי' ישמעאל רק מצד שהוא קו כזו שיכול להסתעף ממנו ישמעאל אעפ\"י שלא יהי' עוד אז לע\"ל אינו יכול לברך להמשיך הבריכה עליונה ע\"י כוס של ברכה של יין המשומר כנ\"ל וכן ביצחק הוא קו שמאל דאצילות שיצא ממנו עשיו אף שלא יהי' לע\"ל כשרוח הטומאה יעבור כנ\"ל רק מאחר שהקו שלו גורם סיבת הסתעפות בחי' עשיו שיצא כבר ונסתעף ממנו לכך אינו יכול לברך כו' כנ\"ל (וזהו דקדוק לשונם לפי שכבר הנ\"ל אף שעתה איננו כי רוח עברה ותטהרם כו') נותנין לו ליעקב אומר להם אני לא אברך לפי שכבר נשאתי שתי אחיות בחייהון שעתידה תורה כו' פי' יעקב הוא בחי' קו האמצעי מאצילות בחי' בריח התיכון שמבריח מן הקצה אל הקצה שהוא כללא דאבוהון שלמותי' דכולא והי' ראוי לברך בכוס של ברכה כו' השיב להם אני לא אברך לפי שכבר נשאתי שתי אחיות כנ\"ל פי' הם ב' פרצופים דלאה ורחל שהם ב' עולמות עלמ' דאתכסיא ועלמא דאתגלי' שחיבר ב' עולמות אלו ביחד כמ\"ש ברוך<sup data-n=\"2417\">17</sup> ה' מן העולם ועד העולם כו' פי' ברוך הוא המשכה מן העולם היא עלמ' דאתכסי' ועד העולם הוא עלמ' דאתגלי' שיתחבר ביחד שזה עשה יעקב שנשא שתי אחיות בחייהון כו' ולכן מצד<sup data-n=\"2418\">18</sup> אומר אני לא אברך הבריכ' העליונה בכוס ש\"ב ביין המשומר כנ\"ל וד\"ל, אומרים לו לדוד טול אתה וברך אומר אני אברך ולי נאה לברך שנאמר כוס ישועות אשא כנ\"ל פי' דהע\"ה הוא בחי' מל' מדת מל' דאצילות ונאמר בס\"י נעוץ סופן בתחילתן ותחילתן בסופן דייק' לכך אמר אני אברך ולי נאה לברך מצד היות כ\"ד<sup data-n=\"2419\">19</sup> דאצילות שנעוץ תחילתן בסופן דייק' וסופן בתחילתן דייק' לכך לי נאה לברך דייק' בחי' הבריכה העליונה מעצמות אוא\"ס ב\"ה שלמעלה מהכלי' ע\"י כוס ישועות דיין המשומר כנ\"ל וד\"ל.",[["2416","16","<b>ואת רוח הטומאה אעביר</b>: זכרי' יג, ב."],["2417","17","<b>ברוך ה' מן העולם ועד העולם</b>: ראה דה\"א כט, י."],["2418","18","<b>מצד</b>: אוצ\"ל: מצד זה."],["2419","19","<b>כ\"ד</b>: כ\"ה בהכת\"י."]]],[2100490439,"<h3>נוסח שני: הנותן שלג כצמר</h3>\n<b>הנותן</b><sup data-n=\"2420\">1</sup> שלג כצמר<sup data-n=\"2421\">2</sup> כפור כאפר כו' ישב רוחו יזלו מים כו' הנה כתיב מים<sup data-n=\"2422\">3</sup> חיים יצאו מירושלים חציים אל הים הקדמוני וחציים אל הים האחרון וידוע מארז'ל שאין<sup data-n=\"2423\">4</sup> טפה יורדת מלמעלה אא\"כ טיפיים עולה כנגדה מלמטה והטעם ידוע לפי שבמל' שהוא מקבל שתי קומות מכמו שמקבלת וכמ\"ש ואולך<sup data-n=\"2424\">5</sup> אתכם קוממיות כו'.\n<b>והנה</b> יש להקדים מהו יין<sup data-n=\"2425\">6</sup> המשומר בענביו שארז\"ל<sup data-n=\"2426\">7</sup> שעליו אינו רוצה אברהם לברך לעתיד מפני שיצא ממנו ישמעאל ויצחק לפי שיצא ממנו עשיו עד דוד שאמר לי נאה לברך וכמ\"ש כוס ישועות אשא. הנה יין סתם הוא בחי' התגלות והיינו מ\"ש אשכול<sup data-n=\"2427\">8</sup> על ענבים סחטה כו' דהיינו שיצא היין מן הענבים ונתגלה מההעלם שהעלימוהו הענבים כו' והיינו בחי' חסדים המגולים מן החזה ולמטה שיש שם שרש להיות עה\"ד טו\"ר כו' והיינו כמו עד\"מ האהבה באלקו' המורגש אצלו שיש שרש בזה למדות הקשות וישות כו' משא\"כ ענין שמחת בית השואבה הוא ע\"ד התענוג והשמחה הנולד מההתבוננות בגדולת הבורא שבלתי מורגש כלל מחמת תכלית אמיתית העמקות הדעת בהשגה אזי התענוג ממילא נולד ולא יורגש אליו כו' וזהו שמחו<sup data-n=\"2428\">9</sup> צדיקים בה' שהשמחה היא כלולה באלקות ממש והיינו עד\"מ למעלה חסדים הסתומים ביסוד דאימה שהם למטה מהרגשה וע\"ש ואתה<sup data-n=\"2429\">10</sup> מרום ה' כו' אוביך כו' יעקב שמח<sup data-n=\"2430\">11</sup> כו' ואמנם שרש ההעלם זה שבלתי מורגש הוא הכתר שהוא שרש לכל העולמות כמ\"ש אהי'<sup data-n=\"2431\">12</sup> אשר שלחני כו' שיש אהי' באימא והיינו ת\"ת דאימא שנעשה כתר לז\"א כתר הפרטי אבל אהי' שבכתר הכללי הנק' אהי' אשר אהי', אנא<sup data-n=\"2432\">13</sup> זמין לאתגלאה הוא שרש לכל הנעלמים שהוא כללי כו'.\n<b>והנה</b> כעת נק' המל' כוס של ברכה שהוא בחי' התגלות והיינו מה שסחטה לו אשכול של ענבים שיצאו האורות ונתגלה וההמשכה הוא מבחי' הבריכה העליונה שהוא הכתר הנ\"ל ולע\"ל שתהי' הנקבה<sup data-n=\"2433\">14</sup> תסובב גבר עלית המל' בכתר",[["2420","1","<b>הנותן שלג כצמר</b>: הנחת המהרי\"ל. נעתק מכת\"י 80 עו, א. נמצא ג\"כ בכת\"י 392 מא, א. 523 שו, ב. 735 צ, ב.\nהנחת כ\"ק אדמו\"ר האמצעי — ד\"ה ”ענין ברכת הזימון\" נדפס בסידור קב, א [מגוכתי\"ק 1025 ה, ב].\nהנחת ר' משה בן אדה\"ז ממאמר זה נדפס לעיל ע' שמב בד\"ה בגמרא. . דרש רב עוירא.\nמאמר זה נדפס ג\"כ במאמרי אדה\"ז הקצרים ע' רמז."],["2421","2","<b>הנותן שלג כצמר</b>: תהלים קמז, טז."],["2422","3","<b>מים. . האחרון</b>: זכרי' יד, ט."],["2423","4","<b>שאין. . מלמטה</b>: ראה ירושלמי ברכות פ\"ט ה\"ב."],["2424","5","<b>ואולך אתכם קוממיות</b>: בחוקותי כו, יג. וראה ב\"ב עה, א."],["2425","6","<b>יין. . בענביו</b>: ברכות לד, ב."],["2426","7","<b>שארז\"ל</b>: פסחים קיט, ב."],["2427","8","<b>אשכול. . סחטה</b>: ראה ב\"ר פי\"ט, ה. ובכ\"מ."],["2428","9","<b>שמחו צדיקים בה'</b>: תהלים צז, יב."],["2429","10","<b>ואתה. . אוביך</b>: תהלים צב, ט-י."],["2430","11","<b>שמח</b>: נ\"א: שמש ומגן."],["2431","12","<b>אהיה. . שלחני</b>: ראה שמות ג, יד."],["2432","13","<b>אנא זמין לאתגלאה</b>: ראה זח\"ג סה, סע\"א ואילך."],["2433","14","<b>הנקבה תסובב גבר</b>: ירמי' לא, כב."]]],[2100490440,"וכתר יהי' מל' שמה שעתה הוא מל' כח הפועל בנפעל יהי' אז הכתר כו' א\"כ יקרא כוס של ברכה וההמשכה אליו יהי' ממקום היותר גבוה יהי' בחי' א\"ק וזהו שאמרו כסא<sup data-n=\"2434\">15</sup> דמשיחא רכ\"א לוגין והיינו כוסי רוי' בגימט' רכ\"א והוא אותיות אר\"ך דהיינו א\"א כו' כי נעוץ תחב\"ס ע\"כ הכתר נעשה מל' ומה שהמל' נעשה שתי קומות הוא כי הכתר הוא כעת ממוצע בין המאציל לנאצלים שיש בו מע\"ס הגנוזות שהם הסתומים והנעלמים בעצמותו והוא שרש ג\"כ לע\"ס הגלוים דאצילות ולע\"ל שתתעלה המל' בכתר תהי' שתי קומות כו' וד\"ל.\n<b>אך</b> ביאור הענין הוא שלע\"ל שיהא מים חיים יוצאים כו' היינו שרש מקיפים דאור ישר ומקיפים דאו\"ח ופי' מקיפים דאור ישר עד\"מ השכל שלמעלה מהיותו מוגבל בכלי השגה והרי זה בחי' העלם של הכלי ופי' מקיפים דאו\"ח עד\"מ מי שהבין השכל לכאורה לפום ריהטא ואמנם עדיין לא נתיישב במוחו היטב שיהי' ברור בלי קושיא והנה כאשר ירצה שיתיישב בתוך הכלי אזי יסתלק ממנו מפני שא\"א להגביל ולהתיישב להיות למעלה הרבה והרי זה העלם שבדרך חזרתו מלמטה למעלה והוא עולה עד מקור הכח היולי המשכיל על כל דבר כו' וכמו\"כ אנו רואים שכאשר לא יבין השכל אחרי העיון וסבתו הסתלקות הנ\"ל אזי אח\"כ ע\"י ההעמקה יומשך השפעת שכל ממקורו והיינו ע\"י הסתלקות זו של המקיף דאו\"ח מעורר עד בעצמיות המשכיל וממשיך שם שפע חדשה וזהו ג\"כ שאמר הגמרא שתיק<sup data-n=\"2435\">16</sup> רב ואח\"כ השיג להם כמו שע\"י הקושיא שלהם נסתלק שכלו בבחי' אור חוזר ונעשה מקיף אזי ממשיך שפע חדשה כו' וזהו הטעם מילי<sup data-n=\"2436\">17</sup> בסלע שתיקותא בתרין שנמשך ב\"פ מכמו שע\"י הדיבור והיינו ענין שתיקותא והנה כמו\"כ למעלה דעכשיו נק' המל' מקבלת ונק' כוס של ברכה כנ\"ל וכתר הוא המשפיע ונק' בריכה ולע\"ל שיקרא הכתר מל' יקראוהו כוס והא\"ק נק' משפיע וכמו שעתה יש למעלה מהכתר כך לע\"ל שא\"ק יהי' במקום כתר א\"כ מוכרח שיש למעלה הימנו דהיינו עצמיות הא\"ס כו' ומפני שהכתר יהי' בחי' מקבל א\"כ מה שהוא למעלה הימנו והוא בחי' א\"ק הוא כענין בחי' מקיף דאו\"י עליון וד\"ל.",[["2434","15","<b>כסא. . לוגין</b>: ראה יומא עו, א."],["2435","16","<b>שתיק רב</b>: סוכה ז, א. ובכ\"מ."],["2436","17","<b>מילי. . בתרין</b>: מגילה יח, א."]]],[2100490441,"<h3>ענין יין המשומר (המשך)</h3>\n<b>ענין</b><sup data-n=\"2437\">1</sup> יין המשומר<sup data-n=\"2438\">2</sup> בענביו מששת ימי בראשית כו' הנה בר\"מ<sup data-n=\"2439\">3</sup> פ' בא מבואר איך שיש ג' בחי' מקור ומעין וחפירה רברבא מעיין דא יו\"ד ואח\"כ ז' נחלים והם ג\"ר כח\"ב וז\"ת ז' נחלים כו'. והנה בינה הוא ההשגה וההבנה המושגת ומובנת לו וחכ' הוא המקור שממנו נמשך ונובע ההשגה ונק' שכל הנעלם והכתר הוא המקור והשרש גם לשכל הנעלם שיהי' נובע ממקורו.\n<b>והנה</b> בבהמ\"ז יש ג' ברכות ברכת הזן הוא חסד עד ברכת בונה ירושלים בחי' ת\"ת וכוס של ברכה הוא המל' שבה נמשכים כל המשכות המוחין חו\"ג וכדוגמת האותיות שמגבילים בתוכה השכל ומדותיו והרי זה ככוס גשמי שמקבל היין וזהו וברכת<sup data-n=\"2440\">4</sup> את הוי' אלהיך את הוא המל'. וכמו\"כ ענין ברכות שלפני המצות שאומרים ברוך אתה הוי' אלהינו מלך העולם אתה הוא חסד הוי' ת\"ת אלקים גבורה ואח\"כ נמשך למל' והיינו מ\"ש מלך העולם. וזהו הטעם שיחיד<sup data-n=\"2441\">5</sup> או שנים שאוכלים פטורים מד\"ת משא\"כ בג' כי ע\"י ג' קווין נמשך השפע מבחי' חכמה והיינו ענין התורה דאורייתא מחכמה כו' משא\"כ ע\"י שנים או אחד.\n<b>והנה</b> עתה הוא התלבשות מל' דאצי' בנוגה דבריאה [ונאמר<sup data-n=\"2442\">6</sup> ענבימו<sup data-n=\"2443\">7</sup> ענבי רוש שהמל' הגם שנק' ענבין<sup data-n=\"2444\">8</sup> אוכמין לגבי אימא מ'מ לגבי ענבין שבבחי' נוק' איקרי עינבי חיוור' כו']. ומזה הוא התהוות מאכלים גשמיים [ובשבת הוא עלי' של המל'], משא\"כ לע\"ל יהי' הסעודה מלויתן [דכל מה שיש ביבשה יש בים וכמ\"ש וידגו] שנאמר עליו לויתן זה יצרת לשחק בו לויתן היינו יחוד או\"א ע'י יסוד אבא המלובש ביסוד דאימא לויתן לשון התחברות כמו הפעם<sup data-n=\"2445\">9</sup> ילוה אישי לויתן<sup data-n=\"2446\">10</sup> חן וענקים לגרגרותיך וממנו נמשך השחוק שהוא בחי' תענוג והיינו באימא שנק' עוה\"ב והוא התגלות התענוגים משא\"כ בחכמה הוא העלם ועצמות התענוג ונק' עדן והבינה נק' נהר היוצא מעדן.\n<b>ועל</b> סעודה זו הי' כוס של ברכה ביין המשומר בענביו שהוא מו\"ק דאבא הנק' ששת ימי בראשית שהם בבחי' שבירה כי ג' ראשונות הן למע' מהשבירה",[["2437","1","<b>ענין יין המשומר</b>: הנחת המהרי\"ל. נעתק מכת\"י 80 עט, א. נמצא ג\"כ בכת\"י 392 מד, א. 735 צא, א.\nהנחת כ\"ק אדמו\"ר האמצעי — ד\"ה ”ענין ברכת הזימון\" נדפס בסידור קב, א. [מגוכתי\"ק 1025 ה, ב].\nהנחת ר' משה בן אדה\"ז ממאמר זה נדפס לעיל ע' שמב בד\"ה בגמרא. . דרש רב עוירא.\nמאמר זה נדפס ג\"כ במאמרי אדה\"ז הקצרים ע' שיא."],["2438","2","<b>ענין יין המשומר</b>: ברכות לד, ב."],["2439","3","<b>בר\"מ פ' בא</b>: מב, ב."],["2440","4","<b>וברכת. . אלקיך</b>: עקב ח, י."],["2441","5","<b>שיחיד. . בג'</b>: ראה אבות פ\"ג מ\"ג."],["2442","6","<b>ונאמר. . כו'. ובשבת. . המל'. דכל וידגו</b>: כל המוסגר כאן בין חצאי עיגול, נמצא כאן רק בכת\"י 735 הנ\"ל, ובכת\"י 80, 392 בא קטע זה בסוף הדרוש (כמועתק לקמן — בין חצאי עיגול)."],["2443","7","<b>ענבימו. . רוש</b>: האזינו לב, לב."],["2444","8","<b>ענבין אוכמין. . חיוורין</b>: ראה זח\"א קצב, א."],["2445","9","<b>הפעם ילוה אישי</b>: ויצא כט, לד."],["2446","10","<b>לויתן. . לגרגרותיך</b>: משלי א, ט."]]],[2100490442,"וכמארז\"ל יעקב<sup data-n=\"2447\">11</sup> אבינו לא מת כו' וע\"כ המקור ומעיין וחפירה יהי' למעלה משהן עתה והיינו בג\"ר כי כתר חו\"ב שבכתר כתר שבכתר הוא המקור ח\"ס הוא המעיין ובינה דא\"א הוא החפירה וז' נחלים הם חג\"ת דא\"א שהם למעלה מעלה גם מאו\"א שאבא בחסד דא\"א אחיד ותליא ובינה מלבשת לגבורה דא\"א כמ\"ש אני<sup data-n=\"2448\">12</sup> בינה לי גבורה כו' וענין מדות חו\"ג באריך שהוא למעלה מעלה מהמדות הוא כענין שנמצאים החו\"ג בשכל שהרי השכל הוא המקור להם וממילא מוכרח שנמצא בהשכל וכך גם בא\"א יש גם המדות. ועליו אברהם<sup data-n=\"2449\">13</sup> אינו רוצה לברך מפני שיצא ממנו ישמעאל ויצחק מפני שיצא ממנו עשיו והגם שלע\"ל יתבררו הברורים מ\"מ אינו יכול כ\"כ להגביה הכוס למעלה מאחר שהי' ממנו יניקה תחלה יעקב<sup data-n=\"2450\">14</sup> אמר לא אברך מפני שנשא ב' אחיות שעתידה תורה לאוסרן עלי.\n<b>הנה</b> עיקר איסור העריות נאמר בתורה בלשון גילוי עריות וכמ\"ש ערות<sup data-n=\"2451\">15</sup> אמך לא תגלה והיינו כי באצי' היחוד הוא בבחי' עריות כי אימא נק' אמו או חמותו מל' נק' בתו וכתיב אמור<sup data-n=\"2452\">16</sup> לחכמה אחותי את רק שבבי\"ע אסור לעשות כן ושם הוא הערוה והיינו מפני שאצי' הוא בבחי' אתכסי' איהו<sup data-n=\"2453\">17</sup> וגרמוהי חד ע\"כ יהי היחוד שלום משא\"כ בבי\"ע שנק' עולם הפירוד בחי' אתגלי' ע\"כ הם שם בחי' ערוה וזה שנק' גילוי עריות גילוי דוקא שהוא בבי\"ע. והנה יעקב הי מרכבה לבחי' אצי' ומטעם זה הי' מותר לו לישא ב' אחיות ומ\"מ הרי עתידה תורה לאוסרה עליו שהרי אצילות הוא מקור על הבריאה ויהי' מזה גילוי עריות. משה אמר לא אברך שלא זכה לכנוס לא\"י והיינו שהי' מעולם היותר גבוה ואין לו שייכות לזה כלל. רק דוד אמר לי נאה לברך כוס<sup data-n=\"2454\">18</sup> ישועות אשא כי דוד הוא בחי' רחל בחי' מל' ועכשיו נק' יעקב בעלה דמטרוניתא ולע\"ל יהי' עליות המל' בכתר אשת<sup data-n=\"2455\">19</sup> עט\"ב והי'<sup data-n=\"2456\">20</sup> אור הלבנה כאור החמה. (וכל<sup data-n=\"2457\">21</sup> מה שיש ביבשה יש בים וכמ\"ש וידגו, ובשבת הוא עליות המל' ונאמר ענבימו ענבי רוש שבמל' גם שנק' ענבי אוכמי לגבי אימא מ\"מ לגבי ענבים שבבחי' נוגה נק' ענבי חוורין כו').",[["2447","11","<b>יעקב אבינו לא מת</b>: תענית ה, ב."],["2448","12","<b>אני. . גבורה</b>: משלי ח, יד."],["2449","13","<b>אברהם אינו רוצה</b>: פסחים קיט, ב."],["2450","14","<b>יעקב. . אחיות</b>: ראה עד\"ז גם בד\"ה יעקב נשא במאמרי אדה\"ז הקצרים — פסחים קיט, ב."],["2451","15","<b>ערות. . תגלה</b>: אמור כ, יט."],["2452","16","<b>אמור. . את</b>: משלי ז, ד."],["2453","17","<b>איהו. . חד</b>: הקדמת תקו\"ז ג, ב."],["2454","18","<b>כוס. . אשא</b>: תהלים קטז, יג."],["2455","19","<b>אשת. . בעלה</b>: שם יב, ד."],["2456","20","<b>והי'. . החמה</b>: ישעי' ל, כו."],["2457","21","<b>וכל. . כו'</b>: רק בכת\"י 80, 392. וראה לעיל. ונראה שהוספה זו נכתבה על הגליון, ולא ידע המעתיק לאן שייכת."]]],[2100490443,"<h3>ביאור שני לדרוש ע\"פ יונתי בחגוי הסלע</h3>\n<b></b><b>בעז\"ה, ליל שבת פ' צו </b>\nליל שבת פ' צו\n<b>(ביאור</b><sup data-n=\"2458\">1</sup> שני לדרוש דפ' משפטי' ע\"פ יונתי בחגוי הסלע כו')",[["2458","1","<b>ביאור שני לדרוש דפ' משפטים</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (כג, א). נמצא ג\"כ בכת\"י 2045 צג, ב. בכותרת: ביאור על הנ\"ל. נדפס בשינויים בלקו\"ת שה\"ש יט, ב — כ, ב (אותיות א-ב)."]]],[2100490444,"להבין שרשי הדברים הנאמרי' ע\"פ יונתי<sup data-n=\"2459\">2</sup> בחגוי הסלע כו' קומי לך רעייתי יפתי כו', הנה שורש ענין ותורה<sup data-n=\"2460\">3</sup> שם בישראל כו' יובן בהקדים תחלה שרש ענין התורה מה היא דהנה ארז\"ל נובלות<sup data-n=\"2461\">4</sup> חכמה של מעלה תורה. פי' נובלו\"ת הוא בחי' חיצוניו' ואחוריי' דחכמה עילא' כמשל עלה הנובלת מן עיקר הפרי שגדל באילן וכיוצא, ויש להבין הלא התורה היא חכמתו ית' והוא נק' חכים<sup data-n=\"2462\">5</sup> ולא בחכמה ידיע' כו' ואיך יתכן שתהא התורה רק בבחי' נובלו\"ת חש\"מ בבחי' אחוריי' וחיצוניו' בלבד.\n<b>אך</b> הענין יובן בהקדים תחלה שעיקר התורה הנגלית נתלבשה במדות בלבד דהיינו בדרך כלל בששה מדו' כשר פסול טמא טהור אסור מותר חייב זכאי וכיוצא והן כלולי' בשיתא סדרי משנה בדרך כללות סדר זרעים בבחי' מדת החסד כו' סדר נשים בת\"ת וחכמה בנזיקין ודעת בסדר קדשים כמובן מתוך דבריהם ז\"ל ע\"פ<sup data-n=\"2463\">6</sup> והי' אמונת עתך כו' ודרך כלל הוא רק בחי' השפעת החכמה במדות בלבד דהיינו אם כשר או פסול או טמא טהור כו' והענין הוא אם זה ראוי להשראת אור א\"ס וכשר להיו' בחי' כלי או פסול כו' וכן טמא או טהור כו' וא\"כ החכמה בזה הוא רק בבחי' גילוי אור א\"ס למטה שבמדו' דאצי' הוא בחי' ז\"א שהן בחי' מדו' עליונו' אם בכך וכך יוכשר שפע האור לבא למטה או בכך וכך ויש בזה בחי' חו\"ג שמאל<sup data-n=\"2464\">7</sup> דוחה וימין מקרבת כו' לומר בכך יתקרב ויוכשר ולא בכך שכאשר יפסוק הדין פסול ה\"ז שמאל דוחה שלא יקרב לפניה' ולא ישכון בו אור א\"ס וכאשר יפסוק הדין כשר ה\"ז בחי' ימין מקרבת לקרב הדבר לאור אלקי להיו' כשר להשראת אור א\"ס כו'.\n<b>וכמו</b> שהוא למטה כך הענין למעלה בכל פנימי' אור ושפע שיש בכל מצוה ומצוה שבתורה בפרט אם המשכה או העלא' הנק' מ\"ד ומ\"ן כל זה נתברר בחכמה איך ובמה תהא המשכת מ\"ד ואיך ובמה תהי' בחי' העלא' מ\"ן ע\"י מעשה &lt;קכח&gt;\nהמצוה והוא רק עפ\"י חכמה וטעם והיינו חכמה שבמדו' בלבד כמו ע\"ד דוגמא מצות הקרבנו'<sup data-n=\"2465\">8</sup> יש בהן הכונה בהעלא' מ\"ן והמשכת מ\"ד כמ\"ש בהם",[["2459","2","<b>יונתי בחגוי הסלע</b>: שה\"ש ב, יד."],["2460","3","<b>ותורה שם בישראל</b>: תהלים עח, ה."],["2461","4","<b>נובלות חכמה של מעלה תורה</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז."],["2462","5","<b>חכים ולא בחכמה ידיעא</b>: ת\"ז בהקדמה (פתח אליהו)."],["2463","6","<b>ע\"פ והי' אמונת עתיך</b>: ישעי' לג, ו. וראה שבת לא, סע\"א."],["2464","7","<b>שמאל דוחה וימין מקרבת</b>: סוטה מז, א."],["2465","8","<b>הקרבנו'. . בהעלאת מ\"ן והמשכת מ\"ד</b>: ראה ג\"כ תו\"א בראשית ח, ד. כ, ג. כה, ד. לקו\"ת ויקרא ב, ב. תו\"ח וישלח קפט, ד. אוה\"ת חקת ע' תשפו. בלק (הוספות) ע' 17. ובכ\"מ."]]],[2100490445,"לחמי<sup data-n=\"2466\">9</sup> לאשי ריח ניחוחי וידוע פי' רי\"ח שהוא בחי' העלא' מ\"ן מרפ\"ח כו' שנפל בשבירת הכלים בבהמו' דפני שור שבמרכבה דנוגה דעשי' כו' והמשכת מ\"ד הוא פי' ניחו\"ח<sup data-n=\"2467\">10</sup> לשון נחות דרגא וכמ\"ש וירח<sup data-n=\"2468\">11</sup> ה' את ריח הניחוח ויאמר כו' ואם יעשה ויקריב הקרבן בפסול לא יהי' לריח ולא לניחוח הרי יש בחי' חכמה עליונה באופן שעשה הקרבן בכשרו' איך שיהי' לריח ניחוח ובאיזה אופן יהי' הכשרו לבחי' מ\"ד כו' והרי כל זה רק עפ\"י החכמה אמנם אין השפעה זו מחכמה עילא' של המאציל רק מבחי' נובלו\"ת והוא בחי' חיצוניו' ואחוריי' בלבד מעצמו' אור חכמתו כו' שהרי אין חכמה זו רק איך שיהי' אופן הכשר לגילוי אור א\"ס במדו' אם בחסדי' או בגבורו' ודרך כלל הוא בחי' מ\"ן ומ\"ד כו' אבל לבחי' עצמות אור המאציל לא נק' חכמה זו בשם פנימי' כלל כי אין כל זה נוגע לבחי' עצמותו כו' וד\"ל ויובן זה עד\"מ מהשפעת שכל האדם שמתלבש במדותיו אם להיטב חסדו כך או כך כשיש לפניו הרבה דרכים שאע\"פ שכל מה שיעשה במדותיו הכל משפע השכל הוא מ\"מ אין זה עצם חכמתו כמו שהיא מצד עצמה בכח השכלי שלו שהוא רק להשכיל ההשכלות והחכמו' בלבד אלא הוא רק השפלת השכל איך להנהיג א\"ע במדותיו כו' וכך אוריי'<sup data-n=\"2469\">12</sup> דלעילא שהגם שידוע דמחכמה עילא' נפק' אבל היא רק מבחי' חיצוניו' ונובלו' לגבי עצם אור פנימי' אבא כו' כי לא יש ערך בין גילוי אור א\"ס במדות לגבי עצמו' אורו כו', והתלבשו' זו דאור אבא במדו' דז\"א נק' תור\"ה להבדיל<sup data-n=\"2470\">13</sup> בין הטמא לטהור כו' וזהו שנק' נובלו\"ת חכמה שלמעלה וד\"ל.\n<b>והנה</b> כתיב למען<sup data-n=\"2471\">14</sup> אחיי וריעיי כו' שיש נשמות<sup data-n=\"2472\">15</sup> שנק' אחים וריעים לבחי' ז\"א מפני שנולדו ונאצלו יחד עם ז\"א מיחוד או\"א עילאי' כו' והם<sup data-n=\"2473\">16</sup> גבוהי' מבחי' החכמה שבז\"א שהיא התורה ועליהם נא' ותורה שם בישראל והוא בחי' ישראל<sup data-n=\"2474\">17</sup> שעלה במחשבה שעל ידו נמשך התורה כנ\"ל כו'. וביאור הדברים הנה",[["2466","9","<b>לחמי לאשי ריח ניחוחי</b>: פינחס כח, ב."],["2467","10","<b>ניחו\"ח לשון נחות דרגא</b>: לקו\"ת פינחס עו, א. עז, א. עח, ד. ובכ\"מ. וראה גם מאמרי אדה\"ז תקס\"ד ע' סז ובהנסמן במ\"מ לשם."],["2468","11","<b>וירח ה' את ריח הניחוח</b>: נח ח, כא."],["2469","12","אוריי'. . דמחכמה עילא' נפקת' זהר בשלח סב, א. יתרו פה, א. (רע\"מ) משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["2470","13","<b>להבדיל בין הטמא לטהור</b>: שמיני יא, מז."],["2471","14","<b>למען אחיי וריעיי</b>: תהלים קכב, ח."],["2472","15","<b>נשמות שנק' אחים ורעים לבחי' ז\"א</b>: ראה לקו\"ת שה\"ש יט, סע\"ב ואילך. וראה בארוכה בביאוה\"ז להצ\"צ כרך א' ע' תקמו ואילך. תורת שמואל תרל\"ג ח\"א ע' מט. ח\"ב ע' תקצו."],["2473","16","<b>והם גבוהים. . שהיא התורה</b>: ראה לקו\"ת שם: והן הנשמות שנק' אחים ורעים למקום כמ\"ש למען אחיי ורעיי כו' ומבאר בזהר שהן למעלה אפילו מבחי' בנים (ע' זהר דקכ\"א סע\"ב וד' צד סע\"ב ח\"ג ד\"ז ע\"ב). . והם למעלה מבחי' תורה וכמש\"נ ג\"כ בביאור ע\"פ ששים המה מלכות [לקו\"ת שם מ, סע\"ב — בסופו]. וראה יהל אור ע' תפו-ז. סה\"מ תקס\"ד ע' קו."],["2474","17","<b>ישראל שעלה במחשבה</b>: ראה ב\"ר פ\"א, ד. שע\"ת קטו, ב. ש\"א פ, א."]]],[2100490446,"הנשמו'<sup data-n=\"2475\">18</sup> שהם באים מבחי' יחוד זו\"נ היינו כשאור אלקי יורד ונמשך מאין ליש שהוא מאצי' לבריא' ממש אבל בחי' נשמה דאצי' עצמו היינו בחי' מדרי' אלקו' ממש והוא בחי' אור אצי' כמו שהוא קודם שירד בבריאה כו' אלא שהוא רק מבחי' הכלים החיצונים דאצי' וד\"ל. ופי' בחי' כלים שבאצי' ידוע כי הוא בחי' הגבול שיש גם בבחי' האצי' והגם דבאצי' איהו<sup data-n=\"2476\">19</sup> וחיוהי וגרמוהי חד כו' שגם הכלים הנק' גרמוהי הוא בבחי' א\"ס זהו רק הכלים די\"ס דז\"א דוקא משום דאור א\"ס ממש שורה בכל ספי' וספי' דז\"א כמו שנא' לך<sup data-n=\"2477\">20</sup> הגדולה כו' שהוא אור החסד דז\"א שנק' גדולה הרי אור א\"ס ממש שורה במדת החסד הזה והוא מ\"ש לגדולתו<sup data-n=\"2478\">21</sup> אין חקר כו' והיינו לך ה' הגדולה כידוע ועד\"ז גם באור הבינה אע\"פ שהיא ג\"כ בבחי' אור וכלי נא' לתבונתו<sup data-n=\"2479\">22</sup> אין מספר והוא בחי' אור א\"ס שבבינה ועד\"ז בכל פרטי פרטי' י\"ס דז\"א וכמאמר אנת<sup data-n=\"2480\">23</sup> חכים ולא בחכמ' ידיע' מבין ולא בבינה ידיע' כו' וד\"ל משא\"כ בחי' הנשמות שיש באצי' אע\"פ שהם כחות אבל הם רק חלק מצומצם בבחי' גבול ע\"ד האצי' והוא מפני שאין אור א\"ס שורה &lt;קכט&gt;\nממש בהן אלא הם כחות נבדלים יותר מעצמות אור המאציל כענין שכליים נבדלי' למטה כו' ומ\"מ הם כחות אלקיים רק שהמה כחות מצומצמים ולכך נק' אחים וריעי' לז\"א מפני ששרש אחד להן מאור המאציל אלא שנאצלו בבחי' גבול כו' ולהיותם בבחי' האלקי' לכך אינם יכולי' לסבול כל דבר רע אף בתערובו' דטו\"ר כי<sup data-n=\"2481\">24</sup> לא יגורך רע כתיב וכן טהור<sup data-n=\"2482\">25</sup> עינים מראו' ברע כו'.\n<b>וזהו</b> שאמרו בזוהר<sup data-n=\"2483\">26</sup> באדה\"ר כשחטא בעה\"ד פרח מיני' זיהר\"א עילא\"ה פי' זיהר\"א עילא\"ה היינו בחי' זוהר אור האצי' והוא שרש נשמתו כמו שהיא בבחי' האצי' דהיינו בחי' מזלא כו' וע\"ז או' טהורה היא פי' בבי\"ע חלק הנשמ' בלתי טהורה כ\"כ כי יש בה בחי' תערובו' דעה\"ד טו\"ר לפעמים אבל חלק הנשמה שבבחי' אצי' הנק' זיהרא עילא' טהורה היא בתמידו' לפי שאין דבר רע מתקרב שם כלל וכמ\"ש וכבודי<sup data-n=\"2484\">27</sup> לאחר לא אתן כו' ולכך כשחטא אדה\"ר פרח ונסתלק ממנו זיהרא עילאה הנ\"ל וכן בדוד<sup data-n=\"2485\">28</sup> אמרו שנסתלק' ממנו רוה\"ק ו' חדשים מפני חטאו וכמ\"ש במ\"א וד\"ל ויש הרבה נשמו' שהיו מבחי' האצי' כמו נשמו' הג' סבו' ונשמת רשב\"י ור\"ע ור\"א וגם הנה לכל נשמה ונשמה יש בשרשה בחי' אצי' וכמאמר הידוע",[["2475","18","<b>הנשמו'. . יחוד זו\"נ. . מאצי' לבריאה</b>: ראה לקו\"ת שם: וכמ\"ש בע\"ח שער סדר אבי\"ע פ\"ד וה'."],["2476","19","<b>איהו וחיוהי וגרמוהי חד</b>: תקו\"ז בהקדמה (פתח אלי')."],["2477","20","<b>לך הגדולה</b>: דברי הימים-א כט, יא."],["2478","21","<b>לגדולתו אין חקר</b>: תהלים קמה, ג."],["2479","22","<b>לתבונתו אין מספר</b>: תהלים קמז, ה."],["2480","23","<b>אנת חכים ולא בחכמ' ידיעא</b>: ת\"ז בהקדמה (פתח אלי')."],["2481","24","<b>כי לא יגורך רע</b>: תהלים ה, ה."],["2482","25","<b>טהור עינים מראות ברע</b>: חבקוק א, יג."],["2483","26","<b>בזהר באדה\"ר. . זיהרא עילאה</b>: וראה גם המשך תער\"ב ח\"ג ע' א'שפ שמבאר זה באריכות."],["2484","27","<b>וכבודי לאחר לא אתן</b>: ישעי' מב, ח."],["2485","28","<b>בדוד. . רוה\"ק ו' חדשים מפני חטאו וכמ\"ש במ\"א</b>: ראה סנהדרין קז, א. יומא כב, א. סה\"מ תקס\"ד ע' קו."]]],[2100490447,"דמזלי\"ה<sup data-n=\"2486\">29</sup> חז\"י וא\"כ מהו ההפרש בין אותן נשמות לשאר הנשמות אך הנה הענין הוא שאותן הנשמות<sup data-n=\"2487\">30</sup> דאצי' היו מלובשי' למטה בגופים גשמיים בעולם הזה השפל ג\"כ כמו נשמת רשב\"י שהי' לו בחי' נשמה דאצי' מלובשת בחומר גופני כו' וכיוצא בו בהרבה תנאים שנק' אחים וריעי' כו' אבל שאר כללו' נ\"י אין אור זה דאצי' מלובש בגופי' שלהם אלא נשאר האור בבחי' אצי' בהעלם ומקיף בלבד וכמ\"ש אך<sup data-n=\"2488\">31</sup> בצלם יתהלך איש וכמ\"ש במ\"א וד\"ל.\n<b>וזהו</b> שרש ענין ותורה שם בישראל לפי שישראל עלה במחשבה כנ\"ל דהנה פי' עלה במחשבה היינו בבחי' החכמ\"ה שנק' חשב מ\"ה כידוע, והנה ידוע בדרך כלל דד'<sup data-n=\"2489\">32</sup> אותיות דשם הוי' היו\"ד<sup data-n=\"2490\">33</sup> בחכמה והה\"א בבינה כו' והן כללו' ד' העולמות אצי' בריאה החכמה באצי' והוא היוד ההא דבינה בבריאה כו' וכתיב והחכמה<sup data-n=\"2491\">34</sup> מאין תמצא שהוא בחי' הכתר וכשאו' ישראל על\"ה במחשבה פי' עלה היינו בבחי' פנימי' החכמה והטעם שנק' שם בשם על\"ה הוא לפי שידוע הכלל בענין עילה ועלול שבחי' היחוד שלהם הוא בבחי' הפנימי' דהיינו בחי' פנימי' של העלול הוא שעולה ומתייחד בעילתו ודבוק בו ובחי' חיצוניו' של העלול הוא שיורד ומשפיע לעילה המקבלת מאתו כו' ועד\"ז משתלשל ויורד מעילה לעילה כידוע והנה לפ\"ז הכלל הרי דוקא בחי' פנימי' החכמה דבוקה בכתר עליון כי בחי' הכתר לגבי החכמה נק' עילה לגבי עלול שהרי החכמה עלולה מן הכתר וכמ\"ש והחכמה מאין תמצא כו' וכל עלול דבוק פנימיותו בעילתו וחיצוניותו מתפשטת למטה הימנו הרי מה שמתפשט מאור החכמה למטה הימנו דהיינו במדות דז\"א שהוא באיסור והיתר טמא טהור כנ\"ל הוא רק מבחי' חיצוניות אור החכמה אבל בחי' פנימי' אור החכמה הדבוקה בבחי' הכתר היא גבוה הרבה מאד נעלה עד שאינה מתפשטת כלל בתורה כי למעלה הרבה מחכמה שבתורה היא עד שבחי' &lt;קל&gt;\nהחכמה שמלובשת בתורה אינה רק בחי' נובלו' ואחוריי' ממנה כנ\"ל דנובלו' חכמה של מעלה תורה וע\"ז נא' ופני<sup data-n=\"2492\">35</sup> לא יראו דהיינו פנימי' אור אבא אך ישרא\"ל על\"ה שם במחשבה שהוא בחי' פנימי' אור אבא לפי שנק' בנים ובן<sup data-n=\"2493\">36</sup> נמשך ממוח האב מבחי' הפנימי' שבטפה",[["2486","29","<b>דמזליה חזי</b>: ראה מגילה ג, א."],["2487","30","<b>הנשמות. . האצי'. . רשב\"י</b>: ראה ג\"כ לקו\"ת שה\"ש יט, ג. סה\"מ תקס\"ד שם: נשמתם המה מבחי' אצי' ממש. . כנשמת רשב\"י וכיוצא בו. ושם נמצא הג\"ה מכ\"ק אדהצ\"צ ע\"ז: וע' בת\"א פ' בא בענין שם צבאות וי\"ל ע\"ד שאמר משה ונתתי עשב [ואתחנן יא, טו. וראה לקו\"ת בחוקותי נ, א. ובארוכה לקו\"ש ח\"ד ע' 1087]. וע\"ד שהמלאך נברא נק' לפעמים בשם ה' [ראה אגה\"ק סכ\"ה]. גם ע\"ד ראה נתתיך אלקים לפרעה."],["2488","31","<b>אך בצלם יתהלך איש וכמ\"ש במ\"א</b>: תהלים לט, ז. וראה בארוכה בתו\"ח תצוה [הוצאת קה\"ת — תשס\"ג] שלט, ד. מאמרי אדה\"א תצא ע' תצח."],["2489","32","<b>דד' אותיות דשם הוי'. . ד' העולמות</b>: וראה לקו\"ת במדבר ה, ב. וש\"נ."],["2490","33","<b>היו\"ד בחכמה והה\"א בבינה</b>: ראה זהר בראשית לא, א. (רע\"מ משפטים) קכג, ב. (אד\"ז האזינו) רצ, ב. וראה פרדס שער (כז) האותיות פי\"ג."],["2491","34","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["2492","35","<b>ופני לא יראו</b>: תשא לג, כג."],["2493","36","<b>ובן נמשך ממוח האב</b>: ראה תניא פ\"ב."]]],[2100490448,"הרוחנית שבמוחי' כידוע ולזה הטעם גבוהי' הנשמו' מן המלאכי' לפי שהמלאכי'<sup data-n=\"2494\">37</sup> שרשם רק מבחי' הבל הדיבור שהרי בדבר ה' ורוח<sup data-n=\"2495\">38</sup> פיו כל צבאם והנשמות מבחי' פנימי' המוחי' והגם שהדיבור יותר דק ורוחני מהטפה שבמוחי' עד\"מ מ\"מ המוחי' שמהם הטפה הרוחניו' יותר בחי' פנימי' הן מן הדיבור אע\"פ שנראי' בהגשמה יותר וגם יותר פנימי' הן מגופו של שכל וחכמה שבמוח שמאיר לדיבור כמ\"ש במ\"א וד\"ל.\n<b>וזהו</b> פי' ישראל עלה במחשבה דהיינו בבחי' עליי' של אור פנימי' אבא כשהוא דבוק באור הכתר כנ\"ל וזהו הטעם שאמר ותורה שם בישראל שע\"י ישראל זה שעלה במחשבה נמשך התורה לפי שבחי' חיצוניו' חכמה שנמשך בתורה תלוי זה בבחי' הפנימי' דחכמה והוא ע\"י שרש נשמת ישראל דלעילא שדבוק באור הכתר עד שמשם ממשיך מקור החכמה בבחי' הפנימי' ויוכל אור החכמה להתפשט אח\"כ בבחי' חיצוניו' למטה במדות דז\"א כו' ולכך בישראל דלעילא תליא מלתא וד\"ל, וזהו ג\"כ ענין מה שמצינו שהתורה נק' תורת משה דוקא כמ\"ש תורה<sup data-n=\"2496\">39</sup> ציוה לנו מש\"ה כו' כי הנה שרש בחי' נשמת<sup data-n=\"2497\">40</sup> משה הוא מבחי' פנימי' אור אבא כנ\"ל בכללו' נ\"י בשרשם בהעלם ובמשה הי' ניצוץ מזה מלובש למטה בגופו (כענין שכינה<sup data-n=\"2498\">41</sup> מדברת מתוך גרונו כו') וע\"י מש\"ה נמשכה החכמה להיות מלובשת במדות שהוא בבחי' נובלות ואחוריי' בלבד כנ\"ל ולא מבחי' הפנימי' כנ\"ל ע\"כ תורה זו ציוה לנו משה שעל ידו דוקא ירדה בהתלבשו' חיצוניות זאת ולכך בכל פ' נאמר ויאמר<sup data-n=\"2499\">42</sup> ה' אל משה לפי שבו הדבר תלוי מטעם הנ\"ל וד\"ל ומבואר בזוהר דאתפשטותי'<sup data-n=\"2500\">43</sup> דמשה בכל דרא ודרא כו' שיש בכל דור נשמות גבוהות מבחי' משה והוא מבחי' פנימי' אור החכמה כמו נשמת<sup data-n=\"2501\">*43</sup> ר\"ע ורשב\"י וכיוצא וכן בכל דור ודור יש נשמות וניצוצו' שמלובשים בגופים מבחי' משה ע\"כ מצינו בגמרא שרב ספרא אמר לרבא משה<sup data-n=\"2502\">44</sup> שפיר קאמרת מפני שנשמת רבא הי' מבחי' משה באותו הדור (ולפי שרבא הי' ניצוץ ר\"ע דאמרי' משמת<sup data-n=\"2503\">45</sup> ר\"ע נולד רבי ומשמת רבי נולד רב יהודה ומשמת ר\"י נולד רבא ואין צדיק נפטר עד שנולד צדיק כמותו כו') ומ\"ש שפיר קאמרת ר\"ל מפני שבכח נשמת רבא תלויה המשכת חכמה זו בדין זה לכך אמר משה שפיר קאמרת שכאילו מפי משה ממש נאמרה הלכה זו כו' וד\"ל.",[["2494","37","<b>שהמלאכי' שרשם. . הדיבור</b>: ראה אגרת התשובה פ\"ד."],["2495","38","<b>ורוח פיו כל צבאם</b>: תהלים לג, ו."],["2496","39","<b>תורה צוה לנו משה</b>: ברכה לג, ד."],["2497","40","<b>נשמת משה הוא מבחי' פנימי' אור אבא</b>: ראה לקו\"ש ח\"ו ע' 244. וש\"נ."],["2498","41","<b>שכינה מדברת מתוך גרונו</b>: ראה זח\"ג רלב, א (ברע\"מ). ז, א. רסה, סע\"א. שמו\"ר פ\"ג, טו. ויק\"ר פ\"ב, ג."],["2499","42","<b>ויאמר ה' אל משה</b>: יתרו יט, ט."],["2500","43","<b>דאתפשטותי' דמשה בכל דרא ודרא</b>: תקו\"ז תס\"ט (קיב, רע\"א. קיד, רע\"א)."],["2501","*43","<b>נשמת. . רשב\"י</b>: ראה גם מאמרי אדה\"ז תקס\"ב ע' תלא. מאמרי אדה\"ז על פרשיות התורה ע' רנו. שער האמונה פה, ב. שערי אורה עג, ב. תו\"ח תולדות קנח, ב."],["2502","44","<b>משה שפיר קאמרת</b>: שבת קא, ב. וש\"נ."],["2503","45","<b>משמת ר\"ע נולד רבי</b>: ראה קידושין עב, ב."]]],[2100490449,"<b>וזהו</b> שרש ענין קומי<sup data-n=\"2504\">46</sup> לך רעייתי פרנסתי שמפרנסי'<sup data-n=\"2505\">47</sup> לאביהם שבשמים כו'. דהנה עד\"מ המאכל הוא הממשיך ומחבר הנפש לגוף וכל כח מכחו' הנפש מתחזק באבר מאברי הגוף כמו השכל במוח וכח הפעולה ביד וכיוצא ע\"י המאכל לכך נק' מזון פרנסה שמפרנס לגוף באורות הנשמה שבאי' ומתלבשי' בכל האיברי' וכו' כך הנמשל למשכיל למעלה דישראל מפרנסי' לאביהם שבשמים כו' דהנה ידוע בהתפשטו' י\"ס הנאצלים מעצמות המאציל &lt;קלא&gt;\nהם רק מבחי' גילוי אור ולא מבחי' עצמותו כלל כי אין ערוך כלל בין עצמות המאציל עם הנאצלים יותר משאין ערוך בין אצי' לבריאה דהנה הגם שבבחי' בריאה כבר הוא בא שם בבחי' הגבול והצמצום ממש מאין ליש כו' מ\"מ הרי נאמר כולם בחכמ\"ה עשית והנה ידוע בהתלבשות החכמה דאצי' בחכמה די\"ס דבריאה וחכמה דבריאה מתלבשת בחכמה דיציר' וחכמה דיצירה בחכמה דעשי' ומחכמה דעשי' נמשך חכמה האנושית אע\"פ שחכמה דעשי' רחוק ערכה מחכמה דבריאה ומכ\"ש לגבי חכמה דאצי' מ\"מ אחר שנתלבש ובא האור בהשתלשלו' מאצי' לבריא' הרי מ\"מ יש להם קצת ערך ושייכות עד\"מ השפעת וירידת אור השכל לתינוק ובהלבשו' במשלים רבים ושונים דמ\"מ אור השכל כמו שהוא נמצא גם במשל היותר אחרון כו' אבל מבחי' המאציל לנאצלי' אין ערוך כלל ולא נוכל לומר גם מעין ודוגמא מחכמה דאצי' לגבי חכמה שבמאציל אחר שאצי' ועשי' שוין שם ועל שניהם יחד או' כולם בחכמ\"ה עשי\"ת כלומר גם האצי' כי גם הוא כעשי' חשיבא כו' וד\"ל.\n<b>וזהו</b> שישראל מפרנסי' לאביהם שבשמים פי' אביה\"ם שבשמי\"ם הוא בחי' חכמה דאצי' המלובשת במדו' דז\"א שנק' שמי\"ם כידוע והוא בחי' התורה ג\"כ והפרנס' לאביהם הוא אור אבא היינו להמשיך מקור לחכמה בבחי' הפנימי' והוא מבחי' אור הכתר שבעצמות המאציל דהחכמ\"ה שם נק' עלול בלבד כו' וכמ\"ש והחכמה מאין תמצא כנ\"ל וזאת הפרנסה לחכמה הוא עד\"מ חיזוק המשכת כח השכל למוח ממקור השכל ע\"י המאכל וכיוצא ולכך נק' רעייתי פרנסתי שמפרנסי' לאביהם שבשמים והוא רק מצד שרש נשמתם שעלה ישראל במחשבה וביכולתם דוקא להמשיך מקור החכמה ואזי יוכל אור החכמה להתלבש גם בבחי' חיצוניות באיברים דז\"א דהיינו בכלל בבחי' המדות ושאר האיברים בפרט כי רמ\"ח<sup data-n=\"2506\">48</sup> מ\"ע רמ\"ח איברים כו' וד\"ל.\n<b>וזהו</b> שאמרו ז\"ל ועשיתם<sup data-n=\"2507\">49</sup> את\"ם כאילו עשאוני כו' פי' כאילו עשאוני לבחי' אדם דאצי' להיות מלובשי' בו האורו' בכלים ומבחי' אור אבא שרש כל האצי' כידוע וישראל עלה שם במחשבה כנ\"ל, וזהו ענין יאר<sup data-n=\"2508\">50</sup> ה' פניו אתנו פי' אתנ\"ו",[["2504","46","<b>קומי לך רעייתי</b>: שה\"ש ב, י."],["2505","47","<b>שמפרנסי' לאביהם שבשמים</b>: זח\"ג ז, ב. שהש\"ר ע\"פ לסוסתי. יל\"ש פקודי רמז תיח."],["2506","48","<b>רמ\"ח מ\"ע רמ\"ח איברים</b>: ראה תיקוני זהר ת\"ל. וראה תניא פ\"ד ובליקוט פירושים שם."],["2507","49","<b>ועשיתם אתם כאילו עשאוני</b>: ויקרא כו, ג. זח\"ג קיג, א. ויק\"ר פל\"ה, ז."],["2508","50","<b>יאר ה' פניו אתנו</b>: ראה תהלים סז, ב."]]],[2100490450,"דוקא כי ע\"י ישראל יאר ה' פניו במדות דז\"א עד שנמשך התורה להיות גילוי אור א\"ס למטה כנ\"ל וכתיב חכמת<sup data-n=\"2509\">51</sup> אדם תאיר פניו פי' שרש המוחי' דז\"א נמשך רק מבחי' חיצוניו' דאור אבא אבל כדי שיומשך שרש לזאת ההמשכה צריך להיות האור בבחי' פנימי' אור אבא והיינו בחי' הארת הפנים דאבא והוא דוקא מאור הכתר כנ\"ל וזהו יאר הוי' פניו אתנו ע\"י ישראל שעלה שם בבחי' הפנימי'. אך מה שאמר יאר ה' אתנו דוקא ולא לזולתו כו', הענין דאתנו כך הוא להיות כי אור זה הבא ומאיר בתורה להבדיל בין הטמא לטהור כו' הוא בא ע\"י צמצום אור השכל במקורו לדקדק בין ההשפעו' עד שיהי' נשפע גילוי אור א\"ס רק לטהור ולכשר כו' ויתרחק מפסול וטמא וזהו ע\"י הארת הפנים שמיוחדת ומובדלת לקדוש' בלבד כמו שלא ישרה גילוי אור א\"ס בחכמה אלא במניח תפילין ולומד התורה כו' ולא בזולת זה ואדרבה כל שאינו מניח תפילין יתרחק מזה וכן לענין אריכו' ימים במניח תפילין למען<sup data-n=\"2510\">52</sup> ירבו ימיכם כו' ובאוכל חלב ונכרתה<sup data-n=\"2511\">53</sup> הנפש בקצירת &lt;קלב&gt;\nימים וכיוצא שכל זה הוא עפ\"י בחי' אור פנים העליוני' בחכמ' עילא' הוא שהובדל והופרש אור השפע להיות מיוחד ומקודש ובא רק בבחי' הפנימי' ולא יבא בבחי' החיצוניות כו' והיינו יאר פניו אתנו דוקא ע\"י אמצעו' ישראל באה הבדלה זו להיות אורו' בכלים בקדוש' האלקי' דהיינו כאילו עשאונ\"י כו' וגם מפני זה לישראל בלבד הוא שמיוחד למטה בחי' הארת הפנים העליוני' הללו וכמ\"ש יאר ה' פניו אליך, אליך דוקא ולא לזולתם ומטעם הנ\"ל משום שהם דוקא נק' רעייתי כלומר פרנסתי שמפרנסי' לאביהם שבשמים וד\"ל.\n<b>ושרש</b> ענין יפת\"י שהן הלבושי' דמעשה המצות כמבואר שם הנה בשרש ענין המשכת התורה מבואר למעלה שהוא לעשו' בחי' אורו' וכלים באצי' ולהיו' בחי' י\"ס דאצי' מתפשטי' ממקורם ע\"י אור החכמה שהיא ראשית הגילוי כו' וזהו כאילו עשאוני לבחי' אדם והיינו ענין עוסק בתורה לשמה לשם התורה להיו' אור התורה נמשך במדו' כנ\"ל, אך הנה כל זה הוא בחי' התפשטו' האורו' די\"ס דאצי' בכלים שהוא עדיין הכל למעלה בבחי' האלקו' דהא איהו וחיוהי וגרמוהי חד כו' אמנם אין עדיין בחי' גילוי האור בא עד למטה ממש והוא גם בעולם הפירוד מאין ליש כו' שנמשך מבחי' מל' דאצי' כידוע שמלכותו<sup data-n=\"2512\">54</sup> בכל משלה וכתי' מלכותך<sup data-n=\"2513\">55</sup> מלכו' כ\"ע כו' אבל ע\"י המצות מעשיו' בא גילוי אור האלקי גם בעולמו' דבי\"ע הנפרדי' יש מאין ולכך המצות<sup data-n=\"2514\">56</sup> נק' מצות המלך כי לבוש מלכות דאצי' הוא ע\"י המצו' דוקא, וביאור הדברי' הנה הכלל ידוע בע\"ח שא\"א לבא גילוי אורות דאצי' בבי\"ע כ\"א ע\"י התלבשותן תחלה בבחי' מל' דאצי' ובין אצי' לבריא' יש בחי' הפרסא המפסיק כידוע ומל' דאצי' בוקע את אור המסך והפרסא הזאת",[["2509","51","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["2510","52","<b>למען ירבו ימיכם</b>: ואתחנן יא, כה."],["2511","53","<b>ונכרתה הנפש</b>: צו ז, כה."],["2512","54","<b>שמלכותו בכל משלה</b>: תהלים קג, יט."],["2513","55","<b>מלכותך מלכות כ\"ע</b>: תהלים קמה, יג."],["2514","56","<b>המצות נק' מצות המלך</b>: אסתר ג, ג. ובזח\"ג קעה, ב."]]],[2100490451,"ויורדת לבי\"ע ונמצא יש כאן ב\"פ צמצום והתלבשו' א' אורו' דאצי' במל' והב' מל' דאצי' ע\"י בקיעת המסך בבי\"ע כו' והנה באמת אם לא בחי' הלבוש הזה שמתלבש בו בחי' מל' לא הי' מדה זו יורדת להיו' בחי' מל' כו' בבי\"ע אחר שאין ערוך כלל בין נברא לבורא ועל מי ימלוך אחר שממנו נמצאי' כו' אלא ע\"י צמצום והעלם לבוש זה הנק' לבוש מלכו' והוא מ\"ש ה'<sup data-n=\"2515\">57</sup> מלך גיאו' לבש מפני שאין<sup data-n=\"2516\">58</sup> מלך בלא עם ואזי אור מדה זו ברוך ונמשך להיו' נק' מלך העולם כו' וכמ\"ש שם באריכו', ואמנם הנה באמת נא' מלכותך מלכו' כ\"ע כלומר שמדת מל' אין לה שיעור בהתפשטו' כי אור א\"ס שורה גם במדה זו וכמ\"ש לך<sup data-n=\"2517\">59</sup> ה' הממלכה כו' וע\"כ הי' אור מדה זו מתפשט לבחי' החיצונים ג\"כ כי מלכותו בכל משלה כו' אבל ע\"י המצו' הובדל האור שיולבש רק בלבוש מלכות דקדוש' האלקי' וכענין הנ\"ל בפי' יאר פניו אתנו כו' אתנו דוקא, וזהו פי' יפת\"י כמ\"ש ישראל<sup data-n=\"2518\">60</sup> אשר בך אתפא\"ר כלבוש המייפה לגוף כך המצו' הם בחי' לבושי מלכו' לפרקי ואיברי ז\"א שנעשי' ע\"י התורה כנ\"ל בענין כאילו עשאונ\"י בהיו' שעל ידן יש בחי' גילוי אור אלקי מיוחד לקדושה גם בבחי' עולם הפירוד יש מאין שהוא נמשך מבחי' מלכו' והמצו' נק' לבושי' יפים למלכות. והנה כל זה שהמצו' נק' לבוש מלכו' בבחי' היופי כו' היינו בבחי' עולם התיקו\"ן הנק' ברודי\"ם כשנעשה התיקון בבחי' קוי\"ם והוא מצו' &lt;קלג&gt;\nשהם לבושי' לקבלו' אור השפע בבחי' פנימי' דקדוש' ולהבדיל בין הטמא כו' אבל קודם בחי' התיקו\"ן והוא בעולם התוהו שנק' עקודי' נקודי' שהיו האורות מפורדי' זה תחת זה כו' ולא בבחי' קוים כו' אזי עדיין לא הי' בחי' התיקון של לבוש מלכו' הנ\"ל מיוחד לקדוש' האלקי' כי הי' מתלבש גם בלבושי' זרים שלא בבחי' מלכו' דקדוש' אלא בחי' מלכו' אחרים כענין מלך<sup data-n=\"2519\">61</sup> אלקי' על גוי\"ם עכשיו בבחי' גלות השכינה כו'.\n<b>וזהו</b> ואלה<sup data-n=\"2520\">62</sup> המלכים אשר מלכו בארץ אדום לפני מלוך מלך לבני ישראל כו'. פי' בבחי' התוהו לא היו האורו' בבחי' התלבשו' בבחי' פרצוף עדיין שעיקר ענינו הוא בחי' תיקוני הלבושי' ותיקון הכלים אלא כאו\"א מיוחד בפ\"ע כו' ע\"כ לא הי' בחי' מלכו' לבחי' האורו' דתוהו מיוחד בקדוש' האלקי' אלא הי' לבושי' זרים מלבישי' אותו והן בחי' מלכים אחרים דתוהו עד שנבנה הבנין בבחי' פרצו\"ף כו' וזהו ואלה המלכים אשר מלכו בארץ אדום לפני מלוך מלך לבנ\"י פי' בני ישראל הם בחי' נו\"ה דז\"א ובנין הנוק' הנק' מלך לבני ישראל לא הי' נבנה עדיין בבחי' פרצוף אלא מלכי' אחרים משם ב\"ן דתהו כמו וימלוך<sup data-n=\"2521\">63</sup> בלע בן בעור כו' עד מלך השמיני כו', וע\"ד הפשוט מובן ג\"כ אחר שבמלכותא דארעא לא הי' מלך לישראל למטה גם לבחי' ישראל דלעילא שהוא בחי' ת\"ת דז\"א לא נמשך להיו' לו בחי' לבוש מלכו'",[["2515","57","<b>ה' מלך גיאות לבש</b>: תהלים צג, א."],["2516","58","<b>שאין מלך בלא עם</b>: בחיי וישב לח, ל. וראה שער היחוד והאמונה פ\"ז."],["2517","59","<b>לך ה' הממלכה</b>: דברי הימים א כט, יא."],["2518","60","<b>ישראל אשר בך אתפאר</b>: ישעי' מט, ג."],["2519","61","<b>מלך אלקים על גוים</b>: תהלים מז, ט."],["2520","62","<b>ואלה המלכים אשר מלכו</b>: וישלח לו, לא."],["2521","63","<b>וימלוך בלע בן בעור</b>: וישלח לו, לב."]]],[2100490452,"לעילא במלכותא דלעילא לכך מלכו מלכים באדום עד שמלך מלך לבנ\"י למטה כו' וד\"ל.\n<b>ודוגמת</b> ענין זה יש גם עכשיו בזמן הגלות דהנה בזמן הגלות אמרו בזוהר דקדב\"ה<sup data-n=\"2522\">64</sup> אסתלק לעילא לעילא כו' וביאור ענין זה הוא מבו' במ\"א לפי שבחי' הגלות בחי' שינה הוא שמוחין דז\"א מסתלקי' כמו בגלות<sup data-n=\"2523\">65</sup> דמצרים מצר<sup data-n=\"2524\">66</sup> מ\"י שהי' בחי' עיבור דז\"א במעי אימא כו' והיינו דאסתלק קדב\"ה שהוא ז\"א לעילא לעילא בבחי' מוחין דאימא ועוד למעלה ומסיבת עלי' זו אינם מוגבלי' האורו' שלו בכלים ולבושי' בבחי' התיקון כי מפני הרוממו' של המוחין אין כל מה שלמטה מהאצילות תופס מקום כלל כענין שממית<sup data-n=\"2525\">67</sup> בידים תתפש והיא בהיכלי מלך כו' כידוע וכמ\"ש אם<sup data-n=\"2526\">68</sup> צדקת מה תתן לו וכו' וד\"ל וזהו שביציאת מצרים נא' ותעל<sup data-n=\"2527\">69</sup> שוועתם כו' וידע אלקי' שירד אורו' דז\"א בכלים לידע ולהרגיש בצער ולכך בכל גלות ג\"כ כתיב מלך<sup data-n=\"2528\">70</sup> אלקי' על גוים שע' שרים מקבלי' מבחי' מלכו' דקדוש' והוא ענין גלות השכינה מפני שבזמן הגלות אסתלק לעילא כו' והוא למעלה מבחי' הנק' בבחי' מלכו' זרה מתלבשת להיו' מלך על גוים וכיוצא וכענין ואלה המלכי' כו' וכמ\"ש ושפחה<sup data-n=\"2529\">71</sup> כי תירש גבירתה כו' וכמבואר בענין תיקון חצות ואז נא' אלביש<sup data-n=\"2530\">72</sup> שמים קדרות שמים הוא בחי' ז\"א כידוע והלבושי' שה' מלך גיאו' לבש כו' מתלבש במלכי' אחרים וזרים שמשחירי' בקדרות וחשך כו' וד\"ל אבל כל זה לפני מלוך מלך לבנ\"י דהיינו בתוהו וכאשר יש מלך לישראל נתייפו הלבושי' שה' מלך גיאו' לבש כו' וכמ\"ש עוז<sup data-n=\"2531\">73</sup> והדר לבושה כו' וזהו דוקא ע\"י מעשה המצו' בקבלת מלכו' שמים באמרו אלקינו מלך העולם שבזה נעשה בבחי' התיקון וזהו יפתי שמייפה הלבוש מלכו' והיינו &lt;קלד&gt;\nאחר שנק' רעייתי שהוא בנין ז\"א עצמו באורו' וכלים כנ\"ל בפי' כאילו עשאוני כו' וד\"ל.\n<b>וזהו</b> כי<sup data-n=\"2532\">74</sup> הנה הסתיו עבר כו' קומי לך רעייתי יפתי. פי' הסתיו עבר הוא זמן יציא' מצרים שאח\"ז נעשה בחי' התיקון למעלה וכמ\"ש וידע אלקי'<sup data-n=\"2533\">75</sup> שיאר ה' פניו אתנו דוקא ע\"י התורה ומצות שלכך נק' רעייתי יפתי כנ\"ל אמר קומי לך פי' קומי ע\"י העלא' מ\"ן במס\"נ באחד דוקא ולכך הקרי לך דהנה מבואר למעלה דישראל עלה במחשבה בפנימי' אור אבא כו' אך הנה כדי שתוכל לעלות עד שרש מקור",[["2522","64","<b>דקדב\"ה אסתלק לעילא לעילא</b>: ראה זהר ויגש רי, א. בשלח נח, ב. ויקרא כ, ב. אחרי עה, רע\"א."],["2523","65","<b>בגלות מצרים. . עיבור דז\"א במעי אימא</b>: ראה פע\"ח שער חהמ\"צ פ\"א."],["2524","66","<b>מיצר מ\"י</b>: ראה פע\"ח שער חהמ\"מ שכ\"א, פ\"ז. ראה גם תו\"א נח, ב. קג, ד. דרך מצותיך עו, ב."],["2525","67","<b>שממית בידים תתפש</b>: משלי ל, כח."],["2526","68","<b>אם צדקת מה תתן לו</b>: איוב לה, ז."],["2527","69","<b>ותעל שוועתם</b>: שמות ב, כג."],["2528","70","<b>מלך אלקים על גוים</b>: תהלים מז, ט."],["2529","71","<b>ושפחה כי תירש גבירתה</b>: משלי ל, כג."],["2530","72","<b>אלביש שמים קדרות</b>: ישעי' נ, ג."],["2531","73","<b>עוז והדר לבושה</b>: משלי לא, כה."],["2532","74","<b>כי הנה הסתיו עבר</b>: שה\"ש ב, יא."],["2533","75","<b>וידע אלקים</b>: שמות ב, כה."]]],[2100490453,"חוצבה זה א\"א להיו' כ\"א ע\"י מס\"נ דוקא לפי ענין מס\"נ הוא בבחי' יחוד דאו\"א כידוע בענין י'<sup data-n=\"2534\">76</sup> הרוגי מלוכה שהעלו מ\"ן לאו\"א כו' וכמבואר בכונות דפסוק ראשון דק\"ש באמרו ה' אלקינו<sup data-n=\"2535\">77</sup> שהוא בחי' או\"א ע\"י ואהבת<sup data-n=\"2536\">78</sup> בכל נפשך במס\"נ למסור<sup data-n=\"2537\">79</sup> נפשו באחד כי מסירת הנפש עולה למעלה מעלה ממש דהיינו בבחי' עצמו' המאציל והוא בבחי' אור הכתר שעל ידו נעשה יחוד דאו\"א הפנימי' כי כל יחוד א\"א להיו' כ\"א במדרגה שלמעלה מן המתייחדי' והוא באור הכתר כשמאיר בחכמה בבחי' הפנימי' כנ\"ל ושם מגיע התקשרות בחי' מזלא של הנפש מצד שרשה בהעלם אך אין ביכולתה להגיע שם ממש בגילוי אלא בשעת מס\"נ שעולה ונכללת באור הכתר תחלה ומייחד יחוד אור הכתר בחכמה וזהו קומי לכ\"י כ\"ף יו\"ד להאיר הכ\"ף דכתר ביו\"ד דחכמה.\n<b>וזהו</b> שמע<sup data-n=\"2538\">80</sup> ישרא\"ל יש\"ר<sup data-n=\"2539\">81</sup> א\"ל וא\"ל נהירו דאבא שמקבל מש\"ר דכתר נק' ש\"ר כמ\"ש במ\"א ואז נעשה ממילא יחוד הוי'<sup data-n=\"2540\">82</sup> אלקינו או\"א תרין ריעי' כו' ונעשה בנין האורו' בכלים בז\"א דהיינו בתורה והוא מ\"ש אח\"כ והיו<sup data-n=\"2541\">83</sup> הדברי' האלה אשר אנכי פי' אנכי<sup data-n=\"2542\">84</sup> הכ\"ף שבו מורה על הכתר שמלובש באבא ומחיצוניו' דאבא מאיר בתורה שהוא להיו' מוחי' לז\"א במדו' כשר<sup data-n=\"2543\">*84</sup> בפי' רעייתי כו' והוא רק נובלו' חכמה של מעלה ואמנם פנימי' חכמ' של מעלה תלוי ביחוד אור הכתר בחכמ' שאינו אלא ע\"י מס\"נ באחד באמרו תחלה ואהבת את ה' אלקיך פי' אלקיך הוא בחי' מזלא של הנפש שדבוקה בשרשה בכתר שמקבל חכמה משם וכמ\"ש קודש<sup data-n=\"2544\">85</sup> ישראל לה' ראשית תבואתו וכמו שהתבוא' פנימי' הזריעה כו' ולכך נק' ראשית כמו החכמ' כו', הטעם למס\"נ למטה דוקא וכענין שאמר<sup data-n=\"2545\">86</sup> המגיד להב\"י שיזכהו למס\"נ דמשמע שיהי' זכות זה גדול מכל מה שיאריך ימים יותר בתורה ועבודה כו' הענין הוא לפי שבחי' אור מלמטה למעלה נעשה ע\"י מס\"נ מן הגוף דוקא וכענין הידוע במעלת בעלי תשובה כמו ר\"א בן דרודיא שא' רבי עליו שקנה<sup data-n=\"2546\">87</sup> עולמו בשעה א' גם שלא עשה שום מצוה כו' כשיצא' נשמתו נקשרה בשרשא דכולא והוא אור הכתר שמאיר",[["2534","76","<b>הרוגי מלוכה שהעלו מ\"ן לאו\"א</b>: ראה ע\"ח שער הכללים פ\"א. שער מ\"ן ומ\"ד של\"ט ד\"א. פע\"ח שער (יב) נפילת אפים פ\"ה-ו. שער הכוונות שם דרוש ה. שערי אורה בהקדמה."],["2535","77","<b>ה' אלקינו</b>: ואתחנן ו, ד."],["2536","78","<b>ואהבת בכל נפשך</b>: שם ו, ה."],["2537","79","<b>למסור נפשו באחד</b>: ראה זהר (רע\"מ) משפטים קיט, א. צו לג, א. ראה שו\"ת הרשב\"א ח\"ה סנ\"ה. ב'ח טור או\"ח ר\"ס ס\"א. פע\"ח ש' הק\"ש פי\"ב."],["2538","80","<b>שמע ישראל</b>: ואתחנן ו, ד."],["2539","81","<b>ישר אל</b>: ראה ר\"מ בוטריל לספר יצירה פ\"א מ\"א (טו, א) רמ\"ז ר\"פ שמיני."],["2540","82","<b>הוי' אלקינו או\"א תרין ריעין</b>: ואתחנן ו, ד. ראה תקו\"ז תי\"ח (לד, רע\"ב). פע\"ח שער (ז) הק\"ש פ\"ז."],["2541","83","<b>והיו הדברים האלה</b>: ואתחנן ו, ו."],["2542","84","<b>אנכי. . הכתר</b>: ראה זהר (רע\"מ) פינחס רנו, ב."],["2543","*84","<b>כשר</b>: אולי חסר איזה תיבה בגוכתי\"ק."],["2544","85","<b>קודש ישראל לה'</b>: ירמי' ב, ג."],["2545","86","<b>שאמר המגיד להב\"י שיזכהו למס\"נ</b>: מגיד משרים ר\"פ בראשית סד\"ה הלא לך למנדע. פ' אמור ד\"ה אח\"כ א\"ל. פ' בחוקותי ד\"ה ביום הנזכר. ובכ\"מ."],["2546","87","<b>שקנה עולמו בשעה א'</b>: ע\"ז יז, א."]]],[2100490454,"בחכמ' שממנו שרש כל היחודי' דתורה ומצו' וא\"כ מה צריך לתורה ומצו' אחר שנכללי' הכל במס\"נ &lt;קלה&gt;\nצריך טעם למה ע\"י אור חוזר דמס\"נ מגיע לבחי' הארת הכתר וכו' הענין ידוע בע\"ח<sup data-n=\"2547\">88</sup> דבבחי' אור ישר מלמעלה למטה י' הספירו' הן בסדר כח\"ב כו' עד מל' ובבחי' א\"ח נהפוך מלמטה למעלה דהיינו אור הכתר תחלה ואח\"כ חו\"ב עד שבחי' מלכו' למעלה וא\"כ הכתר למטה ומעורר למעלה ג\"כ בחי' אור הכתר כו' (ובזה יובן יותר פי' קומי לך לעצמותך וגם לכי לכף יו\"ד מטעם שהכל ענין א' והוא בבחי' אור הכתר אלא שזה מלמעלה למטה וזה מלמטה למעלה וד\"ל).",[["2547","88","<b>בע\"ח. . אור ישר</b>: ראה ע\"ח שער מ\"ן ומ\"ד פי\"ד. ובפרדס שער ממטה למעלה."]]],[2100490455,"<h3>הראיני את מראיך</h3>\n<b>בעזר\"ה יום שבת פ' צו</b>\n<b>(עוד</b> שם) הראיני<sup data-n=\"2548\">1</sup> את מראייך<sup data-n=\"2549\">2</sup> השמיעני את קולך כי קולך ערב ומראך נאוה כו'. הנה תחלה יש להקדים שיש עשר ספי' בבחי' אור ישר כח\"ב כו' ויש עשר ספי' בבחי' אור חוזר מלמטה למעלה כח\"ב כו' והוא מסיבת בחי' הפרסא שיש בסיום האצי' שע\"י שמסתיים האור מקו וחוט שם אזי בוקעי' האורו' עליוני' ועולי' בבחי' א\"ח ובא\"ח עולה כתר בראשונה וכו' ועפ\"י הקדמה זאת יובן הטעם לירידת<sup data-n=\"2550\">3</sup> הנשמה בגוף חומרי בעוה\"ז שהיא לצורך עלי' כדי לבא למעלה בבחי' א\"ח כו' ע\"י אהבת בכל<sup data-n=\"2551\">4</sup> מאדך שהוא בלי גבול בכלי כו'.\n<b>ותחלה</b> יש לבאר מהו בחי' אור הכתר באור ישר כו' הנה בחי' הכתר<sup data-n=\"2552\">5</sup> הוא בחי' ממוצע בין המאציל לנאצלי' להביא ולחבר אור ושפע המאציל בנאצלי' לפי שאין ערוך כלל וכלל בין עצמו' המאציל לנאצלי' ע\"כ צריך לבחי' ממוצע להביא ולהמשיך אור א\"ס בנאצלי' כו' והטעם הוא לפי שהנאצלי' הן בבחי' ההשתלשלות ולגבי אור עצמו' המאציל לא שייך בחי' השתלשלו' כלל גם להיו' נקרא במדו' וספי' כמו חכים ומבין וכיוצא וכמאמר ולאו<sup data-n=\"2553\">6</sup> מכל אינון מדו' כלל",[["2548","1","<b>הראיני את מראייך</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (כד, ב). מאמר זה הוא המשך לד\"ה דלעיל.\nהנחת המהרי\"ל נדפס לקמן ע' שסט ושם נסמן."],["2549","2","<b>הראיני את מראייך</b>: שה\"ש ב, יד."],["2550","3","<b>לירידת הנשמה בגוף. . לצורך עלי'</b>: ראה ספר המפתחות לאדה\"ז בערכו. וראה לקו\"ש חט\"ו ע' 245."],["2551","4","<b>בכל מאדך. . בלי גבול</b>: ואתחנן ו, ה. ראה אגה\"ק ס\"ז (קכו, א)."],["2552","5","<b>הכתר הוא בחי' ממוצע</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב פ\"א."],["2553","6","<b>ולאו מכל אינון מדות כלל</b>: ראה תיקוני זהר בהקדמה יז, א."]]],[2100490456,"וכמ\"ש רז\"ל אליו<sup data-n=\"2554\">7</sup> ולא למדותיו משא\"כ בי\"ס דאצי' אמרו ז\"ל הדבק<sup data-n=\"2555\">8</sup> במדותיו מה הוא רחום וכו' ומה שנאצל מאתו עשר ספי' הוא רק מבחי' אותיו' שמו בלבד שאין לו ערך למהות ועצם כלל וכמאמר הידוע כתר<sup data-n=\"2556\">9</sup> עליון כו' איהו שם מ\"ה במילוי אלפין דאיהו ארח אצילו' ואיהו שקיא דאילנא כו' פי' עד\"מ שקיו דאילנא שיניקת פנימי' חיותו ע\"י המים כך למעלה גם בחי' פנימי' החיו' והשפע של כל אורו' הנאצלי' שנמשלי' לאילנא כמ\"ש כי<sup data-n=\"2557\">10</sup> האדם עץ השדה האדם דלעילא כו' אינו אלא מבחי' שם בלבד של המאציל והוא שם מ\"ה דהוי' במילוי אלפין ואיהו ארח כל האצי' כו' ושם מ\"ה זה הוא דוקא בבחי' כתר עליון להיותו בחי' ממוצע כנ\"ל ע\"כ בו דוקא שם זה להחיו' חיו' פנימי' לכל הנאצלי' והם ד' אותיו' בכלל י'<sup data-n=\"2558\">11</sup> אצי' ה' בריא' ו' יצירה כו' ומציא' מקור שם זה נמשך מעצמו' המאציל רק בבחי' אותיו' &lt;קלו&gt;\nשם בלבד וכמ\"ש הודו<sup data-n=\"2559\">12</sup> על ארץ פי' הוד שמו בלבד כידוע וד\"ל וא\"כ אצי' ועשי' שוין לפניו אחר ששניהם מאותיו' שמו אלא שזה מן היו\"ד וזה מן ה\"א אחרונ' בדרך כלל וכולם אינם ערוך כלל לגבי עצמותו ומהותו כו' משא\"כ מאצי' לעשי' יש קצת ערך אחר שבא האור והשפע מזה לזה בבחי' ההשתלשלו' ע\"ד דוגמא הנה שכל אנושי נמשך מספי' חכמ' שבמל' דעשי' ובתוכה מלובש חכמ' שבמ' דיצי' ובתוכ' מבחי' חכמ' שבמל' דבריא' ובתוכה מבחי' חכמ' שבמ' דאצי' ובתוכ' מבחי' חכמ' שבז\"א עד חכמ'<sup data-n=\"2560\">13</sup> דאור אבא ראשית הגילוי מן המאציל וא\"כ שרש דשרש מציא' שכל אנושי נמשך מחכמ' דאצי' רק שזה נעשה מקור לזה בבחי' השתלשלו' כו' משא\"כ מאור המאציל להיות חכמה דאצי' אין האור בא רק ע\"י אות יו\"ד משמו שאינו מעצמותו כלל א\"כ אינו בערך ומהו' חכמה כלל וכמאמר אנת<sup data-n=\"2561\">14</sup> חכים ולא בחכמ' ידיע' כו', ואמנם בחי' אור הכתר להיותו בחי' ממוצע יכול להביא אור עצמו' המאציל בנאצלי' שאין לפי ערכם כלל ונק' אור חדש כו' שלא האיר מעולם בנאצלי' כו' והוא ע\"י שם<sup data-n=\"2562\">15</sup> מ\"ה זה שנק' שקיו דאילנא כו' ונק' שם מ\"ה החדש כידוע בע\"ח, והנה אין אור חדש זה בא ומאיר רק ע\"י אתעדל\"ת בהעלא' מ\"ן כיוצא בו דוקא כידוע דכל אתעדל\"ע לא תבא כ\"א באתעדל\"ת שתהא כדוגמתו כו' כי רוח<sup data-n=\"2563\">16</sup> אייתי רוח ואמשיך רוח כדוגמתו ממש כו' וא\"כ צריך שתהא אתעדל\"ת מלמטה להמשיך אור חדש זה בבחי' אור הכתר ג\"כ מבחי' ומדרגה כזאת דהיינו",[["2554","7","<b>אליו ולא למדותיו</b>: ראה פרדס (שער הכוונה) של\"ב, פ\"א."],["2555","8","<b>הדבק במצותיו מה הוא רחום</b>: ספרי עקב עה\"פ (עקב יא, כב). וראה רמב\"ם הל' דעות פ\"א, ה\"ה. סהמ\"צ להרמב\"ם מ\"ע ח. שו\"ע אדה\"ז או\"ח סקנ\"ו, ס\"ג. וראה ג\"כ מכילתא בשלח טו, ב. שבת קלג, ב."],["2556","9","<b>כתר עליון כו' איהו שם מ\"ה</b>: ראה תיקוני זהר בהקדמה יז, א."],["2557","10","<b>כי האדם עץ השדה</b>: שופטים כ, יט."],["2558","11","<b>י' אצי' ה' בריאה ו' יצירה</b>: ראה ע\"ח (שער סדר אצי') ש\"ג, פ\"א. לקו\"ת להאריז\"ל בראשית עה\"פ (ג, כג) וישלחהו ה\"א."],["2559","12","<b>הודו על ארץ</b>: תהלים קמח, יג."],["2560","13","<b>חכמ' דאור אבא ראשית הגילוי</b>: ראה זח\"א לא, ב. ת\"ז רת\"ל."],["2561","14","<b>אנת חכים ולא בחכמה ידיעא</b>: ראה ת\"ז בהקדמה (יז, ב)."],["2562","15","<b>שם מ\"ה. . שנק' שקיו דאילנא</b>: ראה תקו\"ז בהקדמה (יז, א)."],["2563","16","<b>רוח אייתי רוח</b>: ראה זהר תרומה קסב, ריש ע\"ב."]]],[2100490457,"שתהא ההעלא' מ\"ן בחי' אור חדש שלא יכילנו הכלי ולא יגבילנו כלל והוא בחי' אור הכתר מלמטה למעלה ע\"י אהבת בכל מאדך שהוא אור שאינו מוגבל גם בשכל ולב כו' ונק' כתר בבחי' מקיף אלא שעולה בדרך עלי' מלמטה מפני שלא יכילנו הכלי וכך מעורר למעלה אור העצמו' דא\"ס להיו' בבחי' הכתר בבחי' אור ישר מלמעלה למטה בי\"ס דאצי' וכמאמר אור<sup data-n=\"2564\">17</sup> חדש על ציון תאיר כו' שלא יכילנו הכלים כו' והוא בחי' מאד העליון וכמ\"ש ישכיל<sup data-n=\"2565\">18</sup> עבדי כו' וגבה מאד כו' אבל העלא' מ\"ן שמתיישבת באור וכלי עפ\"י ההשתלשלו' לא תוכל לעורר אתעדל\"ע כ\"א באותו האופן ג\"כ והוא שיומשך האור בכלי מן המאציל בנאצלי' אבל לא בחי' אור חדש שלמעלה מבחי' אור וכלי כו' וד\"ל.\n<b>ובכל</b> זה יובן הטעם שהי' ירידת נשמה לגוף לצורך עלי' כנ\"ל. דהנה ידוע ההפרש בין נשמו' למלאכי' שהמלאכי'<sup data-n=\"2566\">19</sup> נק' עומדים כמ\"ש ונתתי<sup data-n=\"2567\">20</sup> לך מהלכים בין העומדי' האלה כו' דהיינו שעומדי' מוימ\"ב עפ\"י סדר ההשתלשלו' דמאציל בנאצלי' בבחי' קו המדה באורו' וכלים באצי' כך נמדד שיעור השתלשלו' דאצי' בנבראי' כמו המלאכי' שבדבר ה' ורוח פיו כו' ואין אתעדל\"ת שלהם רק בבחי' אור המוגבל בכלי וכך המשכת מ\"ד שעל ידם באצי' הוא ג\"כ באור שכבר נמדד בכלי כנ\"ל ועיקר הטעם הוא מה שאין להם דבר מסתיר ומונע אופן העבודה שלהם כפי הבריא' ע\"כ אין להם בחי' אור חוזר לצאת מגבול הכלי כי עד\"מ מכיסוי הזכוכי' של המראה האור חוזר לאחוריו מחמת ההסתר כו' אבל בנשמו' שמלובשי' בגופים גשמיים &lt;קלז&gt;\nשמסתיר האור אלקי ומונע אזי בהכרח שיחזור האור בבחי' אור חוזר למעלה דהיינו למעלה מהגבלת הכלי של האור כענין אהבת בכל מאדך אחר שאין מניחי' לאור להתפשט עוד למטה בהכרח שיחזור לאחור ואמנם חזרה זו בכח גדול הוא כנראה לעין ממרוצת המים ע\"י דף המסתיר לאחוריו בכח גדול וכן בהכאת אבן בכותל וכיוצא והוא ענין נקודת הלב שנמצא באדם מצד שרואה שמסתיר עליו חשכי מסך גופו הבהמי כו' והוא הנק' עומקא דלבא כמ\"ש ממעמקי'<sup data-n=\"2568\">21</sup> קראתיך הוי' מעומקא דלבא שאינו נגבל בלב ולא במוח כו' והוא כמו בחי' אור הכתר המקיף על הלב אלא שהוא בא בבחי' א\"ח מלמטה למעלה מצד שלא יכילנו הכלי כנ\"ל ואזי ע\"י בחי' כתר זה באור החוזר מעורר למעלה אתעדל\"ע בחי' כתר העליון שיאיר בנאצלי' ג\"כ בבחי' מקיף שלא מערך הכלי והוא הנק' אור חדש כנ\"ל וזהו קראתיך הוי' שנמשך שם הוי' מחדש מבחי' מ\"ה דבעצמו' המאציל דאיהו שקיו דאילנא כנ\"ל ואין זה אלא ע\"י ממעמקי' דוקא מטעם הנ\"ל וד\"ל, וזהו ענין הירידה של הנשמה לבא לכלל הסתר כדי שתעלה בבחי' אור חוזר בבחי' הכתר כנ\"ל וזהו דרך פרט בנשמ' פרטית וכיוצא בזה מובן בכללו' נ\"י שהיא בחי' מל' דאצי' למעלה",[["2564","17","<b>אור חדש על ציון תאיר</b>: נוסח (אשכנז) ברכת ק\"ש שחרית."],["2565","18","<b>ישכיל עבדי</b>: ישעי' נב, יג."],["2566","19","<b>שהמלאכים נק' עומדים</b>: ראה תו\"א וישב ל, סע\"א. לקו\"ת בחוקותי מה, א. שלח לח, ד. סה\"מ תקס\"ד ע' קעז."],["2567","20","<b>ונתתי לך מהלכים בין העומדים</b>: זכרי' ג, ז."],["2568","21","<b>ממעמקים קראתיך. . מעומקא דלבא</b>: תהלים קל, א. ראה אגה\"ק פ\"ד. לקו\"ת אחרי כח, ב. במדבר ו, ג. וראה זהר ויקרא ע, א."]]],[2100490458,"כידוע שע\"י בחי' הפרסא דוקא להיותה בחי' מסתיר ומעכב שאין אור האצי' מתפשט עוד למטה נעשה בחי' א\"ח באורו' דאצי' שמסתיימי' במל' ועולי' למעלה בבחי' הכתר ונעשה בחי' כתר למטה ומעורר בחי' כתר עליון לחבר ולהמשיך אור חדש בנאצלי' כו' וד\"ל.\n<b>וזהו</b> הראיני את מראייך כו' כלומר הטעם שנק' רעייתי לחבר אור א\"ס בחכמ' ושאר הספי' כנ\"ל משום שנק' מראה בבחי' אור חוזר במס\"נ מצד ההסתר דוקא כמשל מראה כנ\"ל, ומה שאמר מראייך ב' מראו' מבואר למעלה שהוא בחי' תשובה עילא' ותשובה תתא' ושרש ענינם למעלה הכל הוא מסיבת הפרסא דלכך נעשה בחי' אור חוזר וד\"ל.\n<b>השמיעני</b> את קולך כי קולך ערב כו'. הנה מבואר בזוהר<sup data-n=\"2569\">22</sup> שהוא קלא דאוריית' ומטעם המבואר למעלה בפי' רעייתי שמפרנסי' לאביהם שבשמים כו' דהיינו שממשיכי' אור א\"ס בחכמה שתתלבש בתורה וכמ\"ש ותורה שם בישראל כו' וזהו השמיעני את קולך כו', אך מה שאמר כי קולך ערב דהיינו בבחי' המתיקו' והעריבו' דוקא שהוא בחי' התענוג הנה זה יובן בהקדים מאמר אבא בנימין במה שהשתדל תמיד ואמר שתהא<sup data-n=\"2570\">23</sup> תפלתי סמוכה למטתי כו' ומבואר הכונה שלא ילמוד קודם תפלה אלא מיד בקומו ממטתו יתפלל ואח\"כ ילמוד וידוע מ\"ש בתוס' דלא ידע ר\"י מה איסור יש בדבר אם ילמוד קודם התפלה אחר שלא הגיע זמנה עדיין כו'.\n<b>אך</b> הענין הוא דכתיב ואהי'<sup data-n=\"2571\">24</sup> אצלו אמון כו' שעשועי' יום יום וכן כתיב אני<sup data-n=\"2572\">25</sup> תורתך שעשעתי ולכאורה ב' פסוקי' הללו סתרי אהדדי דאני תורתך שעשעתי משמעו ענין פועל יוצא דהיינו שאני ממשיך ופועל להיו' בחי' שעשועי' ותענוג עליון בתורה וזהו תורתך שעשעתי כלומר שעשעתי אותה כו' ובאמרו ואהי' אצלו כו' שעשועי' יום יום משמעו דהוא משתעשע ומקבל &lt;קלח&gt;\nתענוג מן התורה כו' וכן לבני אדם נא' ג\"כ בתורה ושעשועי<sup data-n=\"2573\">26</sup> את בני אדם כו', אמנם ביאור הענין דשניהם אמת דהנה מבואר למעלה דבחי' אור הכתר הוא שמאיר בחכמה וידוע דבחי' הכתר הוא בחי' עונג העליון אך שעשועי' ותענוגי' שבכתר הם בבחי' ההעלם של עצמו' המאציל ולא נגלה בבחי' גילוי עדיין וזהו כי<sup data-n=\"2574\">27</sup> עמך מקור חיים פי' מקור כל התענוגי' כו' כידוע אבל הארת עונג זה בחכמ' אחר שהוא מאין ליש כמ\"ש והחכמה מאין תמצא ע\"כ בחכמה העונג הזה קצת בבחי' גילוי ולכך נק' החכמה עדן וכמ\"ש ונהר<sup data-n=\"2575\">28</sup> יוצא מעדן כו' וזהו דאמרה התורה ששרשה מבחי' פנימי' אור",[["2569","22","<b>בזוהר שהוא קלא דאורייתא</b>: ראה רע\"מ רכט, ב."],["2570","23","<b>שתהא תפלתי סמוכה למטתי</b>: ברכות ה, סע\"א. וראה לקו\"ת ברכה צו, ב."],["2571","24","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["2572","25","<b>אני תורתך שעשעתי</b>: תהלים קיט, ע."],["2573","26","<b>ושעשועי את בני אדם</b>: משלי ח, לא."],["2574","27","<b>כי עמך מקור חיים</b>: תהלים לו, י."],["2575","28","<b>ונהר יוצא מעדן</b>: בראשית ב, י."]]],[2100490459,"אבא ואהי' אצלו כו' שעשועי יום יום היינו בחי' או\"א שנק' יום יום שכבר העונג העליון דכתר בהם בגילוי ומהם נמשך קבלת העונג לז\"א במדו' כשהקדב\"ה<sup data-n=\"2576\">29</sup> שהוא ז\"א יושב ועוסק בתורה שמקבל שעשועי' דאו\"א כו' אבל מה שאמר אני תורתך שעשעתי בפועל יוצא היינו בחי' הכתר שהוא מקור כל השעשועי' ונק' שעשועי<sup data-n=\"2577\">30</sup> המלך בעצמותו כמ\"ש במ\"א וממנו נמשך עונג להיו' מציא' עונג גלוי באור אבא ואוריי' מחכמ' נפק' ע\"כ אמר תורתך שעשעתי ומ\"ש אני הוא אין דכתר כידוע וד\"ל.\n<b>וזהו</b><sup data-n=\"2578\">31</sup> ההפרש בין הלימוד שקודם התפלה ללימוד שאחר התפלה דהנה מבואר למעלה דע\"י מס\"נ באחד מצד ההסתר שיש בתפלה בא בחי' אור חוזר בבחי' הכתר ומעורר למעלה בחי' אור חדש בכתר עליון כו' וא\"כ מזה האור החדש יומשך ג\"כ ממקור השעשועי' שבעצמו' אור עונג חדש בחכמה שבתורה ולהיו' תורתך שעשעתי בשעשועי' חדשי' כו' משא\"כ בלימוד התורה שקודם התפלה שלא הי' עדיין אתעדל\"ת להיו' אתעדל\"ע באור הכתר להמשיך אור חדש כו' אין כאן בחי' עונג חדש בחכמה שבתורה אלא ממה שכבר נאצל בה מראשית ההשתלשלו' או מבחי' הרשימו שנשארה בה מיום דאתמול ע\"י אתעדל\"ת של יום אתמול בתפלה ותשובה וכיוצא בה שנתעורר אתדל\"ע בכתר ביום אתמול כו' או ע\"י אהבת בכל מאדך שבקריא' ק\"ש דאתמול אבל לא מיום דעכשיו ע\"כ ביקש אבא בנימין שתהא תפלתי בבחי' סמוכה למטתי ויקדים להיו' בחי' א\"ח דתפלה ואזי יהי' תורתו מקבל שעשועי' חדשי' ממקור כל התענוגי' אחר שיתפלל וילמוד מיד אחר התפלה כו' וד\"ל, וזהו מ\"ש כי קולך בתורה ער\"ב בבחי' עריבו' התענוג והשעשועי' המקוריי' שבעצמות המאציל מצד שהראני את מראייך תחלה בבחי' א\"ח בתפלה ואזי דוקא השמיעני את קולך בתורה כי קולך ערב כו' וד\"ל.\n<b>ומראך</b> נאוה. הנה מבואר שם שזה קאי למעשה המצות שבשבילם נק' יפתי כנ\"ל הטעם ועתה אחר שאמר הראיני את מראייך בבחי' א\"ח כנ\"ל אמר ומרא\"ך נאו\"ה שהוא ענין יפוי והידור יותר מופלג כמשמעו' לשון נאוה לשון נפעל דהיינו על היפוי הראשון שנתייפה יותר וביאור הדברים הנה דרך כלל יובן זה גם בדרך הפשוט דהנה במצות מעשיות יש ב' דברים הא' גופו<sup data-n=\"2579\">32</sup> של מעשה המצוה לעשו' סוכה וליטול אתרוג בפ\"מ וכיוצא שזה יש בכל ישראל גם בקל שבקלים כמארז\"ל דאפי' פושעי<sup data-n=\"2580\">33</sup> ישראל מלאים מצות &lt;קלט&gt;\nכרמון כו' והיינו גוף מעשה המצות אך בכונת",[["2576","29","<b>כשהקב\"ה. . יושב ועוסק בתורה</b>: ראה ע\"ז ג, א."],["2577","30","<b>שעשועי המלך בעצמותו</b>: ראה עמק המלך שער א. לקו\"ת שה\"ש כז, סע\"א."],["2578","31","<b>וזהו ההפרש בין הלימוד שקודם התפלה</b>: ראה ג\"כ לקו\"ת ברכה צו, ב."],["2579","32","<b>גופו של מעשה. . סוכה וליטול אתרוג</b>: בלקו\"ת שה\"ש כ, ד מציין (ועמ\"ש ע\"פ כבס ביין לבושו וסד\"ה ועשית בגדי קודש גבי ג' בחי' ומדריגות שיש בעשיית הלבושים כו' וע' בפרדס ש\"ח פ\"א)."],["2580","33","<b>פושעי ישראל מלאים מצות כרמון</b>: חגיגה כז, א."]]],[2100490460,"של מעשה המצות אין א' דומה לחבירו וכל חד לפום שיעורא דילי' באוי\"ר והשגתו כך יכוין בנקודה שבלב באופן ההמשכה או באופן ההעלא' באותה מעשה המצוה ואפי' במצוה א' שיעשו שני בנ\"א אין ההשפעה עליונה שנעשה ע\"י מעשיהם שוה והוא לפי אופן שינוי כונה שלהם שזה מכוין לכונה פנימי' יותר ימשיך למעלה מבחי' פנימי' האורו' וזה אינו מכוין כלום אינו ממשיך כ\"א מדרגו' החיצוניו' דעשי' וכיוצא וע\"ד דוגמא הנה אמרו שנים<sup data-n=\"2581\">34</sup> שצלאו פסחיהם כו' הרי אע\"פ שפסח אחד להם ומצוה א' ביד שניהם בהשתוות מעשה ואין ההמשכה<sup data-n=\"2582\">*34</sup> ועד\"ז יובן ההפרש בדרך כלל בין צדיקי' מקיימי מצות לרשעי' מקיימי מצו' שמצד הכונה רחוקי' זה מזה בערך אע\"פ שבמעשה מעשה א' לשניהם כו' וא\"כ יובן בענין ההפרש בין בחי' היופי שמצד מעשה המצו' בכלל שנק' יפתי מטעם הנ\"ל שנעשה בחי' לבוש מלכו' למעלה עי\"ז ובין יופי והידור היותר נאה והוא תכלית שלימו' הכחות שבלב שבמעשה המצות מן הצדיקי' וכיוצא בהם בכל חד לפום שיעורא דילי' כו' והוא מ\"ש ומראך נאוה וד\"ל.\n<b>ושרש</b> ענין זה ע\"ד הקבלה וגם הטעם שתלוי זה במה שקדם ואמר הראיני את מראייך בבחי' א\"ח כו' הנה תחלה יש להקדים כלל א' בדרכי הקבלה הידוע בפרדס וע\"ח שלעולם בחי' הכתר ובחי' התפארת ענין א'<sup data-n=\"2583\">35</sup> הם ממש והמופת שהרי ידוע בפרדס שבחי' הת\"ת הוא בחי' הקו האמצעי וגם הרי הכתר<sup data-n=\"2584\">36</sup> לעולם הוא בחי' קו אמצעי שהרי ידוע שהוא בחי' ממוצע בין המאציל לנאצלי' כו' וגם ידוע שלעולם בחי' כתר שבתחתון נעשה מבחי' ת\"ת שבעליון כמו בחי' ת\"ת<sup data-n=\"2585\">37</sup> דאימא נעשה כתר לז\"א ובחי' ת\"ת דז\"א משליש התחתון שבו נעשה כתר לנוק' כו' א\"כ מאחר שמבחי' הת\"ת נעשה כתר בהכרח לומר שענין א' הם שאל\"כ מהיכן הי' מציא' התהוו' הכתר דוקא מבחי' ת\"ת ולא ממדה אחרת זולתה אך הענין הוא לפי ששניהם ענין א' הם ממש דהיינו ששניהם בחי' ממוצע בכל מקום שהם והוא שיש בכחם לחבר ולהביא מעליון לתחתון או מדבר להיפכו והוא נק' כח ההתחברו' או כח המחבר וגם נק' בלשון קו אמצעי והוא הנק' ממוצע ולהיו' כי יש כח האמצעי המחבר הזה בכתר וגם בת\"ת ולא בזולתם ע\"כ יבא בחי' הסתעפות מזה לזה אחר ששניהם ענין א' ולכך בחי' כתר של התחתון נעשה מבחי' ת\"ת שבעליון כמו בחי' ת\"ת דאימא שנעשה כתר לז\"א.\n<b>והענין</b> הוא שבחי' הכתר הזה בז\"א הוא בחי' כח הנק' ממוצע להביא מאור עליון דאימא שהוא השכל לאור התחתון של המדו' הנק' ז\"א והוא אמצעי שיש",[["2581","34","<b>שנים שצלאו פסחיהם</b>: נזיר כג, א."],["2582","*34","<b>ההמשכה</b>: אולי חסר איזה תיבות בגוכתי\"ק."],["2583","35","<b>בחי' הכתר ובחי' התפארת ענין א'</b>: ראה אוה\"ת שמות כרך ז' ע' ב'תשמט ואילך."],["2584","36","<b>הכתר. . ממוצע</b>: נסמן לעיל בראש המאמר."],["2585","37","<b>ת\"ת דאימא. . משליש התחתון. . כתר לנוק'</b>: בלקו\"ת שה\"ש שם [צ\"ע בע\"ח שער עשרים (בדפוס שקלאוו תק\"ס, לפנינו הוא שכ\"א) פ\"ב ב' שלישים תחתונים כו', אמנם מן המוח כו' רק חצי שליש]."]]],[2100490461,"בו התחברו' של כח העליון עם כח תחתון כו' ונעשה כח התחברו' זאת למטה מבחי' ת\"ת פי' כי בהכרח הוא שיהי' באור עליון דאימא בחי' כח אמצעי לחברו ולהביאו למטה והוא בחי' הת\"ת שבו דוקא כי הנה נצח והוד נק' משפיעי' שכבר נשפע עצמו' ההשפעה בהם כענין כליו' שמבשלו' הזרע אבל כח המביא ומוריד זאת ההשפעה לנצח והוד הוא בחי' ת\"ת ונקרא בשם המכריע כלומר &lt;קמ&gt;\nשמכריע את המדו' חו\"ג שיהו נוטין להשפיע ולהתחבר ולהאיר אור למטה כי מצד עצם המדו' חו\"ג אינם בגדר כח ירידה למטה אלא הם נשארים בעצם כמו שהם כמו מדת החסד חסד זה היה נשאר בעצם ולא הי' מאיר לזולתו וכן בהיפוך מדת הדין כו' וענין נטיית החסד והטוב לזולתו נק' הכרעה כמו הכרעת משקל שמטהו למטה כידוע וכך הטיית המדה להאיר למטה נק' הכרעה והוא ע\"י מדת הת\"ת שנק' מכריע כלומר מטה כמ\"ש מטה כלפי חסד וע\"ד הנראה לעין כשאדם מעיין בשכלו באיזה דבר אם לזכות או לחוב ועדיין הדבר שקול הרי ב' המדו' חו\"ג שולטי' בו באותה שעה ואינן מאירי' עדיין למטה עד שיבא הכח המכריע והוא המטה אותן אם לחוב אם לזכו' יהי' איך שיהי' יפסוק הדבר שיבא ויאיר למטה כו' וד\"ל ונמצא בחי' ת\"ת זה המכריע ומטה ההשפעה בנצח והוד יש בו כח המחבר שבכחו לחבר ולהביא אור בלבד והכל עדיין בעצם המשפיע אבל בחי' כתר שנעשה לתחתון הוא הנק' אמצעי ממש שיש בו מכח המשפיע ומכח המקבל יחד אלא שזה בא מצד השתלשלו' דהיינו מבחי' כח המחבר שבמשפיע נעשה כח המחבר למטה לקשר עליון בתחתון תמיד והוא בחי' הכתר ולא נעשה רק מבחי' שליש התחתון שבת\"ת דעליון וב\"ש העליוני' נשארי' בעליון כו' וכמ\"ש במ\"א וד\"ל ועד\"ז יובן בכל פרטי השתלשלו' הפרצופי' העליוני' כמו שמבחי' ת\"ת דא\"א כתר לאו\"א כו' עד שכתר<sup data-n=\"2586\">38</sup> דנוק' שנעש' מת\"ת ז\"א הוא היותר אחרון וכתר דא\"א שנעש' מת\"ת דא\"ק וכיוצא וכידוע שמלביש עד טיבורו כו' הוא היותר עליון וכולן באין מזה לזה בהשתלשלו' עד בחי' כתר דנוק' וד\"ל.\n<b>ואחר</b> שנתבאר שבחי' הת\"ת ובחי' הכתר ענין א' הם יובן גם כאן במה שאמר ומרא\"ך נאו\"ה דר\"ל בחי' כת\"ר דנוק' שנק' נאו\"ה על עוצם הפלגת היופי וההידור שבכת\"ר מפני שהוא נעשה מבחי' אור אשר חוזר מלמטה למעלה שע\"ס דא\"ח בחי' הכתר קודם לבא כנ\"ל והוא ענין הקישוטי' שבכתר דנוק' כו' וע\"ז אמר ומרא\"ך נאוה שהוא יותר נאה גם מגופו של כתר שנעש' מת\"ת דז\"א עפ\"י סדר ההשתלשלו' כנ\"ל והטעם הוא מובן עפ\"י הנ\"ל דמפני העלא' מ\"ן מכתר זה שבבחי' א\"ח מעורר למעלה בחי' אור חדש גם בכתר הכללי היותר ראשון שמחבר עצמו' אור א\"ס באבי\"ע ומשם יורד אור חדש זה ומאיר בהשתלשלו' מכתר לכתר ע\"י אמצעי' הת\"ת שבכל פרצוף וכנ\"ל עד כת\"ר דנוק' וא\"כ אור זה החדש שבא עתה מת\"ת דז\"א בכתר דנוק' ע\"י סיבת בחי' א\"ח דמרא\"ה נאה הוא הרבה גם מכתר דז\"א ומכתר דאו\"א כי ממקום הגבוה מכל הכתרים הוא בא ומכ\"ש מבחי' הכתר שקיבלה הנוק' כבר מת\"ת דז\"א כו' וזהו ומרא\"ך דוקא נאוה לשון נפעל שנתייפה ביפוי שאין",[["2586","38","<b>שכתר דנוק'. . הוא היותר עליון</b>: בלקו\"ת שם: ועיין בע\"ח שער מיעוט הירח פרק א' ב' שיש בזה כמה מדריגות זו למעלה מזו עד שמקבלת כתרה ג\"כ מת\"ת דאימא."]]],[2100490462,"כמוהו עפ\"י סדר השתלשלו' הכתרי' מטעם הארת אור חדש הנ\"ל בכתר הראשון שאינו אלא בסיבת הארת הכתר למטה בבחי' א\"ח כנ\"ל והוא ענין אהבת בכל מאדך בלי גבול כנ\"ל (וזהו מ\"ש ביום<sup data-n=\"2587\">39</sup> ההוא יצאו מים חיים כו' וכן וערבה<sup data-n=\"2588\">40</sup> לה' מנחת יהוד' כימי עולם כו') והיינו שאמרו ז\"ל יפה<sup data-n=\"2589\">41</sup> שעה א' בתשובה ומע\"ט פי' דוקא ע\"י התשובה שהיא בחי' א\"ח אזי המצו' נק' טובים כלומר מאירים וכמ\"ש וירא<sup data-n=\"2590\">42</sup> אלקי' את האור כי טוב וכמו עד\"מ האבנים &lt;קמא&gt;\nטובו' שמאירי' כך כונת המצו' בבחי' התשובה מעומקא דלבא שקדמה למעשה הוא המאיר אור החדש הנ\"ל מלמעלה למטה וכמ\"ש אור חדש על ציון תאיר כו' והוא הקישוטי' שבכתר כו' וזה עולה ע\"ד הנ\"ל ג\"כ בהפרש שבין מעשה המצוה עצמי לכונת המצוה מפני שכונת המצוה דוקא עושה אותה להיו' נק' מעשה טוב\"ה ומאיר\"ה (והיינו ענין המאמר בקישוטי'<sup data-n=\"2591\">43</sup> אזלא מאנין ולבושי' דמצו' כו' וכמ\"ש במ\"א). וזהו שאמר ומראך נאוה להורות על יפוי היותר גדול ממה שאמר תחלה יפת\"י דפי' יפת\"י הוא מפני שבחי' ת\"ת דז\"א הוא שנעש' כתר לנוק' עפ\"י סדר ההשתלשלו' אבל מרא\"ך נאו\"ה מייפה גם לבחי' ת\"ת דז\"א בכתר חדש כנ\"ל וזהו ישראל<sup data-n=\"2592\">44</sup> אשר בך אתפאר וכן זה<sup data-n=\"2593\">45</sup> אלי הוא בחי' ת\"ת ואנוהו יותר כו' כמ\"ש ומרא\"ך נאו\"ה כו' וד\"ל.\n<b>ואחר</b> כל הנ\"ל יובן סדר הפסוקי' יונתי בחגוי הסלע בסתר המדרגה כו' ע\"כ קומי לך רעייתי יפתי כו' ואח\"כ השמיעני את קולך כו'. דהנה מבואר למעלה דמסיבת בחי' הפרסא שבין אצי' לבי\"ע הוא שנעשה בחי' א\"ח כו' אמנם אין זה מצד סיבת הפרסא בלבד אלא דוקא מטעם שבחי' המל' היא בוקעת הפרסא ומתצמצמת ויורדת בבי\"ע ונעשית שם כמו נקודה א' בלבד וכאשר עולה מן הצמצום וההסתר בבחי' עלי' הע\"ס שלה עולי' בבחי' א\"ח ואז בחי' כתר קודם לבא כו'.\n<b>ותחלה</b> יש להבין ביאור ענין מה שנעשי' כנקוד' א' בבי\"ע כו' דהנה ידוע שבחי' מל' דאצי' היא אחת ממדותיו דא\"ס והרי יש בה בחי' א\"ס ממש דהא איהו וחיוהי וגרמוהי חד כו' והגם שנק' סופא דכל דרגין היינו לגבי סדר ההשתלשלו' אבל באצי' עצמו היא בבחי' א\"ס וזהו מלכותך<sup data-n=\"2594\">46</sup> מלכו' כ\"ע ור\"ל בלתי מוגבלת כו' וכנ\"ל בפי' לך ה' הממלכה כו' וא\"כ איך אפשר שיקבלו הנבראי' בעלי גבול האור והשפע מבחי' מל' דאצי' כמו להיו' נהנין מזיו השכינה בג\"ע העליון אחר שהנאה זאת היא באה בהשגה ועונג גבולי לפי ערך המקבלי' וזיו השכינה עצמה בלתי ב\"ג כו' אלא הענין ידוע מפני שמתצמצמת עצמה בתכלית בירידתה לעולם הבריא' ומעלמת כל בחי' עצמותה לגמרי עד\"מ הנפש כשמעלמת כוחותיה בעצמותה לבלתי יתפשט כח ממנה כלל כו' ולא נשאר בה רק בחי' האחרונה שבה והיא נק' נקודה א'",[["2587","39","<b>ביום ההוא יצאו מים חיים</b>: זכרי' יד, ח."],["2588","40","<b>וערבה לה' מנחת יהודה</b>: מלאכי ג, ד."],["2589","41","<b>יפה שעה א' בתשובה</b>: אבות פ\"ד, מי\"ז."],["2590","42","<b>וירא אלקים את האור</b>: בראשית א, ד."],["2591","43","<b>בקישוטין אזלא</b>: זמירות ליל שבת ”אזמר בשבחין\"."],["2592","44","<b>ישראל אשר בך אתפאר</b>: ישעי' מט, ג."],["2593","45","<b>זה אלי</b>: בשלח טו, ב."],["2594","46","<b>מלכותך מלכות כ\"ע</b>: תהלים קמה, יג."]]],[2100490463,"כמבואר במ\"א בענין הא לחמא עניא כו' שהיא בחי' נקוד' תחת יסוד כו' ומכ\"ש בגלות השכינה בע' שרים מתצמצמת עוד יותר ובזה יש ריבוא רבבו' ירידו' כמו בלילה שמסתתרת עוד למטה והוא בהיכלו' דנוגה לברר ברורי' דרפ\"ח וכמ\"ש ותקם<sup data-n=\"2595\">47</sup> בעוד לילה ותתן טרף כו' וכמ\"ש במ\"א ובכל שחר היא קמה מעט מעט מן הצמצומי' הרבים האלה ועולה מעט מעט להיו' בבחי' התפשטות קצת עד שבשעת העמידה דש\"ע בתפלה חזרה לבנינה השלם בבחי' האצי' כו' כמבואר בפרע\"ח וזהו יונת\"י שהיא מל' דאצי' שנמשלה ליונה היא בחגוי הסלע בבחי' צמצום כנקוד' א' בלתי התפשטו' כלל וכלל כמשל היונה הטמונה בנקיקי הסלעי' שגדפיה מצומצמי' בדוחק כו' וכך למטה גם אוי\"ר אין לכנ\"י כל היום בעסקם במו\"מ מפני מחשך חומריו' עוה\"ז המסתיר ומצמצם וה\"ז כחגוי הסלע ועוד יותר נשפלים בדברי' &lt;קמב&gt;\nהאסורי' שבהיכלו' דנוג' כגזל וכיוצא והוא נק' סתר המדרגה וגם למעלה הוא כמו ירידת המל' להיכלו' דנוגה בלילה כו' וד\"ל.\n<b>אמנם</b> מסיבת הדוחק הזה בהסתר העצום כשמסתתרת בבי\"ע ואז נק' הסת\"ר<sup data-n=\"2596\">48</sup> אסתיר פני כו' בהכרח שתעלה משם בבחי' א\"ח למעלה באצי' ובוקעת הפרסא ועולה כו' אחר שאין אורה יכול להתפשט עוד ומסיבת תגבורת התשוקה לעלו' תקדום לעלות בבחי' הכתר שבה תחלה כו' ואזי העלא' מ\"ן שלה מעורר בכתר עליון שיתחבר בנאצלים ובזה נעשה התורה בעולם האצי' והמצו' בלבוש מלכו' שזהו קומי לך רעייתי יפתי כנ\"ל אך זהו עדיין קודם התפלה אלא רק מסיבת ירידה עצומה דאתמול כשתקום בחצו' בקימה ועלי' עד עלות השחר שיהי' האופן בבחי' א\"ח מטעם הנ\"ל ע\"כ תקרא רעיית\"י ויפת\"י אמנם שלימו' עלייתה עד שתמשיך אור חדש דמאציל בתורה ומצו' והוא שיהי' קול\"ך ער\"ב ומרא\"ך נאו\"ה כנ\"ל זהו דוקא מק\"ש ואילך עד אחר ש\"ע והוא באמרו בכל<sup data-n=\"2597\">49</sup> מאדך שמעורר בזה בחי' מאד העליון כו' וכנ\"ל ואח\"כ השמיעני את קולך שהוא קול דאוריי' אחר התפלה דוקא כמו שאמר אבא בנימין וכנ\"ל אזי הקול ערב להיו' אני תורתך שעשעתי וכן במצות להיו' יפוי יותר גם בת\"ת העליון וכמ\"ש ומראך נאוה כו' וכל זה ע\"י שהראני את מראייך בבחי' א\"ח מצד ההסתר בחגוי הסלע כל היום וכל הלילה כי אחר הלימוד שאחר התפלה כשעוסק האדם בפרנסה וכמ\"ש ואספת<sup data-n=\"2598\">50</sup> דגנך חוזר ומסתתר וכו' וחוזר ועולה בבקר וכן חוזר חלילה מירידה לעלי' ומעלי' לירידה כי כן הוסד הדבר שלא יהי' עלי' אלא אחר ירידה כו' וכך למעלה בבחי' אדם העליון שעל הכסא הנה כתיב חסד<sup data-n=\"2599\">51</sup> אל כל היום שיורד חסדו למטה בבחי' ו' יומין דחול וג'<sup data-n=\"2600\">52</sup> שעו' הראשונו' יושב הקדב\"ה ועוסק בתורה כו' ותחלה מתפלל שנא' ואני<sup data-n=\"2601\">53</sup> תפלה כו' ובלילה הוא בחי' שינה כו' ובבקר יאיר אורו כמ\"ש יומם<sup data-n=\"2602\">54</sup> יצוה ה' חסדו כו' וד\"ל. ובכל הנ\"ל מובן עיקר הטעם למה שירדה הנשמה בגוף כדי",[["2595","47","<b>ותקם בעוד לילה</b>: משלי לא, טו."],["2596","48","<b>הסתר אסתיר פני</b>: לשון הפסוק וילך לא, יח."],["2597","49","<b>בכל מאדך</b>: ואתחנן ו, ה."],["2598","50","<b>ואספת דגנך</b>: ואתחנן יא, יד."],["2599","51","<b>חסד אל כל היום</b>: תהלים נב, ג."],["2600","52","<b>וג' שעות הראשונות</b>: ראה ע\"ז ג, ב."],["2601","53","<b>ואני תפלה</b>: תהלים קט, ד."],["2602","54","<b>יומם יצוה ה' חסדו</b>: תהלים מב, ט."]]],[2100490464,"שיהי' ע\"י הירידה בחי' א\"ח מצד ההסתר דוקא ואזי יהי' בכח' להמשיך אור שם מ\"ה החדש מעצמו' המאציל בכתר העליון וזהו שביקש אבא בנימין שתהא תפלתי בבחי' א\"ח סמוכה למטתי דהיינו שיהי' בא מצד ההסתר של בחי' הירידה בשינה בלילה באילנא דמותא כו' מטעם זה ולא מצד הלימוד שהרי לא זכר לימוד כלל שהרי הי' ביכולתו שלא ילמוד קודם אלא מטעם שתהא סמוכה למטתי דוקא ומטעם הנ\"ל וד\"ל."],[2100490465,"<h3>נוסח שני: הראיני את מראיך</h3>\n<b>הראיני</b><sup data-n=\"2603\">1</sup> את מראיך<sup data-n=\"2604\">*1</sup> השמיעיני את קולך כו' הנה יש ע\"ס מלמעלה למטה דאור ישר וע\"ס דאור חוזר ממטה למעלה ע\"י הפרסא המפסקת בבינה דאצי' בוקע האורות ועולים בבחי' אור חוזר ונעשה כח\"ב למטה כו'.\n<b>וביאור</b> זה באדם למטה הוא ע\"ד מ\"ש ואהבת<sup data-n=\"2605\">2</sup> את הוי' כו' בכל מאדך מאוד<sup data-n=\"2606\">3</sup> היא בלי גבול והיינו בחי' א\"ס והוא עד\"מ למעלה המשכת אור הכתר שמאיר באצי' שלזה הי' תכלית<sup data-n=\"2607\">4</sup> ירידת הנשמה שהיא צורך עלי' כו' כי הנה הנאצלים המה בחי' השתלשלות כי כללות השכל האנושי אינו נמשך מחכמה דעשי' ע\"י אמצעות הנפש דעשי' וחכמה דיצי' מקור לחכמה דעשי' הגם שהיא רוחנית יותר חכמה דבריאה מקור לחכמה דיצי' חכמה דאצי' מקור לחכמה דבריאה וא\"כ השכל אנושי אינו נמשך מן החכמה דאצי' ומפני זה נאמר כולם<sup data-n=\"2608\">5</sup> בחכמה עשית שלגבי המאציל הרי הוא מרומם לבדו ואינו בערך החו\"ב כו' ואצי' המה רק מדות הדבק במדותיו מה<sup data-n=\"2609\">6</sup> הוא רחום אבל המאציל הוא בחי' אליו<sup data-n=\"2610\">7</sup> ולא למדותיו כו' ועיקר התהוות אבי\"ע מן המאציל הוא רק מבחי' שמות שאין ערוך לגבי עצם המהות כמ\"ש בע\"ח<sup data-n=\"2611\">8</sup> דיו\"ד",[["2603","1","<b>הראיני</b>: הנחת המהרי\"ל. נעתק מכ\"י 1824 יט, ב. נמצא ג\"כ בכת\"י 80 עז, ב. 143 סא, א. 523 (בסופו). 1213 סא, א בכותרת: ביאור על התורה יונתי בחגוי הסלע מאדמו\"ר לבניו שי'.\nמאמר זה נדפס ג\"כ במאמרי אדה\"ז כתובים ח\"ב ע' קיט."],["2604","*1","<b>הראיני את מראיך</b>: שה\"ש ב, יד."],["2605","2","<b>ואהבת את ה' בכל מאדך</b>: ואתחנן ו, ה."],["2606","3","<b>מאד היא בלי גבול</b>: ראה ג\"כ תו\"א לט, ג."],["2607","4","<b>תכלית ירידת הנשמה לצורך עלי'</b>: ראה ספר המפתחות לאדה\"ז בערכו."],["2608","5","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["2609","6","<b>מה הוא רחום</b>: שבת קלג, ב. ירושלמי פאה רפ\"א."],["2610","7","<b>אליו ולא למדותיו</b>: הובא בפרדס של\"ב רפ\"ב בשם הספרי.\nע' בד\"ה להבין מ\"ש באוצ\"ח בהוספות ללקו\"ת (נא, ג) ודה\"ק שם ”כהובא בפרדס בסופו\" עכלה\"ט, ובכ\"מ אי' ”בספרי\", ובאמת לי' שם. ושם בפרדס של\"ב פ\"ב הביאו ”מספרי\", אבל אדמו\"ר בדיוק השמיט תי' ”מספרי\" מטעם הנ\"ל ע\"כ וכתב לשונו הטהור כהובא בפרדס."],["2611","8","<b>בע\"ח דיו\"ד מקור לאצי'</b>: ראה ע\"ח (שער סדר אצי') ש\"ג. שער (מב) דרושי אבי\"ע רפ\"א ורפ\"ב. (שער כללות אבי\"ע) ספ\"ד. שער ההקדמות דרוש ו' בההפרש שיש בין ד' עולמות אבי\"ע (שצה, א). לקו\"ש ח\"ו ע' 108 ואילך."]]],[2100490466,"מקור לאצי' והה' בבריא' וכו' וכמ\"ש הודו<sup data-n=\"2612\">9</sup> על ארץ ושמים כו' והממוצע לזה שמוריד השפע מן המאציל לנאצלים הוא אור הכתר והיינו מ\"ש כתר<sup data-n=\"2613\">10</sup> עליון כו' איהו שם מ\"ה דאיהו אורח אצילות ואיהו שקיו דאילנא כו' דהיינו חיות עולם האצילות שהוא ע\"י הסתר כי<sup data-n=\"2614\">11</sup> עמך מקור חיים כו' וזהו ענין ירידה צורך עלי' שזהו ההפרש בין מלאכים לנשמות. שמצד שהמלאכים<sup data-n=\"2615\">12</sup> הם למעלה ואין שום דבר מסתיר להם והן בבחי' השתלשלות אינן יכולים להמשיך אור חדש מאחר שאינם ממהותם ומפני זה הם נקראים עומדים כו' אבל למטה בישראל שנשפלו בגוף שמסתיר על קדושת הוי' וש\"ד המונעים הרי מסיבת הסתר זה שאינו מניח להתפשט למטה נעשה א\"ח ממטה למעלה בנקודת הלב ממעמקים קראתיך הוי' להיות קראתיך הוי' בע\"ס דאצי' הוא ע\"י עומקא דלבא תשובה עילאה כו' דמשכין לי' בחילא יתיר שעי\"ז אור חדש על ציון תאיר כו' והיינו בחי' בכל מאדך<sup data-n=\"2616\">13</sup> ובזה יובן למעלה ג\"כ שע\"י סיום הפרסא כו' שאינו מניח להתפשט למטה נעשה אור חוזר בבחי' בפני' נקודת הלב והיינו שמל' נעשה כתר וה\"ז כמשל מרוצת המים ע\"י הדבר המסתיר כו' וזהו בחי' מראה שע\"י הסתר של המראה נעשה אור חוזר ממטה למעלה לראות מה שמונח לאחורי' כו' וכמ\"כ המל' נק' מראה מצד זה כו'.\n<b>השמיעיני</b><sup data-n=\"2617\">14</sup> את קולך קלא<sup data-n=\"2618\">15</sup> דאורייתא שממשיכים עי\"ז אור א\"ס שמתלבש בתורה שהיא חכמה דאצי' כמ\"ש ותורה<sup data-n=\"2619\">16</sup> שם בישראל כו' והיינו מ\"ש כי<sup data-n=\"2620\">17</sup> קולך ערב עריבות ומתיקות בחי' תענוג דהיינו שממשיך בחי' תענוג עליון בתורה אז תתענג כו' היינו המשכת הכתר בחכמ' שבכתר הוא מקור התענוגים וזהו מ\"ש אני<sup data-n=\"2621\">18</sup> תורתך שעשעתי שהיא התענוג דשעשועים עליונים כמ\"ש ושעשוע<sup data-n=\"2622\">19</sup> יום יום או\"א, וזהו ההפרש שבין הלמוד שקודם התפלה בין הלימוד שאחר התפלה כי עיקר המשכת הכתר לחכמה הוא ע\"י התורה בהקדם תחלה בחי' בכל מאדך שהיא המשכת הכתר כנ\"ל אבל ע\"י התורה שקודם התפלה הוא רק המשכה מחכמה ששם שורש התורה בעצמה דאורייתא<sup data-n=\"2623\">20</sup> מחכמה נפקת (והיא נק' רעיתי<sup data-n=\"2624\">21</sup> ישראל שמפרנסין) וזהו שארז\"ל אבא<sup data-n=\"2625\">22</sup> בנימין אומר כו' על תפילתי שתהא סמוכה למטתי כי התורה צריכה להיות אחר התפלה כו' כדי שיהי' המשכת הכתר בחכמה כנ\"ל.",[["2612","9","<b>הודו על ארץ ושמים</b>: תהלים קמח, יג."],["2613","10","<b>כתר עליון</b>: תקו\"ז בהקדמה (פתח אלי')."],["2614","11","<b>כי עמך מקור חיים</b>: תהלים לו, י."],["2615","12","<b>שהמלאכים. . נקראים עומדים</b>: ראה תו\"א וישב ל, סע\"א. לקו\"ת בחוקותי מה, א. שלח לח, ד. סה\"מ תקס\"ד ע' קעז."],["2616","13","<b>בכל מאדך</b>: דברים ו, ה."],["2617","14","<b>השמיעיני את קולך</b>: שה\"ש ב, יד."],["2618","15","<b>קלא דאורייתא</b>: ראה זהר אחרי סא, א. פינחס ריג, א. סה\"מ תקס\"ג ח\"א ע' צט ואילך."],["2619","16","<b>ותורה שם בישראל</b>: תהלים עח, ה."],["2620","17","<b>כי קולך ערב</b>: שה\"ש שם."],["2621","18","<b>אני תורתך שעשעתי</b>: תהלים קיט, ע."],["2622","19","<b>ושעשוע יום יום</b>: משלי ח, ל."],["2623","20","<b>דאורייתא מחכמה נפקת</b>: זח\"ב פח, א. קכא, א."],["2624","21","<b>רעיתי ישראל שמפרנסין</b>: זח\"ג ז, א."],["2625","22","<b>אבא בנימין אומר כו' על תפילתי שתהא סמוכה למטתי</b>: ראה ברכות ה, ב."]]],[2100490467,"<b>ומראיך</b> נאוה אלו המצות כי הנה אמרו פושעי<sup data-n=\"2626\">23</sup> ישראל מלאים מצות וכו' וא\"כ מה הפרש יש בין צדיקים העושים מצות לרשעים. אך הוא כמו שאמרו משל לב'<sup data-n=\"2627\">24</sup> שצלאו פסחיהם כו' שזה ממשיך המשכה יותר עליונה מזה הגם שהמצוה אחת היא סוכה אתרוג כו' והיינו בחי' נאוה ויפת שהן ת\"ת דאימא<sup data-n=\"2628\">25</sup> כתר לז\"א ושליש התחתון דת\"ת דז\"א כתר לנוק' כי ת\"ת וכתר הכל ענין א' דהיינו כך ההתחברות ששניהם מקו האמצעי וכמו שהכתר<sup data-n=\"2629\">26</sup> ממוצע בין המאציל לנאצלים כך ת\"ת ממוצע כמו מאימא לז\"א ומז\"א לנוק' כי נה\"י היא עצם ההשפעה אבל הממוצע המוריד שפע באמצעותו הוא ת\"ת כו' וזהו שע\"י הראיני את מראיך דהיינו המשכ' הכתר בבחי' בכל מאודיך נעשה אח\"כ מראיך נאוה בחי' ת\"ת שנעשה כתר כו' ונק' מעש\"ט ומאירים וירא<sup data-n=\"2630\">27</sup> אלקים את האור כי טוב כו'.\n<b>וזהו</b> יונתי בחגוי הסלע מלכות נק' יונה ויורדת בחגוי הסלע בבי\"ע שהגם שהמל' היא סופא דכל דרגין מ\"מ מאחר שהוא בבחי' אצי' דאיהו<sup data-n=\"2631\">28</sup> וגרמוהי חד שאור א\"ס שורה בהם א\"כ ירידתה בבי\"ע צמצום גדול הוא ונעשה בחי' נקודה כו' שא''א לקבל גם בג\"ע העליון זיו השכינה אא\"כ נתצמצם תחילה בבחי' גבול נקוד' כו' וע\"פ העבודה למטה בשעת התפלה הוא התפשטות אהוי\"ר ואח\"כ כל היום בצמצום ולמחר נעשה התפשטות כו' והנה בחגוי הסלע היא הירידה לסתר המדריגה יותר למטה שהרי יש כמה ירידות שונות כמו ביום או בלילה ותתן<sup data-n=\"2632\">29</sup> טרף לביתה וד\"ל.",[["2626","23","<b>פושעי ישראל מלאים</b>: עירובין יט, א. חגיגה בסופה."],["2627","24","<b>לב' שצלאו פסחיהם</b>: נזיר כג, א."],["2628","25","<b>ת\"ת דאימא</b>: בכת\"י שם: כי הנה ת\"ת דאימא נעשה."],["2629","26","<b>שהכתר ממוצע</b>: ראה ע\"ח שער (מב) דרוש אבי\"ע פ\"א. לקו\"ת צו י, א. סידור שו, ב. סה\"מ ה'ת\"ש ע' 40."],["2630","27","<b>וירא אלקים את האור כי טוב</b>: בראשית א, ד."],["2631","28","<b>דאיהו וגרמוהי חד</b>: ת\"ז בהקדמה."],["2632","29","<b>ותתן טרף לביתה</b>: משלי לא, טו."]]],[2100490468,"<h3>ועשית ציץ</h3>\n<b>ועשית</b><sup data-n=\"2633\">1</sup> ציץ<sup data-n=\"2634\">2</sup>. הנה אית רצון ואית רצון אית רצון שהוא במדות ונלקח מטעם ודעת והוא ההסכם שאחרי ההתבוננות שנגמר בדעתו שראוי לאהוב כו' ונק' מצחא כמו מצח שהוא החופף ומכסה על המוחין רק כשהמוחין מתקצרין נעשה ההסכם כנודע וכו' ואית רצון למעלה למעלה שם יש ג\"כ מוחין ח\"ס שהוא מקור",[["2633","1","<b>ועשית ציץ</b>: הנחת המהרי\"ל. נעתק מכת\"י 80 עח, א. ונמצא ג\"כ בכת\"י 392 מג, ב.\nהנחת כ\"ק אדמו\"ר האמצעי נדפס בתו\"ח תצוה [הוצאת קה\"ת — תשס\"ג] שנו, א. שנט, א. שס, ג מגוכתי\"ק 1025 ח, א, בכותרת: שבת פ' תצוה. וראה שם בסוף הספר ברשימת הכת\"י.\nהנחה אחרת נדפס בתו\"א פג, א ואילך."],["2634","2","<b>ועשית ציץ</b>: תצוה כח, לו."]]],[2100490469,"החכמה הגלוי' וכמה דרגין צמצומים והשתלשלות דרך שערות כו' עד דאתפתחא לל\"ב<sup data-n=\"2635\">3</sup> שבילין כו' וכמבואר בפרד\"ס<sup data-n=\"2636\">4</sup> קבלת הגאונים שד' מוחין חב\"ד והדעת נחלקו לחו\"ג כל אחד כלול מח' בחי' הם ל\"ב.\n<b>והנה</b> גם מצחא<sup data-n=\"2637\">5</sup> חפיא על מוחא שהמוחין מתלבשים ומתעלמים ולא נשאר גילוי אלא ההסכם אלא שם נק' גילוי ע\"ק גלוי רצון דילי' כנודע זמן מנחת<sup data-n=\"2638\">6</sup> שבת רעוא דכל רעווין. והענין כי למטה בז\"א נק' המצח דינין ד' מאות בתי דינין כו' כי החימה מקו המסדים כנודע שהקטן מתכעס ומקפיד כו' בהתלבשות והתעלמות החכמה במצח שהוא ההסכם בלבד נעשה בחי' דין אבל למעלה במקורא דכולא גם בהתעלמות מוחא כו' סתימאה הנה גילוי המצח הוא רעווא דכל רעווין והי'<sup data-n=\"2639\">7</sup> הציץ על מצח אהרן ז\"א בעל שמונה בגדים כו' והציץ הוא המשכת מצחא דע\"ק למצחא דז\"א אסתכלותא דמצחא ש\"ע נהורין כו'.\n<b>והענין</b> כי המשכת מ\"ס לז\"א הוא דרך שערות ת\"ד שערות הם חלולים שיש בהם הבל דק שנמשך מחכמה ויש בהם קצת הארת חכמה שלכן אינה צומחת שערא<sup data-n=\"2640\">8</sup> דדיקנא עד ך' שנה שגדל כח החכמה כו' אך מ\"מ הוא צמצום גדול ואין ערוך כו', אבל אסתכלותא דמצחא הרי הוא מקום פנוי בלי שערות וכנראה בגשמיות שהמצח הוא יותר גבוה מהזקן והציץ דאהרן הי' אסתכלותא ממטה למעלה, ולכן למ\"ד<sup data-n=\"2641\">9</sup> והוי' מלמעלה הוי' שלפני האצילות הוי'<sup data-n=\"2642\">10</sup> הוי' פסיק טעמא קודש חכמה הוי' שבאצי' יו\"ד חכמה כו' דאילו הי' הכל בלמטה קודש חכמה להוי' לז\"א דאצי' אבל כשכתב קודש למ\"ד מלמטה לכן מלמטה מובן כוונת הציץ. אך הנה כ\"ד ועשית משה הוא העושה כו' כי יש תורת<sup data-n=\"2643\">11</sup> משה ותורה<sup data-n=\"2644\">12</sup> צוה לנו משה כי תורה צוה לנו משה מלמעלה למטה ומלמטה למעלה להמשיך בחי' חכמה ולדבקה בו בבחי' חכמה מחשבה דמחשבה כו' אך תורת משה עצמו הוא בחי' המשכת חכמה דהיינו התלבשות אור<sup data-n=\"2645\">13</sup> א\"ס להיות חכמה ועשיתם אותם עוסק",[["2635","3","<b>לל\"ב שבילין כו'</b>: ראה זהר (אד\"ר) נשא קכח, א. קלו, א."],["2636","4","<b>בפרדס קבלת הגאונים</b>: שער הנתיבות פ\"ב (הגאונים שמו להם שמות כפי אשר קבלו בפעולתם. . עד הנה הגיע מה שנמצא בביאור הנתיבות בדברי הגאונים)."],["2637","5","<b>מצחא חפיא על מוחא</b>: ראה זהר (אד\"ר) נשא קכח, ב."],["2638","6","<b>מנחת שבת רעוא דכל רעוין</b>: ראה זהר יתרו פח, ב. (אד\"ר) נשא קכט, ב. (אד\"ז) האזינו רפח, ב. רצג, סע\"א."],["2639","7","<b>והי' הציץ על מצח אהרן</b>: תצוה כח, לח."],["2640","8","<b>שערא. . עד כ' שנה</b>: ראה שו\"ע אדה\"ז הל' ברכת השחר סנ\"ג, סי\"א. לקו\"ת מסעי צב, ד."],["2641","9","<b>למ\"ד והוי' מלמעלה</b>: באוה\"ת תצוה ע' א'תרצ מציין: פ\"ו דשבת דס\"ג ע\"א [צ\"ל ע\"ב] ופ\"ק דסוכה דף ה' ע\"א. ושם הלשון: יו\"ד ה\"א למעלה וקודש למ\"ד למטה. וראה גם ירושלמי יומא פ\"ד, ה\"א. מגילה פ\"א, ה\"ט."],["2642","10","<b>הוי' הוי' פסיק טעמא</b>: תשא לד, ו. ראה זהר (אד\"ר) נשא קלח, רע\"א."],["2643","11","<b>תורת משה</b>: ראה יהושע ח, לא. לב. כג, ו. ועוד."],["2644","12","<b>ותורה צוה לנו משה</b>: ברכה לג, ד."],["2645","13","<b>אור א\"ס להיות חכמה</b>: ראה תניא פל\"ה בהג\"ה."]]],[2100490470,"בתורה<sup data-n=\"2646\">14</sup> לשמה לשם הוי' להיות בחי' תורה הגם שיש תרי\"ג<sup data-n=\"2647\">15</sup> אחרין כו' מ\"מ הגלוי הוא מחכמה ולמטה מחכמה<sup data-n=\"2648\">16</sup> נפקת כו'.\n<b>אך</b> חכמה זו הגלוי' נמשך ממוחא סתימאה דא\"א ששם בחי' ואנחנו<sup data-n=\"2649\">17</sup> מה בחי' בטול שם היא המשכות א\"ס ממש ודברי<sup data-n=\"2650\">18</sup> אשר שמתי בפיך דבר הוי' ממש וע\"כ אחר ולעבדו<sup data-n=\"2651\">19</sup> בכל נפשיכם נאמר ונתתי כו' כי היינו ע\"י מס\"נ<sup data-n=\"2652\">20</sup> וקבלו היהודים כו' ובבחי' בטול זה אמר המגיד<sup data-n=\"2653\">21</sup> להב\"י אני המשנה המדבר בפיך והשגת רוה\"ק שלו הי' ג\"כ עד\"ז שהוא עצמו הי' מדבר קול<sup data-n=\"2654\">22</sup> דודי דופק היינו בקרבו ממש ודברי מוסר שאמר לו הכל הוא עצמו הי' מדבר אלא דרך התלבשות בקולו והוא הי' שומע את קולו ועד\"ז כל השגת רוה\"ק<sup data-n=\"2655\">23</sup> רוח הדובר בו וכן השגת הנביאים המלאך הדובר בו ממש ולכן רב יהודה הי' פטור מהתפלה<sup data-n=\"2656\">24</sup> שלמד בבחי' בטול זה. וע\"י בחי' משה נמשך הציץ לרצון להם לפני ה' מבחי' הוי' אסתכלותא דע\"ק במצח אהרן הוא ז\"א ולכן ונשא<sup data-n=\"2657\">25</sup> אהרן את עון כו' בחי' נושא עון בי\"ג מדה\"ר נמשך ממוחא סתימאה אלא שהי\"ג מד\"ר י\"ג תקוני דקנא נמשכו דרך שערות (ומ\"מ בבחי' אחת הם יותר מעולים שהן פנימי' משא\"כ דרך המצחא הוא בחי' חיצונית) ומצחא דע\"ק רעווא דכל רעווין בק\"ו ושרש כו'. ומעלות משה להכרית זרעו של עמלק<sup data-n=\"2658\">26</sup> כי<sup data-n=\"2659\">27</sup> לא כאברהם שיצא ממנו כו' היינו בחג\"ת דז\"א כי בז\"ת יש יניקה ואחיזה כו' משא\"כ בג' ראשונות בחי' משה נק' יין<sup data-n=\"2660\">28</sup> המשומר בענביו משומר ממגע נכרי שאין שם נגיעה ואחיזה כו'.\n&lt;קמג&gt;",[["2646","14","<b>בתורה לשמה</b>: ראה אבות רפ\"ו. לקו\"ת שלח מז, ג."],["2647","15","<b>תרי\"ג ארחין</b>: ראה זהר (אד\"ר) נשא קכט, א. קלו, א."],["2648","16","<b>מחכמה נפקת</b>: זהר בשלח סב, א. יתרו פה, א. (רע\"מ) משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["2649","17","<b>ואנחנו מה</b>: ראה בשלח טז, ז."],["2650","18","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא."],["2651","19","<b>ולעבדו בכל נפשיכם כו' ונתתי</b>: עקב יא, יג."],["2652","20","<b>מס\"נ וקבלו היהודים</b>: אסתר ט, כז. וראה לעיל ד\"ה וקבל היהודים. תו\"א צז, סע\"ד."],["2653","21","<b>המגיד להב\"י אני המשנה המדברת</b>: ראה מגיד משרים פ' ויחי, בא, תשא, ועוד (ירושלים תש\"ך מה, ב. נג, ב. סט, ב)."],["2654","22","<b>קול דודי דופק</b>: שה\"ש ה, ב."],["2655","23","<b>רוה\"ק רוח הדובר בו</b>: ראה תניא פל\"ד."],["2656","24","<b>ר' יהודה היה פטור מתפלה</b>: ראה ר\"ה לה, א."],["2657","25","<b>ונשא אהרן את עון</b>: תצוה כח, לח."],["2658","26","<b>להכרית זרעו של עמלק</b>: ראה דברים כה, יז."],["2659","27","<b>כי לא כאברהם שיצא ממנו</b>: ראה פסחים נו, א."],["2660","28","<b>יין המשומר בענביו</b>: ראה ברכות לב, ב."]]]]});
